local config = {
  ui_story_5075_50750100_1_dialog_content = "(After surviving the Shadowind's long and perilous journey across the sea, we finally arrived on the shores of Longzhou.)",
  ui_story_5075_50750100_2_dialog_content = "(Yuebai and Zhong Xu had a delivery to make on behalf of their guild, so they had to stay a few more days.)",
  ui_story_5075_50750100_3_dialog_content = "(The Lin Guild kindly invited us to travel with them...)",
  ui_story_5075_50750100_4_dialog_content = "(But as Astra's official envoy, I chose to follow Dantang and Jiu to the Ji Kingdom's capital first.)",
  ui_story_5075_50750100_5_dialog_content = "Ole Dragon Maiden, to you I pray.",
  ui_story_5075_50750100_6_dialog_content = "Please don't let the rain descend. Tomorrow's dawn, dried tofu will be my offering to send—",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>Splash.</color>",
  ui_story_5075_50750100_8_dialog_content = "Urgh!",
  ui_story_5075_50750100_9_dialog_content = "Look out, PlayerName!",
  ui_story_5075_50750100_10_dialog_content = "I know you are intrigued by Ji's landscape, but this riverboat is not the Shadowind.",
  ui_story_5075_50750100_11_dialog_content = "Please try not to be so mesmerized as to fall into the water.",
  ui_story_5075_50750100_12_dialog_content = "It was not easy for me to get a cherished emissary such as you all the way from Astra.",
  ui_story_5075_50750100_13_dialog_content = "You've crossed the ocean and survived Eclipsite and pirate assaults unscathed.",
  ui_story_5075_50750100_14_dialog_content = "I couldn't bear the blame and guilt if you should drown mere steps away from the palace.",
  ui_story_5075_50750100_15_dialog_content = "Haha... Sorry for worrying you like that.",
  ui_story_5075_50750100_16_dialog_content = "I got so caught up listening to that boatman's song that I forgot I was on a boat myself.",
  ui_story_5075_50750100_17_dialog_content = "I've been hearing songs like that ever since the harbor.",
  ui_story_5075_50750100_18_dialog_content = "The notes are so airy and quick, and it sounds like the lyrics are in a local language. What are they singing about?",
  ui_story_5075_50750100_19_dialog_content = "That is a rowing song.",
  ui_story_5075_50750100_20_dialog_content = "Ji is teeming with lakes and rivers that provide a living for the people. Naturally, that makes boatmen and fishermen prevalent.",
  ui_story_5075_50750100_21_dialog_content = "In time, they developed songs for fishing and sailing.",
  ui_story_5075_50750100_22_dialog_content = "Lush be the mountains, clear be the water. Flowers be blooming, willows be elegant. That's what they sing about.",
  ui_story_5075_50750100_23_dialog_content = "And the tune you just heard is one that seeks blessing from the deities.",
  ui_story_5075_50750100_24_dialog_content = "\"Dragon Maiden, please ensure clear skies and smooth sailing.\"",
  ui_story_5075_50750100_25_dialog_content = "\"I shall offer you delicious dried tofu after I reach home safely.\"",
  ui_story_5075_50750100_26_dialog_content = "That is the gist of it.",
  ui_story_5075_50750100_27_dialog_content = "Oh, the Dragon Maiden!",
  ui_story_5075_50750100_28_dialog_content = "Isn't <color=#FFB400>Dragon Maiden Over Turbulent Seas</color> the name of that dance you taught Vice in Twin Pavilions Bay?",
  ui_story_5075_50750100_29_dialog_content = "I remember you saying that the coastal people of Longzhou really revere the Dragon Maiden.",
  ui_story_5075_50750100_30_dialog_content = "... But do deities really like dried tofu that much?",
  ui_story_5075_50750100_31_dialog_content = "Well, not quite. The offering in the folksong actually varies.",
  ui_story_5075_50750100_32_dialog_content = "The Dragon Maiden doesn't ask for offerings, but folks still add them to the song to show their appreciation.",
  ui_story_5075_50750100_33_dialog_content = "That man sang about dried tofu probably because that's what he happened to have at home.",
  ui_story_5075_50750100_34_dialog_content = "And she's okay with that? What a curious deity.",
  ui_story_5075_50750100_35_dialog_content = "I thought I learned a lot about Longzhou back in Twin Pavilions Bay...",
  ui_story_5075_50750100_36_dialog_content = "But now that I'm actually here, it feels like I'm learning something new with every step that I take.",
  ui_story_5075_50750100_37_dialog_content = "I just wish Vice and Carleen were here to see it too.",
  ui_story_5075_50750100_38_dialog_content = "That may happen sooner than you think.",
  ui_story_5075_50750100_39_dialog_content = "That's right! After all, our mission is to strengthen the relations between our two lands.",
  ui_story_5075_50750100_40_dialog_content = "If everything goes smoothly, maybe my friends from Astra will be able to visit Longzhou and see it all for themselves!",
  ui_story_5075_50750100_41_dialog_content = "As well as exchange strategies and technology for opposing the Eclipsites.",
  ui_story_5075_50750100_42_dialog_content = "Communication and cooperation will help facilitate peace for all.",
  ui_story_5075_50750100_43_dialog_content = "I think we must count on you as the emissary to make that vision real.",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>(Thud)</color>",
  ui_story_5075_50750100_45_dialog_content = "We've made shore, and the destination is ahead, Your Highness and PlayerName.",
  ui_story_5075_50750100_46_dialog_content = "We have to disembark here to get into the city.",
  ui_story_5075_50750100_47_dialog_content = "Wait for a second, PlayerName.",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>Dantang gets off the ship, smiles and bows slightly.</color>",
  ui_story_5075_50750100_49_dialog_content = "I am Princess Zhuohua, tasked by the King of Ji to be the ambassador to Astra.",
  ui_story_5075_50750100_50_dialog_content = "Your Excellency has accepted my invitation and journeyed far to Longzhou.",
  ui_story_5075_50750100_51_dialog_content = "For that, please allow me to once again express my gratitude and appreciation.",
  ui_story_5075_50750100_52_dialog_content = "Welcome to the <color=#FFB400>capital of Ji</color>:",
  ui_story_5075_50750100_53_dialog_content = "<color=#FFB400>Haojin</color>.",
  ui_story_5075_50750100_54_dialog_content = "Don't mention it, and thanks for having me!",
  ui_story_5075_50750100_55_dialog_content = "Now it's time for me to hold up my end of the bargain as Astra's envoy.",
  ui_story_5075_50750100_56_dialog_content = "Your Highness, the royal attendants have come. We must return to the palace and the king.",
  ui_story_5075_50750100_57_dialog_content = "Well then, PlayerName...",
  ui_story_5075_50750100_58_dialog_content = "Greetings, Your Highness, esteemed emissary.",
  ui_story_5075_50750100_59_dialog_content = "I am the steward in charge of the Royal Guesthouse, and it's such an honor to have you as our guest, esteemed emissary.",
  ui_story_5075_50750100_60_dialog_content = "The guesthouse will handle all daily activities and security arrangements for you while you are in Ji.",
  ui_story_5075_50750100_61_dialog_content = "It seems we must part for now.",
  ui_story_5075_50750100_62_dialog_content = "Once I am done with official business and Yuebai returns in two days, we shall reconvene. I will take you on a tour of Haojin.",
  ui_story_5075_50750100_63_dialog_content = "The Spring Festival will be upon us soon. It is the most celebrated time in Longzhou.",
  ui_story_5075_50750100_64_dialog_content = "The streets will be dotted with colorful lanterns, dancing dragons, as well as fairs featuring myriad snack vendors.",
  ui_story_5075_50750100_65_dialog_content = "It is certain to leave an everlasting impression on you.",
  ui_story_5075_50750100_66_dialog_content = "Looking forward to it!",
  ui_story_5075_50750100_67_dialog_content = "(Little did we know that such a simple plan would end up full of complications...)",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>Royal Guesthouse</color>",
  ui_story_5075_50750100_69_dialog_content = "Your Excellency, please have some tea.",
  ui_story_5075_50750100_70_dialog_content = "It's amethyst bamboo tea, brewed with fresh spring water just brought down from the mountain, offering an unparalleled pure and sweet taste.",
  ui_story_5075_50750100_71_dialog_content = "It's delicious! Thank you.",
  ui_story_5075_50750100_72_dialog_content = "Esteemed emissary, I'm not sure about your preferences, so I've prepared a variety of snacks.",
  ui_story_5075_50750100_73_dialog_content = "Here are golden cream crisps, sevenfold cakes, and jade dew balls... If you fancy something else, just let us know.",
  ui_story_5075_50750100_74_dialog_content = "That's quite a variety of snacks!",
  ui_story_5075_50750100_75_dialog_content = "Esteemed emissary, let me help you change and bathe.",
  ui_story_5075_50750100_76_dialog_content = "N-N-No thanks! I can do that myself!",
  ui_story_5075_50750100_77_dialog_content = "Y-You guys sure know how to take care of guests...",
  ui_story_5075_50750100_78_dialog_content = "It makes me feel pretty nervous. I don't want to ruin Astra's image by doing something wrong, you know?",
  ui_story_5075_50750100_79_dialog_content = "We should be going to the palace tomorrow to discuss official business, so I don't think I'll be here for very long.",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>Day Two</color>",
  ui_story_5075_50750100_81_dialog_content = "Someone's coming! Are they here to call me over to the palace?",
  ui_story_5075_50750100_82_dialog_content = "Esteemed emissary, our king is thrilled to know you've come all the way from overseas.",
  ui_story_5075_50750100_83_dialog_content = "So he sent me to give you his welcoming gifts, including rare tea and fruits, luxurious outfits and silk, as well as various fragrances.",
  ui_story_5075_50750100_84_dialog_content = "Are these really all for me? But...",
  ui_story_5075_50750100_85_dialog_content = "Now that the gifts have been delivered, I'll excuse myself.",
  ui_story_5075_50750100_86_dialog_content = "May you enjoy good health during your stay in Ji so as to alleviate Princess Zhuohua's anxiety, Your Excellency.",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>Day Three</color>",
  ui_story_5075_50750100_88_dialog_content = "... Why haven't I been called to the palace yet?",
  ui_story_5075_50750100_89_dialog_content = "Are you feeling bored, Your Excellency? How about some opera?",
  ui_story_5075_50750100_90_dialog_content = "If you're into it, I can get some top-notch performers to put on a show for you.",
  ui_story_5075_50750100_91_dialog_content = "That's not what I meant...",
  ui_story_5075_50750100_92_dialog_content = "Not your thing? How about some Pingtan or street shows?",
  ui_story_5075_50750100_93_dialog_content = "If none of that interests you, you could try out cricket fights, quail fights, and plenty of other amusements in Haojin.",
  ui_story_5075_50750100_94_dialog_content = "No, I really don't need anything like that right now...",
  ui_story_5075_50750100_95_dialog_content = "I just want to go meet the ruler of the Ji Kingdom!",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>Day Four</color>",
  ui_story_5075_50750100_97_dialog_content = "Ah, free at last.",
  ui_story_5075_50750100_98_dialog_content = "What is this place? With all these signs, I doubt the king lives around here...",
  ui_story_5075_50750100_99_dialog_content = "Esteemed emissary, you seem to have been skipping meals for the last couple of days, perhaps due to boredom.",
  ui_story_5075_50750100_100_dialog_content = "So, I talked to the steward to set up a fun schedule for you.",
  ui_story_5075_50750100_101_dialog_content = "For first-timers in Haojin, the Dragon Maiden Temple in the South Mountains is a must-see.",
  ui_story_5075_50750100_102_dialog_content = "Besides the magnificent scenery of towering peaks and intricate rocks, rumors have it that the legendary Dragon Maiden was once sighted here.",
  ui_story_5075_50750100_103_dialog_content = "Feel free to enjoy the scenery or offer your prayers. All the others have been cleared out, so no one will disrupt you.",
  ui_story_5075_50750100_104_dialog_content = "Huh? You made people leave just for me? No wonder this place is so deserted...",
  ui_story_5075_50750100_105_dialog_content = "You really didn't have to go to all this trouble. I'm not some big hotshot or anything, and I definitely don't mind being a part of the crowd.",
  ui_story_5075_50750100_106_dialog_content = "You jest, esteemed emissary. You're Ji's honored guest, and we are dedicated to serving you with our utmost efforts.",
  ui_story_5075_50750100_107_dialog_content = "Feel free to go ahead and enjoy yourself.",
  ui_story_5075_50750100_108_dialog_content = "(Fine... I'm already here, so I may as well take a look around.)",
  ui_story_5075_50750100_109_dialog_content = "(There's a seriously imposing statue standing at the center of the main hall. Is that the Dragon Maiden?)",
  ui_story_5075_50750100_110_dialog_content = "(There are all kinds of offerings like Dantang said, everything from fruits and vegetables to tea and snacks...)",
  ui_story_5075_50750100_111_dialog_content = "Huh? Is someone else here too?",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5075_50750100_113_dialog_content = "I wonder which handmaiden dropped this... Or does it belong to that stranger I just spotted?",
  ui_story_5075_50750100_114_dialog_content = "Esteemed emissary...",
  ui_story_5075_50750100_115_dialog_content = "I've inspected the place multiple times. There's no one else in the temple but you.",
  ui_story_5075_50750100_116_dialog_content = "But I'm positive I saw someone here just now. It looks like they dropped something too...",
  ui_story_5075_50750100_117_dialog_content = "I didn't see any... Huh?",
  ui_story_5075_50750100_118_dialog_content = "Where did all the offerings go?",
  ui_story_5075_50750100_119_dialog_content = "H-How could this...",
  ui_story_5075_50750100_120_dialog_content = "Please accept our apologies, Your Excellency. It was our oversight to have let a thief slip in.",
  ui_story_5075_50750100_121_dialog_content = "Wicked spirits wouldn't dare to get close to the Dragon Maiden Temple. It's gotta be those tricky fiendlings again...",
  ui_story_5075_50750100_122_dialog_content = "What's the matter with fiendlings?",
  ui_story_5075_50750100_123_dialog_content = "It's no big deal, not worth your concern, esteemed emissary.",
  ui_story_5075_50750100_124_dialog_content = "It was our negligence. Please, go downhill with the guards first. I'll report this to the steward.",
  ui_story_5075_50750100_125_dialog_content = "Guards! Escort the emissary back to the guesthouse!",
  ui_story_5075_50750100_126_dialog_content = "Affirmative!",
  ui_story_5075_50750100_127_dialog_content = "W-Wait, everyone... At least let me get a few more breaths of fresh air—",
  ui_story_5075_50750100_128_dialog_content = "(The next few days were no different than before.)",
  ui_story_5075_50750100_129_dialog_content = "(I ate, I slept, and I enjoyed myself... They took care of me in every possible way, and guards escorted me wherever I went.)",
  ui_story_5075_50750100_130_dialog_content = "(But no one would give me a straight answer whenever I asked about going to the palace.)",
  ui_story_5075_50750100_131_dialog_content = "Nothing's going to get done at this rate. I should just go talk to the steward myself.",
  ui_story_5075_50750100_132_dialog_content = "I need to secure an audience with the king, or else Dantang and I will never complete our mission.",
  ui_story_5075_50750100_133_dialog_content = "Hopefully there won't be any guards getting in my way...",
  ui_story_5075_50750100_134_dialog_content = "... Princess Zhuohua.",
  ui_story_5075_50750100_135_dialog_content = "(Huh? Did someone just bring up Dantang?)",
  ui_story_5075_50750100_136_dialog_content = "Is the news for real?",
  ui_story_5075_50750100_137_dialog_content = "Haha, you know, there's no smoke without fire.",
  ui_story_5075_50750100_138_dialog_content = "I heard our crown prince is head over heels for that princess. He only has eyes for her.",
  ui_story_5075_50750100_139_dialog_content = "The princess hasn't agreed yet. But maids in the palace say the king intends to arrange a marriage for them.",
  ui_story_5075_50750100_140_dialog_content = "That makes sense! No wonder the palace has been bustling, too busy to care about anything else.",
  ui_story_5075_50750100_141_dialog_content = "Oh my, the duckling has truly turned into a swan! If I remember it correctly, wasn't she here to offset a debt?",
  ui_story_5075_50750100_142_dialog_content = "?!",
  ui_story_5075_50750100_143_dialog_content = "Excuse me, but were you just talking about—",
  ui_story_5075_50750100_144_dialog_content = "Oh look, the esteemed emissary. I was looking for you everywhere.",
  ui_story_5075_50750100_145_dialog_content = "The king has issued a decree, specially inviting you to attend today's grand banquet and share your insights on foreign affairs.",
  ui_story_5075_50750100_146_dialog_content = "Please go and get ready now, then I'll lead you to the palace.",
  ui_story_5075_50750100_147_dialog_content = "You mean right now? Why didn't anyone tell me sooner?",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>Jade towers, gates of gold, majestic and grand. Melodies in harmony, echoing on the imperial land.</color>",
  ui_story_5075_50750201_2_dialog_content = "Emissary from Astra, please enter the royal court!",
  ui_story_5075_50750201_3_dialog_content = "Turns out folks from the western lands do look different from us.",
  ui_story_5075_50750201_4_dialog_content = "The attire's quite novel, although the tight-fit tailoring does cut down on elegance.",
  ui_story_5075_50750201_5_dialog_content = "Rumor has it he's a Caelestite, quite a rarity even in the western lands.",
  ui_story_5075_50750201_6_dialog_content = "(They all seem to be talking about me.)",
  ui_story_5075_50750201_7_dialog_content = "(Good thing Dantang's also here. I hope no one has been picking on her. She does appear rather tense.)",
  ui_story_5075_50750201_8_dialog_content = "You're PlayerName, right? Word has it that you've done a lot to help recover the sea routes between the two continents.",
  ui_story_5075_50750201_9_dialog_content = "Meeting you now, I can tell you're indeed a young talent.",
  ui_story_5075_50750201_10_dialog_content = "You praise me too much. The Shadowind was only able to safely return thanks to everyone's concerted efforts...",
  ui_story_5075_50750201_11_dialog_content = "No need to be humble. Someone, serve our guest some tea.",
  ui_story_5075_50750201_12_dialog_content = "It's quite rare to meet a traveler from across the sea. How about sharing some tales of foreign lands with us?",
  ui_story_5075_50750201_13_dialog_content = "I've heard there are steel giants skilled in warfare on your continent.",
  ui_story_5075_50750201_14_dialog_content = "Those giants, controlled by soldiers inside them with thoughts alone, have eyes bright like lightning and the strength to move mountains. Is that true?",
  ui_story_5075_50750201_X14_option_content = "That's too much...",
  ui_story_5075_50750201_15_dialog_content = "That's... a bit of an exaggeration.",
  ui_story_5075_50750201_16_dialog_content = "Astra's technology isn't quite at that level just yet.",
  ui_story_5075_50750201_17_dialog_content = "While it's true that we have Colossi, they aren't the incredible weapons you're describing.",
  ui_story_5075_50750201_18_dialog_content = "Not to mention there aren't many of them left, and only a few people in the world can control them.",
  ui_story_5075_50750201_X18_option_content = "Maybe in the future, though.",
  ui_story_5075_50750201_X19_dialog_content = "Although such a powerful force does not exist now...",
  ui_story_5075_50750201_X20_dialog_content = "With the military tech-savvy Illumina Federation and the ritual magic-proficient Lumopolis around...",
  ui_story_5075_50750201_X21_dialog_content = "Perhaps Astra will create the giants you described one day.",
  ui_story_5075_50750201_X22_dialog_content = "Oh, so you're saying there's no such thing.",
  ui_story_5075_50750201_19_dialog_content = "Then how do your soldiers confront the wicked spirits in battle?",
  ui_story_5075_50750201_20_dialog_content = "Our militaries research and produce all kinds of weapons and armor to combat them.",
  ui_story_5075_50750201_21_dialog_content = "Combined with Luminatics, they allow us to fend off the Eclipsites... or \"wicked spirits,\" as you call them.",
  ui_story_5075_50750201_22_dialog_content = "So, you're still relying on physical strength in combat, huh?",
  ui_story_5075_50750201_23_dialog_content = "Well then, on your expansive continent, are there immortality techniques or ways to ascend?",
  ui_story_5075_50750201_24_dialog_content = "I, uh... I don't think so.",
  ui_story_5075_50750201_25_dialog_content = "We have a few long-lived people in our land. In fact, the queen of Northland is famous for her eternally-youthful appearance.",
  ui_story_5075_50750201_26_dialog_content = "But as far as true immortals go... I'm afraid I haven't heard of any.",
  ui_story_5075_50750201_27_dialog_content = "Hmm, it seems that despite the sea in between, the other continent isn't much different from our Longzhou.",
  ui_story_5075_50750201_28_dialog_content = "Not entirely true—",
  ui_story_5075_50750201_29_dialog_content = "Ahem.",
  ui_story_5075_50750201_30_dialog_content = "(Don't be rash.)",
  ui_story_5075_50750201_31_dialog_content = "...",
  ui_story_5075_50750201_32_dialog_content = "More interestingly, I've heard that, you've got some peculiar skills.",
  ui_story_5075_50750201_33_dialog_content = "And that they can amplify the strength of Force Arts multiple times.",
  ui_story_5075_50750201_34_dialog_content = "How about I appoint you to a nominal position so that you can stay in Ji?",
  ui_story_5075_50750201_35_dialog_content = "You've seen Haojin's beauty firsthand over the last few days.",
  ui_story_5075_50750201_36_dialog_content = "Our Ji, blessed with abundant land and sea, flourishing in all aspects, is just like a paradise on earth.",
  ui_story_5075_50750201_37_dialog_content = "Isn't it way better than that land overrun by wicked spirits?",
  ui_story_5075_50750201_38_dialog_content = "Hmm, I appreciate the kind gesture, but Astra's my home. Sooner or later, I have to go back.",
  ui_story_5075_50750201_39_dialog_content = "Not only that, but I'm not here for my own pleasure. I came as an emissary in order to promote better relations between our lands.",
  ui_story_5075_50750201_40_dialog_content = "Back in Astra, we've developed all kinds of effective Eclipsite countermeasures. Whether it's Illumina or Lumopolis—",
  ui_story_5075_50750201_41_dialog_content = "Well, you've got a point. But let the maritime trade offices handle such minor matters.",
  ui_story_5075_50750201_42_dialog_content = "Discussing these matters now would be a waste of such a beautiful moment.",
  ui_story_5075_50750201_43_dialog_content = "The Spring Festival is approaching, and Ji teems with prosperity and wonders. We should celebrate together.",
  ui_story_5075_50750201_44_dialog_content = "Everyone, raise your glass!",
  ui_story_5075_50750201_45_dialog_content = "But—",
  ui_story_5075_50750201_46_dialog_content = "Here's to the king's longevity and everlasting rule!",
  ui_story_5075_50750201_47_dialog_content = "Here's to the abundance and prosperity of the Ji Kingdom!",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50750201_49_dialog_content = "It's an earthquake!",
  ui_story_5075_50750201_50_dialog_content = "Hurry, protect the king!",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>Tables and chairs shake, dishes clatter and fall, and the tremors take a while to completely subside.</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>The grand hall, lively a moment ago, is now a mess, filled with the sounds of people rushing around and shouting orders.</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>The officials, who were full of spirit just moments ago, now look quite disheveled.</color>",
  ui_story_5075_50750201_54_dialog_content = "Phew, that was close, but I just got the good news that the townspeople are safe.",
  ui_story_5075_50750201_55_dialog_content = "Not what I planned, but this is where the banquet ends today.",
  ui_story_5075_50750201_56_dialog_content = "Dantang?",
  ui_story_5075_50750201_57_dialog_content = "Come, PlayerName. Let us go somewhere quieter.",
  ui_story_5075_50750201_58_dialog_content = "I think my headband got caught on something...",
  ui_story_5075_50750201_59_dialog_content = "Sorry, Dantang, but could you give me a hand?",
  ui_story_5075_50750201_60_dialog_content = "The flowers on this tree are so pretty. I don't want to accidentally hurt something so precious.",
  ui_story_5075_50750201_61_dialog_content = "Hee, these plum blossoms are hardly precious but quite ubiquitous. You just may be the first one to treat them with such delicacy.",
  ui_story_5075_50750201_62_dialog_content = "Please remain still and let me free you.",
  ui_story_5075_50750201_63_dialog_content = "...",
  ui_story_5075_50750201_64_dialog_content = "Okay, it is done.",
  ui_story_5075_50750201_65_dialog_content = "Have you been finding your stay in the royal guesthouse accommodating these few days?",
  ui_story_5075_50750201_66_dialog_content = "Yeah, but it feels like everyone is going a little overboard with their hospitality.",
  ui_story_5075_50750201_67_dialog_content = "They won't even let me pour myself a cup of water. It makes me feel like I'm really valuable or something.",
  ui_story_5075_50750201_68_dialog_content = "Isn't that the case?",
  ui_story_5075_50750201_69_dialog_content = "Please don't joke about it.",
  ui_story_5075_50750201_70_dialog_content = "I did my best not to make a fool of myself. That wasn't easy for me, you know.",
  ui_story_5075_50750201_71_dialog_content = "I didn't do a good job as the emissary either.",
  ui_story_5075_50750201_72_dialog_content = "Getting into the palace seems impossible. I haven't even gotten the chance to introduce Astra, much less negotiate better ties.",
  ui_story_5075_50750201_73_dialog_content = "... My apologies, PlayerName.",
  ui_story_5075_50750201_74_dialog_content = "That was negligence on my part.",
  ui_story_5075_50750201_75_dialog_content = "I invited you to come all this way here yet failed to provide a forum for you.",
  ui_story_5075_50750201_76_dialog_content = "It's not your fault, Dantang. If I had done a better job of preparing myself, I wouldn't be floundering like this.",
  ui_story_5075_50750201_77_dialog_content = "No, it is my fault...",
  ui_story_5075_50750201_78_dialog_content = "*snickers*",
  ui_story_5075_50750201_79_dialog_content = "Hahaha... All this apologizing between friends is kind of funny, isn't it?",
  ui_story_5075_50750201_80_dialog_content = "Well, there's no use worrying about the past. I'll go back and get ready for my next trip to the palace, and I promise I'll do better then.",
  ui_story_5075_50750201_81_dialog_content = "... Oh, and one more thing.",
  ui_story_5075_50750201_82_dialog_content = "Yes?",
  ui_story_5075_50750201_83_dialog_content = "Before I came, I overheard two of the maids talking... They said something about marriage plans between you and the prince of Ji?",
  ui_story_5075_50750201_84_dialog_content = "And they didn't speak about you in a nice tone, saying you're here as collateral.",
  ui_story_5075_50750201_85_dialog_content = "Which is why I have to ask: are they treating you well over here?",
  ui_story_5075_50750201_86_dialog_content = "Well...",
  ui_story_5075_50750201_87_dialog_content = "I-I'm fine.",
  ui_story_5075_50750201_88_dialog_content = "Actually, I've the same rumors before, but I didn't expect you to hear them too.",
  ui_story_5075_50750201_89_dialog_content = "That is the king's intent, but I have made my position clear, and he cannot force me.",
  ui_story_5075_50750201_X89_dialog_content = "About that... It is true that I am here because of a loan to Ye.",
  ui_story_5075_50750201_X90_dialog_content = "However, it is not a matter for the servants to judge. I will deal with the gossipers later.",
  ui_story_5075_50750201_X91_dialog_content = "Dantang...",
  ui_story_5075_50750201_90_dialog_content = "Do not worry. I have been here long enough to garner sufficient support.",
  ui_story_5075_50750201_91_dialog_content = "No one in the whole palace has yet to defy me out in the open.",
  ui_story_5075_50750201_92_dialog_content = "That includes the prince, right?",
  ui_story_5075_50750201_93_dialog_content = "Of course! Not to mention the crown prince is just a...",
  ui_story_5075_50750201_94_dialog_content = "Dantang! Are you all right, Dantang?",
  ui_story_5075_50750201_95_dialog_content = "... Crown Prince? You should be resting in your chamber this late at night.",
  ui_story_5075_50750201_96_dialog_content = "I was worried about you.",
  ui_story_5075_50750201_97_dialog_content = "That earthquake was pretty strong. Are you alright? Any injuries? Scared?",
  ui_story_5075_50750201_98_dialog_content = "*sighs* I am fine and unhurt, don't you worry.",
  ui_story_5075_50750201_99_dialog_content = "But the king will punish you again if he finds out you left without any guard in tow.",
  ui_story_5075_50750201_100_dialog_content = "I'm grown now! I-I'm not scared of punishment!",
  ui_story_5075_50750201_101_dialog_content = "Besides, as a real man, I must be there for my fiancée in times of crisis!",
  ui_story_5075_50750201_102_dialog_content = "Pfft—",
  ui_story_5075_50750201_103_dialog_content = "How can you say that—",
  ui_story_5075_50750201_104_dialog_content = "Oh? A real man? Clearly, I'm missing something.",
  ui_story_5075_50750201_105_dialog_content = "Your study load is currently fit for that of a child, but since you're already a real man, well...",
  ui_story_5075_50750201_106_dialog_content = "I'll have to tell the teacher that your homework is too light and we need to double it from now on!",
  ui_story_5075_50750201_107_dialog_content = "No... Please don't! I don't wanna be a man anymore!",
  ui_story_5075_50750201_108_dialog_content = "I-I may have high aspirations, but my body and mind aren't fully developed for such a burden!",
  ui_story_5075_50750201_109_dialog_content = "... Had enough for today. I shall return to my chambers to rest!",
  ui_story_5075_50750201_110_dialog_content = "Dantang, let's play together again tomorrow!",
  ui_story_5075_50750201_111_dialog_content = "We hired a new chef who's an expert in Ye cuisine. Father invited you to a feast tomorrow.",
  ui_story_5075_50750201_112_dialog_content = "You gotta come!",
  ui_story_5075_50750201_113_dialog_content = "*sighs*",
  ui_story_5075_50750201_114_dialog_content = "Thank you for your help, sir, or the prince would never go back.",
  ui_story_5075_50750201_115_dialog_content = "This is the chief advisor to the king, PlayerName.",
  ui_story_5075_50750201_116_dialog_content = "And my mentor as well.",
  ui_story_5075_50750201_117_dialog_content = "I am able to thrive in Ji all thanks to his help and guidance.",
  ui_story_5075_50750201_118_dialog_content = "(Is he really that important? Wait, how do people usually show their respect in Longzhou?)",
  ui_story_5075_50750201_119_dialog_content = "Good to see you, sir!",
  ui_story_5075_50750201_120_dialog_content = "Sir, this is PlayerName from Astra, whom I believe you saw during the banquet.",
  ui_story_5075_50750201_121_dialog_content = "Hmm, he left quite the impression.",
  ui_story_5075_50750201_122_dialog_content = "(Yep, he's definitely Dantang's teacher. His gaze makes me even more nervous than an entire room of staring people...)",
  ui_story_5075_50750201_123_dialog_content = "Huh? That mark on the letter you're holding...",
  ui_story_5075_50750201_124_dialog_content = "An urgent report from the inspection office.",
  ui_story_5075_50750201_125_dialog_content = "Is it from the squad hastily dispatched to defend the bay because of increased Eclipsite presence?",
  ui_story_5075_50750201_126_dialog_content = "Now, their opponents, I fear, are more than just wicked spirits.",
  ui_story_5075_50750201_127_dialog_content = "According to the urgent report, right after the earthquake, fiendlings near the sea suddenly went berserk and started harming people.",
  ui_story_5075_50750201_128_dialog_content = "Although the patrols intervened in time and stopped them, I'm afraid this may not be an isolated incident.",
  ui_story_5075_50750201_129_dialog_content = "Frenzied fiendlings? But how? Was there more to the earthquake than simply being a natural disaster?",
  ui_story_5075_50750202_1_dialog_content = "That's why I came here, hoping you could investigate it for us.",
  ui_story_5075_50750202_2_dialog_content = "Sure, tomorrow I shall—",
  ui_story_5075_50750202_3_dialog_content = "Aren't you supposed to babysit the prince for the king again tomorrow?",
  ui_story_5075_50750202_4_dialog_content = "Well, umm...",
  ui_story_5075_50750202_5_dialog_content = "Is there anything I can do to help?",
  ui_story_5075_50750202_6_dialog_content = "Dantang may not have any spare time, but I do. If all you need is someone to investigate, I can handle that just fine.",
  ui_story_5075_50750202_7_dialog_content = "No. You're already doing us a huge favor by traveling here as an emissary, PlayerName.",
  ui_story_5075_50750202_8_dialog_content = "How could we burden you with Ji affairs?",
  ui_story_5075_50750202_9_dialog_content = "I believe it's feasible.",
  ui_story_5075_50750202_10_dialog_content = "Sir?",
  ui_story_5075_50750202_11_dialog_content = "I've reviewed Zhuohua's exchange proposal.",
  ui_story_5075_50750202_12_dialog_content = "But in the royal court, it was clear the king wasn't keen on immediate execution.",
  ui_story_5075_50750202_13_dialog_content = "A pity.",
  ui_story_5075_50750202_14_dialog_content = "PlayerName, being an emissary, you must wish for another chance to persuade the king.",
  ui_story_5075_50750202_15_dialog_content = "That's right.",
  ui_story_5075_50750202_16_dialog_content = "A lot of people helped me get here, and just as many are counting on me. I refuse to go back empty-handed.",
  ui_story_5075_50750202_17_dialog_content = "Well, this is a golden opportunity.",
  ui_story_5075_50750202_18_dialog_content = "As the Spring Festival is just around the corner, the city is bustling with people, along with various activities.",
  ui_story_5075_50750202_19_dialog_content = "So, any trouble caused by wicked spirits and fiendlings could lead to serious consequences and harm to the citizens.",
  ui_story_5075_50750202_20_dialog_content = "And when that happens, if someone were to resolve it quickly, it would be a meritorious deed.",
  ui_story_5075_50750202_21_dialog_content = "The king would surely bestow rewards where they're due.",
  ui_story_5075_50750202_22_dialog_content = "I actually couldn't care less about rewards. After all, I don't even know what to do with the pile of gifts I have back at the guesthouse...",
  ui_story_5075_50750202_23_dialog_content = "But if possible, I'd really like to use this as an opportunity to share our plan with the king!",
  ui_story_5075_50750202_24_dialog_content = "So please leave this task to me, sir.",
  ui_story_5075_50750202_25_dialog_content = "I have another request, and if you agree, I'll leave this matter in your hands.",
  ui_story_5075_50750202_26_dialog_content = "What is it?",
  ui_story_5075_50750202_27_dialog_content = "... Try to keep a low profile during your investigation, and don't let anyone in the royal court know about this.",
  ui_story_5075_50750202_28_dialog_content = "Sir, PlayerName is from abroad and not familiar with Ji. How could he be tasked to carry out mission alone?",
  ui_story_5075_50750202_29_dialog_content = "I never said PlayerName should handle it alone.",
  ui_story_5075_50750202_30_dialog_content = "Not catching my hint, huh? Zhuohua, you're being too impatient.",
  ui_story_5075_50750202_31_dialog_content = "...",
  ui_story_5075_50750202_32_dialog_content = "It's fine, Dantang.",
  ui_story_5075_50750202_33_dialog_content = "I've taken plenty of jobs that have led me to unfamiliar places back in Astra. As tough as those jobs were, I came away with plenty of experience with this sort of thing.",
  ui_story_5075_50750202_34_dialog_content = "Good.",
  ui_story_5075_50750202_35_dialog_content = "Zhuohua, see our young guest out of the palace.",
  ui_story_5075_50750202_36_dialog_content = "... Alright.",
  ui_story_5075_50750202_37_dialog_content = "PlayerName—",
  ui_story_5075_50750202_38_dialog_content = "Just so you know, I won't listen if you're gonna apologize or try to talk me out of this.",
  ui_story_5075_50750202_39_dialog_content = "But if you are made to run about like this while I stay in the palace...",
  ui_story_5075_50750202_40_dialog_content = "But the food is delicious at the banquet.",
  ui_story_5075_50750202_41_dialog_content = "?",
  ui_story_5075_50750202_42_dialog_content = "Don't you think it's many times better than the fare in Twin Pavilions Bay?",
  ui_story_5075_50750202_43_dialog_content = "Yes, since they were prepared by the royal chef.",
  ui_story_5075_50750202_44_dialog_content = "In other words, we're not the ones who made it. We didn't plant the rice either, right?",
  ui_story_5075_50750202_45_dialog_content = "It is from local farmers, of course.",
  ui_story_5075_50750202_46_dialog_content = "Then did we ship it into the city?",
  ui_story_5075_50750202_47_dialog_content = "No, the trading houses throughout the land are responsible for that.",
  ui_story_5075_50750202_48_dialog_content = "Did we buy it ourselves?",
  ui_story_5075_50750202_49_dialog_content = "No, that is the task of the royal purser.",
  ui_story_5075_50750202_50_dialog_content = "And yet you didn't worry about troubling them, or offer to do these things for them.",
  ui_story_5075_50750202_51_dialog_content = "... I am not so conceited to believe I can do their jobs.",
  ui_story_5075_50750202_52_dialog_content = "This task is no different either.",
  ui_story_5075_50750202_53_dialog_content = "Nobody can do everything by themselves. If you aren't free to do something while I have both the time and ability, I should be the one doing it.",
  ui_story_5075_50750202_54_dialog_content = "Troubling others, relying on others, that's just how this world works.",
  ui_story_5075_50750202_55_dialog_content = "Of course, if you think I'm not capable of handling the job...",
  ui_story_5075_50750202_56_dialog_content = "I would never!",
  ui_story_5075_50750202_57_dialog_content = "... You know, you are better suited to be a debater than an emissary, PlayerName.",
  ui_story_5075_50750202_58_dialog_content = "With as much sense as you have made, it would be wise for me to surrender.",
  ui_story_5075_50750202_59_dialog_content = "Haha, if you say so...",
  ui_story_5075_50750202_60_dialog_content = "It's wonderful that you're looking much better than when we left.",
  ui_story_5075_50750202_61_dialog_content = "Ahem. Was it that obvious?",
  ui_story_5075_50750202_62_dialog_content = "It is because of me that you stressed too much, over diplomatic relations, the aftermath of the earthquake...",
  ui_story_5075_50750202_63_dialog_content = "Not to mention worrying about me possibly being wronged, you're so stressed out that you haven't been yourself lately.",
  ui_story_5075_50750202_64_dialog_content = "So you think I'm worried about too many things for no reason?",
  ui_story_5075_50750202_65_dialog_content = "Hardly. Perhaps I should say instead that I am thankful for your friendly advice.",
  ui_story_5075_50750202_66_dialog_content = "For your sake, I must pick myself up and resolve the issues as soon as possible.",
  ui_story_5075_50750202_67_dialog_content = "Good, then let's do our best together! Even if we're not exactly fighting on the same front—",
  ui_story_5075_50750202_68_dialog_content = "We can still work together and attain our goals.",
  ui_story_5075_50750202_69_dialog_content = "Esteemed emissary, I'm here to escort you back.",
  ui_story_5075_50750202_70_dialog_content = "Oh, hello again. Are you here just to escort me back?",
  ui_story_5075_50750202_71_dialog_content = "Certainly. As long as you're in Ji, you're an honored guest of our Royal Guesthouse, and we won't be remiss in our duties.",
  ui_story_5075_50750202_72_dialog_content = "Looks like it's time for me to go. I'll keep you updated, Dantang!",
  ui_story_5075_50750202_73_dialog_content = "Then I shall await your good news in the palace.",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>Moments later...</color>",
  ui_story_5075_50750202_75_dialog_content = "Your Highness? What are you doing standing here alone?",
  ui_story_5075_50750202_76_dialog_content = "Oh, you're back, Jiu. How is it going with that thing we talked about?",
  ui_story_5075_50750202_77_dialog_content = "I'm still working hard on it.",
  ui_story_5075_50750202_78_dialog_content = "But there are still numerous secret agents active in Haojin.",
  ui_story_5075_50750202_79_dialog_content = "Please be careful when I'm not around.",
  ui_story_5075_50750202_80_dialog_content = "Got it. Well done, Jiu.",
  ui_story_5075_50750202_81_dialog_content = "I'll be staying in the palace for the foreseeable future, though, so I'm not expecting any danger.",
  ui_story_5075_50750202_82_dialog_content = "Oh, remind me to write a letter when we get back.",
  ui_story_5075_50750202_83_dialog_content = "Even Captain Yuebai has delivered all shipments and is back in Haojin...",
  ui_story_5075_50750202_84_dialog_content = "A certain Ministress Armilla has not been in touch except for a cryptic message since making landfall...",
  ui_story_5075_50750202_85_dialog_content = "I see I will have to chastise her myself.",
  ui_story_5075_50750202_86_dialog_content = "Hmm?",
  ui_story_5075_50750202_87_dialog_content = "What's wrong, Your Highness?",
  ui_story_5075_50750202_88_dialog_content = "At ease. I'm just a bit surprised.",
  ui_story_5075_50750202_89_dialog_content = "It feels as if the flowers on this plum tree blossomed in the blink of an eye.",
  ui_story_5075_50750202_90_dialog_content = "But don't you favor only begonias?",
  ui_story_5075_50750202_91_dialog_content = "Yes, but I find the plum blossoms today relishing as well.",
  ui_story_5075_50750301_1_dialog_content = "(Even though I was full of confidence when I agreed to do this investigation...)",
  ui_story_5075_50750301_2_dialog_content = "(I didn't expect to run into such a huge obstacle right off the bat!)",
  ui_story_5075_50750301_3_dialog_content = "Hey... All this much protection is kind of uncalled for, don't you think? I just wanted to do a little shopping.",
  ui_story_5075_50750301_4_dialog_content = "Your Excellency, considering your distinguished status, six guards is just the most basic security measure, it's nothing exorbitant.",
  ui_story_5075_50750301_5_dialog_content = "I already applied to add nine more guards to ensure your safety.",
  ui_story_5075_50750301_6_dialog_content = "More guards?!",
  ui_story_5075_50750301_7_dialog_content = "Never mind, more importantly...",
  ui_story_5075_50750301_8_dialog_content = "Why isn't there a single person on this street?",
  ui_story_5075_50750301_9_dialog_content = "To avoid any unwanted interruptions in your leisure, we've cleared the area in advance.",
  ui_story_5075_50750301_10_dialog_content = "But that just ruins the entire experience!",
  ui_story_5075_50750301_11_dialog_content = "You're much too overprotective any way you cut it!",
  ui_story_5075_50750301_12_dialog_content = "(If I can't even talk to anyone out here, my investigation will be over before it starts.)",
  ui_story_5075_50750301_13_dialog_content = "... No need to bother. I'll deliver it for you.",
  ui_story_5075_50750301_14_dialog_content = "(Huh? Someone talking outside?)",
  ui_story_5075_50750301_15_dialog_content = "The palace told me to deliver this to the emissary in person. Please, don't make it hard for me.",
  ui_story_5075_50750301_16_dialog_content = "If that's the case, please come in.",
  ui_story_5075_50750301_17_dialog_content = "Greetings, Your Excellency.",
  ui_story_5075_50750301_18_dialog_content = "These are treats prepared by the palace's new chef. The nobles find them quite tasty.",
  ui_story_5075_50750301_19_dialog_content = "They sent me to bring you some to try.",
  ui_story_5075_50750301_20_dialog_content = "Thanks. Huh? It's still warm.",
  ui_story_5075_50750301_21_dialog_content = "Despite Haojin's mild climate, it's still winter.",
  ui_story_5075_50750301_22_dialog_content = "There's a heater underneath the food container to keep everything warm and tasty for you.",
  ui_story_5075_50750301_23_dialog_content = "The heater uses a new technique imported from Ye.",
  ui_story_5075_50750301_24_dialog_content = "It's also meticulously designed. Skilled artisans carved flowers on the inside; it makes for a suitable ornament.",
  ui_story_5075_50750301_25_dialog_content = "On the inside? Why make such intricate carvings in a place where no one can see them?",
  ui_story_5075_50750301_26_dialog_content = "Well, they said... matters are more easily handled where they aren't visible.",
  ui_story_5075_50750301_27_dialog_content = "What?",
  ui_story_5075_50750301_28_dialog_content = "I was just mumbling to myself. Take your time and enjoy, esteemed emissary. I'll go back to the palace and report.",
  ui_story_5075_50750301_29_dialog_content = "Esteemed emissary, would you like some snacks now? Or is there anything else you need?",
  ui_story_5075_50750301_30_dialog_content = "No thanks. I'm a little tired, so I think I'll just take a nap for now. You guys can go.",
  ui_story_5075_50750301_31_dialog_content = "Oh, you can just leave the food right here. I'll eat it when I wake up.",
  ui_story_5075_50750301_32_dialog_content = "Yes, Your Excellency.",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>The heater emits faint smoke, and through the interlocking copper pieces, you can see flames flickering inside.</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>Click.</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>Just as the flames inside the heater go out, the copper pieces that were previously interlocked together suddenly spread out.</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>Then, they unfold into a small and delicate begonia blossom.</color>",
  ui_story_5075_50750301_37_dialog_content = "There's an insignia hidden inside, as well as a note?",
  ui_story_5075_50750301_38_dialog_content = "May you enjoy good health during your stay in Ji so as to alleviate Princess Zhuohua's anxiety, Your Excellency.",
  ui_story_5075_50750301_39_dialog_content = "She was delivering a secret message from Dantang!",
  ui_story_5075_50750301_40_dialog_content = "(The insignia belongs to that inspection office, I guess, but I don't know what to do with it right now.)",
  ui_story_5075_50750301_41_dialog_content = "(It's a map? With an address yet!)",
  ui_story_5075_50750301_42_dialog_content = "(The maids happen to be gone right now! This is my chance!)",
  ui_story_5075_50750301_43_option_content = "Psychic Scan",
  ui_story_5075_50750301_44_dialog_content = "(I can sense two guards to the east and three to the south... So it looks like I'm going west.)",
  ui_story_5075_50750301_45_dialog_content = "Hey, move fast! The emissary is missing!",
  ui_story_5075_50750301_46_dialog_content = "You stay here. I'll go over there and see if I can find anything!",
  ui_story_5075_50750301_47_dialog_content = "(That didn't take long at all, but thankfully I made it to the edge of the courtyard. Now I just have to get over these walls...)",
  ui_story_5075_50750301_48_dialog_content = "... They're too tall!",
  ui_story_5075_50750301_49_dialog_content = "Esteemed emissary! Esteemed emissary!",
  ui_story_5075_50750301_50_dialog_content = "(I'll be surrounded in no time! Gotta think of something...)",
  ui_story_5075_50750301_51_dialog_content = "Are you playing hide-and-seek?",
  ui_story_5075_50750301_52_dialog_content = "Huh?",
  ui_story_5075_50750301_53_dialog_content = "Over here!",
  ui_story_5075_50750301_54_dialog_content = "Look up.",
  ui_story_5075_50750301_55_dialog_content = "A little kid? What are you doing on top of the wall? It's dangerous up there!",
  ui_story_5075_50750301_56_dialog_content = "It's not dangerous at all. I could even walk on a rope.",
  ui_story_5075_50750301_57_dialog_content = "So are you playing hide-and-seek? I wanna play too.",
  ui_story_5075_50750301_58_dialog_content = "I'm not playing...",
  ui_story_5075_50750301_59_dialog_content = "Esteemed emissary? Are you here?",
  ui_story_5075_50750301_60_dialog_content = "Uh-oh! Sorry, but I gotta go—",
  ui_story_5075_50750301_61_dialog_content = "!",
  ui_story_5075_50750301_62_dialog_content = "Oh, uh... I was just going for a walk!",
  ui_story_5075_50750301_63_dialog_content = "Emissary? Are you around here?",
  ui_story_5075_50750301_64_dialog_content = "?",
  ui_story_5075_50750301_65_dialog_content = "Not here either. Where did he go?",
  ui_story_5075_50750301_66_dialog_content = "Emissary—",
  ui_story_5075_50750301_67_dialog_content = "And you said you weren't playing.",
  ui_story_5075_50750301_68_dialog_content = "That guard didn't see me at all. Did you do this?",
  ui_story_5075_50750301_69_dialog_content = "Hehe. Maybe.",
  ui_story_5075_50750301_70_dialog_content = "?",
  ui_story_5075_50750301_71_dialog_content = "?",
  ui_story_5075_50750301_72_dialog_content = "Wait a minute.",
  ui_story_5075_50750301_73_dialog_content = "Shouldn't you have been awed by my prestigious aura and have dropped to your knees to the great and majestic Chen'ni by now?",
  ui_story_5075_50750301_74_dialog_content = "Prestigious aura...",
  ui_story_5075_50750301_75_dialog_content = "Uh, what makes you think I should be doing that?",
  ui_story_5075_50750301_76_dialog_content = "Because that's what I heard from the storyteller at the bridge on my way here!",
  ui_story_5075_50750301_77_dialog_content = "He said that's the going trend. Is that not right?",
  ui_story_5075_50750301_78_dialog_content = "I don't think that's what he was talking about exactly...",
  ui_story_5075_50750301_79_dialog_content = "Anyways—",
  ui_story_5075_50750301_80_dialog_content = "I definitely heard something going on here.",
  ui_story_5075_50750301_81_dialog_content = "But I just checked... Well, just to be safe, let's check again.",
  ui_story_5075_50750301_82_dialog_content = "Let's play a game of hide-and-seek!",
  ui_story_5075_50750301_83_dialog_content = "I just need some help getting out of here first. Think you can do that, great and majestic Chen'ni?",
  ui_story_5075_50750301_84_dialog_content = "Oh, you've sure got a glib tongue for a kid!",
  ui_story_5075_50750301_85_dialog_content = "Relax. I'm an expert at this game. You won't go wrong with Chen'ni!",
  ui_story_5075_50750301_86_dialog_content = "The secret is to go all out!",
  ui_story_5075_50750302_1_dialog_content = "Huff... Puff...",
  ui_story_5075_50750302_2_dialog_content = "I'm starting to think... that you don't really know how to play hide-and-seek...",
  ui_story_5075_50750302_3_dialog_content = "That's impossible.",
  ui_story_5075_50750302_4_dialog_content = "See, here we are outside the gate.",
  ui_story_5075_50750302_5_dialog_content = "And no one caught us all this time.",
  ui_story_5075_50750302_6_dialog_content = "I'm saying you're not supposed to dash like that during hide-and-seek...",
  ui_story_5075_50750302_7_dialog_content = "And the fact that no one saw us at all means you cheated somehow.",
  ui_story_5075_50750302_8_dialog_content = "... Then again, I guess that means I cheated too.",
  ui_story_5075_50750302_9_dialog_content = "Anyways, thanks again, Chen'ni... I mean, the great and majestic Chen'ni!",
  ui_story_5075_50750302_10_dialog_content = "Well, since you were nice enough to play with me, we can skip the honorific.",
  ui_story_5075_50750302_11_dialog_content = "Sure, Chen'ni. By the way, my name's PlayerName. I'm—",
  ui_story_5075_50750302_12_dialog_content = "A Caelestite.",
  ui_story_5075_50750302_13_dialog_content = "I know.",
  ui_story_5075_50750302_14_dialog_content = "Huh?",
  ui_story_5075_50750302_15_dialog_content = "Emissary? Is it you out there?",
  ui_story_5075_50750302_16_dialog_content = "I should get out of here while I still can.",
  ui_story_5075_50750302_17_dialog_content = "Esteemed emissary, it's really you!",
  ui_story_5075_50750302_18_dialog_content = "Why did you come out without guards? It's too risky.",
  ui_story_5075_50750302_19_dialog_content = "Guards!",
  ui_story_5075_50750302_20_dialog_content = "Wait, I don't—",
  ui_story_5075_50750302_21_dialog_content = "Squeak!",
  ui_story_5075_50750302_22_dialog_content = "Ahh—a rat! H-Help!",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5075_50750302_24_dialog_content = "Ahhh! It's a fiendling... A fiendling is attacking us!",
  ui_story_5075_50750302_25_dialog_content = "... Hush, don't be so loud.",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>Thud.</color>",
  ui_story_5075_50750302_27_dialog_content = "What have you done, Chen'ni?",
  ui_story_5075_50750302_28_dialog_content = "Put her to sleep for a bit.",
  ui_story_5075_50750302_29_dialog_content = "That one's the next.",
  ui_story_5075_50750302_30_dialog_content = "Squeak...",
  ui_story_5075_50750302_31_dialog_content = "That's definitely no ordinary rat...",
  ui_story_5075_50750302_32_dialog_content = "This must be one of those fiendlings that Liqing and the others told me about. A fiendling that failed to take a proper form.",
  ui_story_5075_50750302_33_dialog_content = "Something about it makes me feel really uncomfortable... It's frenzied, isn't it?",
  ui_story_5075_50750302_X33_dialog_content = "According to the urgent report, right after the earthquake, fiendlings near the sea suddenly went berserk and started harming people.",
  ui_story_5075_50750302_34_dialog_content = "You could tell?",
  ui_story_5075_50750302_35_dialog_content = "Then you must be able to see this too.",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>Chen'ni's fingertips brush over the fallen fiendling, pulling out a dark shadow from its body.</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>It's like a murky mist, with a vague touch of malice gathering.</color>",
  ui_story_5075_50750302_38_option_content = "Try telepathy",
  ui_story_5075_50750302_39_dialog_content = "Hate...",
  ui_story_5075_50750302_40_dialog_content = "Ouch—",
  ui_story_5075_50750302_41_dialog_content = "It hurts when I use my powers on it, like I'm touching a corrosive liquid... What is it?",
  ui_story_5075_50750302_42_dialog_content = "A persistent rotten pest.",
  ui_story_5075_50750302_43_dialog_content = "Careful, it's starting to move! It might try to run away!",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>But the girl doesn't even blink.</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>A simple pinch and twist of Chen'ni, and the menacing black mist disperses into thin air like a smothered flame.</color>",
  ui_story_5075_50750302_46_dialog_content = "Come on now, I didn't skip bedtime and come here for this kind of trouble.",
  ui_story_5075_50750302_47_dialog_content = "You go play by yourself, PlayerName. I've got other stuff to do.",
  ui_story_5075_50750302_48_dialog_content = "Wait—",
  ui_story_5075_50750302_49_dialog_content = "What am I supposed to do with these two?",
  ui_story_5075_50750302_50_dialog_content = "Oops, forgot about this mess.",
  ui_story_5075_50750302_51_dialog_content = "Phew.",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>The girl holds the maid up by the shoulder and \"flies\" her back to the Royal Guesthouse.</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>Then, grabbing the fiendling's tail, she throws it far into the sky.</color>",
  ui_story_5075_50750302_54_dialog_content = "Is this really okay?",
  ui_story_5075_50750302_55_dialog_content = "Of course. Fiendlings aren't that weak.",
  ui_story_5075_50750302_56_dialog_content = "If they couldn't stand that, they'd better forget about transforming and stay an animal for the rest of their lives.",
  ui_story_5075_50750302_57_dialog_content = "I got that feeling when I used my powers, and given the weird behavior...",
  ui_story_5075_50750302_58_dialog_content = "You're a fiendling too, aren't you?",
  ui_story_5075_50750302_59_dialog_content = "Chen'ni? Hey, where did you go?",
  ui_story_5075_50750302_60_dialog_content = "I still wanted to ask her about that ball of black mist... Oh well.",
  ui_story_5075_50750302_61_dialog_content = "Maybe I'll run into her again during my investigation.",
  ui_story_5075_50750302_62_dialog_content = "For now, I should start by checking out this address.",
  ui_story_5075_50750302_63_dialog_content = "...",
  ui_story_5075_50750401_1_dialog_content = "It's Spring Festival again. Come and try our sweet fortune tangerines!",
  ui_story_5075_50750401_2_dialog_content = "Have some fortune tangerines! Come on, I'll peel one for you. No charge if it's not sweet.",
  ui_story_5075_50750401_3_dialog_content = "Sesame seeds, melon seeds, and sugar-coated fruits! All made in time-tested ways! Young man, why not come take a look?",
  ui_story_5075_50750401_4_dialog_content = "It's so lively here. Walking through the streets on my own feels completely different.",
  ui_story_5075_50750401_5_dialog_content = "Excuse me, but do you know how to get to Yulin Street?",
  ui_story_5075_50750401_6_dialog_content = "It's a bit far. You should head towards the busiest bridge first, then ask someone else after crossing the intersection.",
  ui_story_5075_50750401_7_dialog_content = "Thank you. There are so many people over there.",
  ui_story_5075_50750401_8_dialog_content = "First time here? Haojin City hosts fairs every Spring Festival—that's a big hit.",
  ui_story_5075_50750401_9_dialog_content = "It's right on that street.",
  ui_story_5075_50750401_10_dialog_content = "There'll be famous actors performing later. You should definitely go watch if you're not in a hurry or anything.",
  ui_story_5075_50750401_11_dialog_content = "Sure, I'll take a look when I have the time.",
  ui_story_5075_50750401_12_dialog_content = "Oh, you picked the wrong time to come. This place used to be even livelier in previous years.",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5075_50750401_14_dialog_content = "What was that noise?",
  ui_story_5075_50750401_15_dialog_content = "Oh, the kids are having fun playing with firecrackers.",
  ui_story_5075_50750401_16_dialog_content = "This one's not loud enough. Get another one!",
  ui_story_5075_50750401_17_dialog_content = "Firecrackers burst, chasing fiendlings away, banish misfortune in a joyful way!",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>Smash, smash!</color>",
  ui_story_5075_50750401_19_dialog_content = "Hahahahah!",
  ui_story_5075_50750401_20_dialog_content = "Squeak...",
  ui_story_5075_50750401_21_dialog_content = "Is this your idea of fun? Setting off fireworks on a crowded street like this is dangerous!",
  ui_story_5075_50750401_22_dialog_content = "That fiendling isn't going frenzied either... In fact, it looks completely harmless!",
  ui_story_5075_50750401_23_dialog_content = "It's no big deal. You see, even for an ordinary Spring Festival, there's a tradition of using firecrackers to ward off fiendlings.",
  ui_story_5075_50750401_24_dialog_content = "The only difference is that they used to hire actors to play fiendlings in the past, and these kids are dealing with a real one.",
  ui_story_5075_50750401_25_dialog_content = "I didn't take this ritual seriously before, but lately, things have been getting restless.",
  ui_story_5075_50750401_26_dialog_content = "Maybe the fiendlings are indeed a bit ominous.",
  ui_story_5075_50750401_27_dialog_content = "Even though you're a newcomer, I'd advise you to steer clear of those things. Alas, I'll be going now.",
  ui_story_5075_50750401_28_dialog_content = "Why isn't it moving at all? Is it already dead?",
  ui_story_5075_50750401_29_dialog_content = "Should we try another blast?",
  ui_story_5075_50750401_30_dialog_content = "Stop it! You kids are getting way too carried away with this.",
  ui_story_5075_50750401_31_dialog_content = "!",
  ui_story_5075_50750401_32_dialog_content = "(The black mist again! And it's smothering the fiendling!)",
  ui_story_5075_50750401_33_dialog_content = "Get out of here, you kids!",
  ui_story_5075_50750401_34_dialog_content = "Huh? Why?",
  ui_story_5075_50750401_35_dialog_content = "...",
  ui_story_5075_50750401_36_dialog_content = "This one... does seem a bit off, doesn't it?",
  ui_story_5075_50750401_37_dialog_content = "Squeak!",
  ui_story_5075_50750401_38_dialog_content = "Oh no, it's too late—",
  ui_story_5075_50750401_39_dialog_content = "Here comes a head-butt!",
  ui_story_5075_50750401_40_dialog_content = "Squeak—",
  ui_story_5075_50750401_41_dialog_content = "The fiendling... It got head-butted into the sky.",
  ui_story_5075_50750401_42_dialog_content = "Keep your guard up! It's coming back!",
  ui_story_5075_50750402_1_dialog_content = "Squeak...",
  ui_story_5075_50750402_2_dialog_content = "Relax, everything's okay now. Hey, quit wriggling around or you'll end up even more hurt.",
  ui_story_5075_50750402_3_dialog_content = "Squeak! Squeak!",
  ui_story_5075_50750402_4_dialog_content = "You were the one helping me out just now, weren't you? Thanks a bunch, that was some incredible commanding!",
  ui_story_5075_50750402_5_dialog_content = "I saw it just now, the way you stepped forward to save this fiendling. You must be a really good person!",
  ui_story_5075_50750402_6_dialog_content = "Haha... I didn't do much. Besides, you were the one who subdued it.",
  ui_story_5075_50750402_7_dialog_content = "And you did it so quickly too! I don't think anyone even noticed that something had happened.",
  ui_story_5075_50750402_8_dialog_content = "It's all a part of my job.",
  ui_story_5075_50750402_9_dialog_content = "Sorry, I still haven't introduced myself. My name is Luo Song, and I'm a wandering priest of sorts.",
  ui_story_5075_50750402_10_dialog_content = "Squeak!",
  ui_story_5075_50750402_11_dialog_content = "I mostly just travel throughout the land, dispatching demons from time to time.",
  ui_story_5075_50750402_12_dialog_content = "Squeak! Squeak!",
  ui_story_5075_50750402_13_dialog_content = "Something has been agitating the fiendlings in this area recently, making them lose their minds and attack people indiscriminately.",
  ui_story_5075_50750402_14_dialog_content = "I came here to investigate the cause of this strange phenomenon, but even a city as well-guarded as Haojin...",
  ui_story_5075_50750402_15_dialog_content = "Squeak! Squeak!",
  ui_story_5075_50750402_16_dialog_content = "Is something wrong with that fiendling?",
  ui_story_5075_50750402_17_dialog_content = "That seems to be the case. Ever since I captured it, it hasn't stopped trying to bite me or squirm its way out.",
  ui_story_5075_50750402_18_dialog_content = "Be careful.",
  ui_story_5075_50750402_19_dialog_content = "Oh, this is nothing. After all, I make my living by dealing with fiendlings all the time.",
  ui_story_5075_50750402_20_dialog_content = "For a fiendling like this, all you have to do is hold your thumb and forefinger like this...",
  ui_story_5075_50750402_21_dialog_content = "And with a little pressure, it can't escape!",
  ui_story_5075_50750402_22_dialog_content = "I see. You must really be a professional after all!",
  ui_story_5075_50750402_23_dialog_content = "... Wait, that's not what I was asking about!",
  ui_story_5075_50750402_24_dialog_content = "Let me try sensing it...",
  ui_story_5075_50750402_25_dialog_content = "I knew it. That weird ball of black mist is still inside the fiendling's body.",
  ui_story_5075_50750402_26_dialog_content = "\"Weird ball of black mist\"?",
  ui_story_5075_50750402_27_dialog_content = "Yes, I can see it! I bet this black mist is causing the fiendlings to go out of control.",
  ui_story_5075_50750402_28_dialog_content = "Something like that is beyond my expertise. A master's touch is most likely needed for this.",
  ui_story_5075_50750402_29_dialog_content = "Unless you think we can beat that black mist out of it?",
  ui_story_5075_50750402_30_dialog_content = "Uh, probably not.",
  ui_story_5075_50750402_31_dialog_content = "But I did meet a girl earlier—",
  ui_story_5075_50750402_32_dialog_content = "Hey! Why did you guys suddenly run over and stand here whispering? What's the deal?",
  ui_story_5075_50750402_33_dialog_content = "Oh, I almost forgot about this gaggle of kids.",
  ui_story_5075_50750402_34_dialog_content = "Not to mention... I never got to ask your name.",
  ui_story_5075_50750402_35_dialog_content = "Me? I'm PlayerName.",
  ui_story_5075_50750402_36_dialog_content = "It's a pleasure to meet you, PlayerName. Would you mind holding onto this guy for me?",
  ui_story_5075_50750402_37_dialog_content = "Huh?",
  ui_story_5075_50750402_38_dialog_content = "Squeak!",
  ui_story_5075_50750402_39_dialog_content = "Hey, don't just throw it to me like that! Wow, this fiendling's stronger than it looks!",
  ui_story_5075_50750402_40_dialog_content = "(It wasn't even moving in Luo Song's hand earlier! Just how strong he is—hey, quit wiggling around!)",
  ui_story_5075_50750402_41_option_content = "Force Boost!",
  ui_story_5075_50750402_42_dialog_content = "Squeak...",
  ui_story_5075_50750402_43_dialog_content = "Phew, that's better.",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>Thwack! Thwack! Thwack!</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>Luo Song flicks the kids' noggins in punishment.</color>",
  ui_story_5075_50750402_46_dialog_content = "(With Luo Song's strength, that probably hurts a lot...)",
  ui_story_5075_50750402_47_dialog_content = "Waaahhhh—",
  ui_story_5075_50750402_48_dialog_content = "Who do you think you are, flicking our heads like that? It hurts!",
  ui_story_5075_50750402_49_dialog_content = "Luo Song is my name. Whether I'm roaming the land or wrangling demons, that much doesn't change.",
  ui_story_5075_50750402_50_dialog_content = "That's because I have nothing to hide. My intentions are upright and honest.",
  ui_story_5075_50750402_51_dialog_content = "You, on the other hand, have plenty to explain to your parents. What are your names?",
  ui_story_5075_50750402_52_dialog_content = "Setting off fireworks in the street to bully the weak and helpless isn't something I can allow, even for children.",
  ui_story_5075_50750402_53_dialog_content = "I, uh, my name is...",
  ui_story_5075_50750402_54_dialog_content = "Hold on, why should I tell you?",
  ui_story_5075_50750402_55_dialog_content = "My parents said it's because these fiendlings bring bad luck that wicked spirits have been running amok lately.",
  ui_story_5075_50750402_56_dialog_content = "You're with them, which means you're no good either!",
  ui_story_5075_50750402_57_dialog_content = "Sounds like nothing but superstition to me.",
  ui_story_5075_50750402_58_dialog_content = "Besides, using other people's words to excuse your poor behavior is still unacceptable.",
  ui_story_5075_50750402_59_dialog_content = "Have you seen any fiendlings working together with the wicked spirits?",
  ui_story_5075_50750402_60_dialog_content = "Well... Though we haven't seen that, this fiendling did swipe our sugar melon!",
  ui_story_5075_50750402_61_dialog_content = "Everyone chipped in their pocket money to buy it, but in a flash, it was gone.",
  ui_story_5075_50750402_62_dialog_content = "Indeed!",
  ui_story_5075_50750402_63_dialog_content = "Thieves are no good, so what we did is all about keeping the community safe!",
  ui_story_5075_50750402_64_dialog_content = "You said it was gone in a flash, then that means you never saw it steal your snacks in the first place.",
  ui_story_5075_50750402_65_dialog_content = "But this creature was the only thing sneaking around nearby. If not it, then who else could it be?",
  ui_story_5075_50750402_66_dialog_content = "PlayerName.",
  ui_story_5075_50750402_67_dialog_content = "Could you please check that fiendling's mouth for any sugary residue?",
  ui_story_5075_50750402_68_dialog_content = "Let me see... Nope.",
  ui_story_5075_50750402_69_dialog_content = "Aside from some mud and a few cuts and bruises, there's nothing else on this fiendling's body.",
  ui_story_5075_50750402_70_dialog_content = "That doesn't prove it wasn't the thief!",
  ui_story_5075_50750402_71_dialog_content = "Perhaps it used some magic, transferring the sugar melon to another place in a whoosh.",
  ui_story_5075_50750402_72_dialog_content = "Uh, I don't think it'd be stealing sweets if it had powers like that.",
  ui_story_5075_50750402_73_dialog_content = "What exactly does your sugar melon look like?",
  ui_story_5075_50750402_74_dialog_content = "What else could it look like? Just white, round, like...",
  ui_story_5075_50750402_75_dialog_content = "A peeled fortune tangerine?",
  ui_story_5075_50750402_76_dialog_content = "Exactly! A sugar melon so good-looking and tasty, fiendlings would surely love it.",
  ui_story_5075_50750402_77_dialog_content = "You bought it from that old man's stall up the street, right?",
  ui_story_5075_50750402_78_dialog_content = "If you had to put all of your money together to buy it, then you likely couldn't afford anything else afterward.",
  ui_story_5075_50750402_79_dialog_content = "But children are greedy, especially when it comes to snacks—and there just so happened to be a fortune tangerine vendor offering free samples nearby.",
  ui_story_5075_50750402_80_dialog_content = "Don't tell me you didn't see it.",
  ui_story_5075_50750402_81_dialog_content = "We did go there, so what?",
  ui_story_5075_50750402_82_dialog_content = "While you were eating his tangerines, where did you place your sugar melon?",
  ui_story_5075_50750402_83_dialog_content = "I just put it right next to the fruit stand... Oh!",
  ui_story_5075_50750402_84_dialog_content = "Indeed, this is our sugar melon, mixed in with the peeled fortune tangerines.",
  ui_story_5075_50750402_85_dialog_content = "...",
  ui_story_5075_50750402_86_dialog_content = "And so the truth appears.",
  ui_story_5075_50750402_87_dialog_content = "What do you have to say for yourselves now?",
  ui_story_5075_50750402_88_dialog_content = "Sorry...",
  ui_story_5075_50750402_89_dialog_content = "Next time you run into this kind of situation, stop and consider first.",
  ui_story_5075_50750402_90_dialog_content = "Don't think you can just blame fiendlings for all of your misfortunes.",
  ui_story_5075_50750402_91_dialog_content = "Tell me, would hurting a fiendling like this bring your sugar melon back?",
  ui_story_5075_50750402_92_dialog_content = "Because of superstitions and stereotypes, we tend to label things we don't understand as \"evil\" so we can attack them...",
  ui_story_5075_50750402_93_dialog_content = "But that kind of behavior is no better than a child throwing a tantrum.",
  ui_story_5075_50750402_94_dialog_content = "This isn't an act of heroism but of cowardice. Do you understand?",
  ui_story_5075_50750402_95_dialog_content = "Got it...",
  ui_story_5075_50750402_96_dialog_content = "Good, now go home and tell your parents about what happened here today.",
  ui_story_5075_50750402_97_dialog_content = "Okay...",
  ui_story_5075_50750402_98_dialog_content = "Do you think they're really going to tell their parents about this?",
  ui_story_5075_50750402_99_dialog_content = "Most likely not.",
  ui_story_5075_50750402_100_dialog_content = "I know that my words are only addressing the symptoms of the problem, not its underlying causes.",
  ui_story_5075_50750402_101_dialog_content = "But rumors can be just as harmful. The idea that fiendlings bring danger and misfortune only came about because enough people had talked about it.",
  ui_story_5075_50750402_102_dialog_content = "What I say is the truth, and as long as I keep telling the truth, something will eventually come from it.",
  ui_story_5075_50750402_103_dialog_content = "After all, truth is truth, and lies are lies.",
  ui_story_5075_50750402_104_dialog_content = "You're a pretty incredible person, Luo Song.",
  ui_story_5075_50750402_105_dialog_content = "You even helped them find their sugar melon in no time at all. It was like you personally saw the whole thing happen!",
  ui_story_5075_50750402_106_dialog_content = "Haha, about that...",
  ui_story_5075_50750402_107_dialog_content = "I didn't see it myself, but someone did.",
  ui_story_5075_50750402_108_dialog_content = "Hmm... Would you like to meet my friend?",
  ui_story_5075_50750402_109_dialog_content = "Roooaaar!",
  ui_story_5075_50750402_110_dialog_content = "Your friend is a fiendling?",
  ui_story_5075_50750402_111_dialog_content = "Its name is Ah Ding.",
  ui_story_5075_50750402_112_dialog_content = "It saw those kids lose their sugar melon earlier and told me all about it.",
  ui_story_5075_50750402_113_dialog_content = "I meant to bring him to tell the kids the truth outright, but a sugar figurine vendor stopped me.",
  ui_story_5075_50750402_114_dialog_content = "He told me that people here have a very negative view of fiendlings right now, and that bringing Ah Ding might make things worse.",
  ui_story_5075_50750402_115_dialog_content = "So I told Ah Ding to wait for me over here.",
  ui_story_5075_50750402_116_dialog_content = "The sugar figurine vendor is the one who taught me how to approach those children with the truth.",
  ui_story_5075_50750402_117_dialog_content = "When I think about it, his views are perfectly valid.",
  ui_story_5075_50750402_118_dialog_content = "I should go thank him and buy some sugar figurines for Ah Ding and his friends, who are hiding in other places.",
  ui_story_5075_50750402_119_dialog_content = "Uh, Luo Song? I know this is a stretch, but... Is that man over there the \"sugar figurine vendor\" you're talking about?",
  ui_story_5075_50750402_120_dialog_content = "Yes, that's him!",
  ui_story_5075_50750402_121_dialog_content = "Could you wait here for a few minutes while I go say hi to my little friends? I'll be back soon.",
  ui_story_5075_50750402_122_dialog_content = "...",
  ui_story_5075_50750402_123_dialog_content = "\"Sugar figurine vendor\"?",
  ui_story_5075_50750402_124_dialog_content = "Yes, that's me alright!",
  ui_story_5075_50750500_1_dialog_content = "... Aren't you supposed to be a fortune-teller?",
  ui_story_5075_50750500_2_dialog_content = "No-no. Check out this crystal-clear syrup.",
  ui_story_5075_50750500_3_dialog_content = "Then look at the lifelike craftsmanship.",
  ui_story_5075_50750500_4_dialog_content = "It's possible only with skills passed down for generations plus years of experience.",
  ui_story_5075_50750500_5_dialog_content = "I swear on my ancestor's grave that I am a genuine sugar figurine maker.",
  ui_story_5075_50750500_6_dialog_content = "It's been quite some time since we parted ways on the Shadowind.",
  ui_story_5075_50750500_7_dialog_content = "Fate brought us both here, so why don't I offer you a free sugar figurine?",
  ui_story_5075_50750500_8_dialog_content = "I'm not trying to be suspicious of you or anything.",
  ui_story_5075_50750500_9_dialog_content = "But a gift from you isn't something I can easily accept.",
  ui_story_5075_50750500_10_dialog_content = "Alas. I can't believe it...",
  ui_story_5075_50750500_11_dialog_content = "Despite only knowing me for a short time, you understand me so well already.",
  ui_story_5075_50750500_12_dialog_content = "Since you've seen right through me, I'll get to the point. Here, please take this.",
  ui_story_5075_50750500_13_dialog_content = "That's an accessory for girls, isn't it?",
  ui_story_5075_50750500_14_dialog_content = "A customer of mine dropped this accidentally just before you showed up.",
  ui_story_5075_50750500_15_dialog_content = "But I'm too busy with sales to track her down, so it's all you.",
  ui_story_5075_50750500_16_dialog_content = "But I have things to do too.",
  ui_story_5075_50750500_17_dialog_content = "Worry not. I found there's a strong karmic bond between you two through divination.",
  ui_story_5075_50750500_18_dialog_content = "Just go about your own business, and you will meet naturally.",
  ui_story_5075_50750500_19_dialog_content = "Guess you're still a fortune-teller after all.",
  ui_story_5075_50750500_20_dialog_content = "Wait, now that I have a closer look, this looks like what I found at the Dragon Maiden Temple.",
  ui_story_5075_50750500_21_dialog_content = "And I remember seeing it on someone else too.",
  ui_story_5075_50750500_22_dialog_content = "No way...",
  ui_story_5075_50750500_23_dialog_content = "Tell me, do you know anything about the <color=#FFB400>fiendlings</color>? Li Tianxian?",
  ui_story_5075_50750500_24_dialog_content = "Of course I do. Do you remember the special <color=#FFB400>Heavenly Hexagram Divination</color> I invented myself?",
  ui_story_5075_50750500_25_dialog_content = "It also has something to do with Longzhou's most revered <color=#FFB400>Thirteen Major Fiendlings</color>.",
  ui_story_5075_50750500_26_dialog_content = "But aren't those animals?",
  ui_story_5075_50750500_27_dialog_content = "Animals, fiendlings, and deities are varied only by their specific appearances.",
  ui_story_5075_50750500_28_dialog_content = "Didn't Zhong Xu tell you the story of the fiendling protectors who were eventually granted godhood?",
  ui_story_5075_50750500_29_dialog_content = "These thirteen fiendlings are also the most unique deities in Longzhou.",
  ui_story_5075_50750500_30_dialog_content = "The <color=#FFB400>Dragon Maiden</color> in <color=#FFB400>Dragon Maiden Over Turbulent Seas</color> that you know is one of them.",
  ui_story_5075_50750500_31_dialog_content = "Although time has made people forget the deities they worship are actually fiendlings.",
  ui_story_5075_50750500_32_dialog_content = "I digress—back to your question.",
  ui_story_5075_50750500_33_dialog_content = "Fiendlings wield different Force Arts too, and for the major fiendlings—or deities...",
  ui_story_5075_50750500_34_dialog_content = "Their power is so advanced, it's dubbed \"supernatural.\"",
  ui_story_5075_50750500_35_dialog_content = "It is said they could change weather, turn invisible, or shapeshift at will.",
  ui_story_5075_50750500_36_dialog_content = "How enviable.",
  ui_story_5075_50750500_37_dialog_content = "Don't tell me that girl is also a... Wait, did I ask you about the fiendlings' powers?",
  ui_story_5075_50750500_38_dialog_content = "Of course you did!",
  ui_story_5075_50750500_39_dialog_content = "Oh... These must be some really powerful Luminatics. I'm not sure whether I can sense something on this level.",
  ui_story_5075_50750500_40_dialog_content = "I'm afraid you'll have to ask the <color=#FFB400>deities</color> about that yourself.",
  ui_story_5075_50750500_41_dialog_content = "Actually, I do have a mantra for you, even though it's nowhere near the supernatural level.",
  ui_story_5075_50750500_42_dialog_content = "It's passed down from the ancient Longzhou people and especially useful for this circumstance.",
  ui_story_5075_50750500_43_dialog_content = "Come, repeat after me.",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>Merry—New—Year.</color>",
  ui_story_5075_50750500_45_dialog_content = "Merry—New—Year.",
  ui_story_5075_50750500_46_dialog_content = "There you go. You'll put it to good use in the next couple of days, guaranteed.",
  ui_story_5075_50750500_47_dialog_content = "No matter what problems you run into, just repeat it, and most everything will be fine.",
  ui_story_5075_50750500_48_dialog_content = "Is such a simple incantation really that powerful?",
  ui_story_5075_50750500_49_dialog_content = "Oh, do not underestimate the power of an ancient mantra.",
  ui_story_5075_50750500_50_dialog_content = "There are actually four parts to the mantra, but the rest is probably still beyond you right now.",
  ui_story_5075_50750500_51_dialog_content = "I'll teach them to you later when we get a chance.",
  ui_story_5075_50750500_52_dialog_content = "Okay! Thanks a lot!",
  ui_story_5075_50750500_53_dialog_content = "Don't mention it.",
  ui_story_5075_50750500_54_dialog_content = "As for your other troubles, I would love to do a reading for you...",
  ui_story_5075_50750500_55_dialog_content = "I'm back, PlayerName. Sorry to have kept you waiting.",
  ui_story_5075_50750500_56_dialog_content = "But I really don't have the time right now.",
  ui_story_5075_50750500_57_dialog_content = "So you're not gonna read my fortune after all?",
  ui_story_5075_50750500_58_dialog_content = "What fortune are you talking about?",
  ui_story_5075_50750500_59_dialog_content = "That reminds me! You said you're a wandering priest, Luo Song? Does that mean you can use divination to predict the future too?",
  ui_story_5075_50750500_60_dialog_content = "What? Don't let others fool you so easily, PlayerName.",
  ui_story_5075_50750500_61_dialog_content = "All that talk about destiny, fate, and karma may sound convincing, even miraculous.",
  ui_story_5075_50750500_62_dialog_content = "But it's nothing but cheap tricks backed up by clever lies.",
  ui_story_5075_50750500_63_dialog_content = "Huh?",
  ui_story_5075_50750500_64_dialog_content = "As long as you do things with a clear conscience, any outcome you desire is possible.",
  ui_story_5075_50750500_65_dialog_content = "It's always better to take fate into your own hands, rather than leaving it up to some swindler's magic sticks.",
  ui_story_5075_50750500_66_dialog_content = "(Li Tianxian...)",
  ui_story_5075_50750500_67_dialog_content = "(Don't look at me, I'm just a sugar figurine maker.)",
  ui_story_5075_50750500_68_dialog_content = "Silly one.",
  ui_story_5075_50750500_69_dialog_content = "One-track mind.",
  ui_story_5075_50750500_70_dialog_content = "Know nothing, know nothing.",
  ui_story_5075_50750500_71_dialog_content = "Trouble, trouble.",
  ui_story_5075_50750500_72_dialog_content = "What nonsense are you two babbling now? So incoherent, haha.",
  ui_story_5075_50750500_73_dialog_content = "...",
  ui_story_5075_50750500_74_dialog_content = "Hey, your sugar figurine is ready.",
  ui_story_5075_50750500_75_dialog_content = "Thank you... Wait, this is just a plum blossom! Where's my sugar figurine?",
  ui_story_5075_50750500_76_dialog_content = "Oh sorry, I'm running out of syrup.",
  ui_story_5075_50750500_77_dialog_content = "But don't be angry. I mean, just as the poem goes...",
  ui_story_5075_50750500_78_dialog_content = "Heavenly beauty, my fountain of bliss, my evening rain, my faint morning mist, I ache for your touch through the long lonely night. While the plum blossoms bloom by my window so bright, they reach out their petals, so swift they appear, convincing my heart that my beauty is near.",
  ui_story_5075_50750500_79_dialog_content = "So why can't you see this <color=#FFB400>plum blossom</color> as a sweet <color=#FFB400>beauty</color>?",
  ui_story_5075_50750500_80_dialog_content = "Sounds like a pretty lame excuse to me.",
  ui_story_5075_50750500_81_dialog_content = "Come on, we all have to be romantic sometimes.",
  ui_story_5075_50750500_82_dialog_content = "Alright, I'm gonna let you go now. See you later!",
  ui_story_5075_50750500_83_dialog_content = "Remember what I said. If you're wavering, try <color=#FFB400>praying to the deities</color>.",
  ui_story_5075_50750500_84_dialog_content = "They're supposed to stage Dragon Maiden Over Turbulent Seas at the fair later.",
  ui_story_5075_50750500_85_dialog_content = "But the deity on the stage isn't a real one.",
  ui_story_5075_50750500_86_dialog_content = "Huh? Is that... the black mist?",
  ui_story_5075_50750500_87_dialog_content = "I need to go investigate!",
  ui_story_5075_50750500_88_dialog_content = "Wait, PlayerName, I'll go with you—",
  ui_story_5075_50750500_89_dialog_content = "Finally, I can get to the reading now that the irritant is gone.",
  ui_story_5075_50750500_90_dialog_content = "Uh-oh.",
  ui_story_5075_50750500_91_dialog_content = "The deity on that stage just could be the real deal after all.",
  ui_story_5075_50750601_1_dialog_content = "Squeak, squeak!",
  ui_story_5075_50750601_2_dialog_content = "Keep quiet and try not to draw too much attention.",
  ui_story_5075_50750601_3_dialog_content = "Huh? It's already awake.",
  ui_story_5075_50750601_4_dialog_content = "The closer it gets to the fair, the harder it struggles...",
  ui_story_5075_50750601_5_dialog_content = "It must be because of its proximity to the black mist.",
  ui_story_5075_50750601_6_dialog_content = "Judging by your description, I would say it has some sort of corrupting capabilities.",
  ui_story_5075_50750601_7_dialog_content = "Like a poison that causes the fiendlings to go berserk.",
  ui_story_5075_50750601_8_dialog_content = "Unfortunately, I have no way of expelling it from their bodies.",
  ui_story_5075_50750601_9_dialog_content = "I've seen fiendlings in the wilderness with the same symptoms, but they never recovered from them. All they could do was hide themselves somewhere far away from people.",
  ui_story_5075_50750601_10_dialog_content = "This little fiendling is no different...",
  ui_story_5075_50750601_11_dialog_content = "You mentioned a girl who could remove such taint before. Can we go see her?",
  ui_story_5075_50750601_12_dialog_content = "To tell the truth, I only just met her today. All I know is that her name is Chen'ni.",
  ui_story_5075_50750601_13_dialog_content = "She seems to be an especially powerful fiendling herself.",
  ui_story_5075_50750601_14_dialog_content = "The accessories she left behind are our only clue.",
  ui_story_5075_50750601_15_dialog_content = "How could someone afford to lose something so valuable, much less two of them?",
  ui_story_5075_50750601_16_dialog_content = "You're not talking about a golden anklet and bracelet, are you?",
  ui_story_5075_50750601_17_dialog_content = "How did you know?",
  ui_story_5075_50750601_18_dialog_content = "Because I've seen them too.",
  ui_story_5075_50750601_19_dialog_content = "You have one too? A little girl bought a soup dumpling from me just now.",
  ui_story_5075_50750601_20_dialog_content = "She bought only one dumpling and paid with this.",
  ui_story_5075_50750601_21_dialog_content = "Is this gold? I was just about to say it was too much, and she suddenly disappeared when I looked up.",
  ui_story_5075_50750601_22_dialog_content = "Same here, but I didn't even see her.",
  ui_story_5075_50750601_23_dialog_content = "All I noticed was one less bowl of sugar taro on this table, and all that was left was this piece of gold.",
  ui_story_5075_50750601_24_dialog_content = "Do you think it was the God of Wealth?",
  ui_story_5075_50750601_25_dialog_content = "Hmm... She doesn't seem to be a god of wealth, does she?",
  ui_story_5075_50750601_26_dialog_content = "Is that really important right now?",
  ui_story_5075_50750601_27_dialog_content = "The young girl who bought stuffed lotus roots with gold? I've seen her. She probably went inside.",
  ui_story_5075_50750601_28_dialog_content = "Welcome! Have a look at my new year posters! Each one is carefully drawn with only the closest attention to detail!",
  ui_story_5075_50750601_29_dialog_content = "The girl who paid with gold? Yes, I remember her.",
  ui_story_5075_50750601_30_dialog_content = "She really liked my new year posters, especially ones themed on the Dragon Maiden Over Turbulent Seas. She took quite a few.",
  ui_story_5075_50750601_31_dialog_content = "I remember after she bought the posters, there were shouts coming from the stage.",
  ui_story_5075_50750601_32_dialog_content = "Maybe she went over to see what the fuss was about.",
  ui_story_5075_50750601_33_dialog_content = "She said she had something else to do before she left. I guess she meant checking out the fair.",
  ui_story_5075_50750601_34_dialog_content = "Looks like she did a pretty thorough job too.",
  ui_story_5075_50750601_35_dialog_content = "Everything here tastes so good!",
  ui_story_5075_50750601_36_dialog_content = "These rice snacks aren't as sweet as the ones back in Astra, but they still make me crave even more!",
  ui_story_5075_50750601_37_dialog_content = "Agreed! The girl must have chosen the best stuffed lotus root among all these! They're absolutely incredible!",
  ui_story_5075_50750601_38_dialog_content = "You like them too, Ah Ding?",
  ui_story_5075_50750601_39_dialog_content = "Roar!",
  ui_story_5075_50750601_40_dialog_content = "That reminds me, what were we doing here again?",
  ui_story_5075_50750601_41_dialog_content = "...",
  ui_story_5075_50750601_42_dialog_content = "...",
  ui_story_5075_50750601_43_dialog_content = "The fair really takes your mind off of things, huh?",
  ui_story_5075_50750601_44_dialog_content = "True, haha...",
  ui_story_5075_50750601_45_dialog_content = "Still, have you noticed something?",
  ui_story_5075_50750601_46_dialog_content = "The fiendling we brought here stopped struggling as soon as we got here. It looks like it has calmed down quite a bit.",
  ui_story_5075_50750601_47_dialog_content = "Let me try using my powers again...",
  ui_story_5075_50750601_48_dialog_content = "There's no more black mist in the surrounding area! Did it just go away?",
  ui_story_5075_50750601_49_dialog_content = "There is one other possibility. A bad one.",
  ui_story_5075_50750601_50_dialog_content = "The mist could be gathering somewhere else. We need to find the girl before someone gets hurt.",
  ui_story_5075_50750601_51_dialog_content = "Hey, PlayerName!",
  ui_story_5075_50750601_52_dialog_content = "Chen'ni! I'm so glad we finally...",
  ui_story_5075_50750601_53_dialog_content = "Cool, you brought a friend!",
  ui_story_5075_50750601_54_dialog_content = "Just in time! Get on the stage now!",
  ui_story_5075_50750601_55_dialog_content = "Do what now?",
  ui_story_5075_50750601_56_dialog_content = "You... I mean, pardon me, but this fiendling—",
  ui_story_5075_50750601_57_dialog_content = "Another one?",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>Just like before, Chen'ni casually waves her hand, even somewhat absent-mindedly.</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>The black mist inside the fiendling is drawn out and crushed, as if it has never existed.</color>",
  ui_story_5075_50750601_60_dialog_content = "Squeak!",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>The small fiendling hops lightly to Chen'ni's feet, bowing its head as if showing gratitude.</color>",
  ui_story_5075_50750601_62_dialog_content = "So you really are—",
  ui_story_5075_50750601_63_dialog_content = "Come on, it's our turn!",
  ui_story_5075_50750601_64_dialog_content = "There are so many people down there!",
  ui_story_5075_50750601_65_dialog_content = "What exactly are we supposed to be doing up here?",
  ui_story_5075_50750601_66_dialog_content = "Dance the <color=#FFB400>Dragon Maiden Over Turbulent Seas</color>, of course.",
  ui_story_5075_50750601_67_dialog_content = "Hello, dear fellow citizens. I know everyone came here today for the famous performers.",
  ui_story_5075_50750601_68_dialog_content = "But I'm sure everyone has heard that the performer playing the Dragon Maiden best injured her foot and can't go on stage.",
  ui_story_5075_50750601_69_dialog_content = "But we can't leave the stage empty during the fair, so we've come up with a new arrangement.",
  ui_story_5075_50750601_70_dialog_content = "Next, a few Dragon Maiden performers will take turns on stage, each presenting her own version of Dragon Maiden Over Turbulent Seas.",
  ui_story_5075_50750601_71_dialog_content = "You all get to pick the best Dragon Maiden performer of this year's Spring Festival. What do you think?",
  ui_story_5075_50750601_72_dialog_content = "Excellent!",
  ui_story_5075_50750601_73_dialog_content = "It's fortunate you brought a friend, PlayerName, or we wouldn't have enough people.",
  ui_story_5075_50750601_74_dialog_content = "Your pal will play Black Dragon, a troublemaking bully of the sea.",
  ui_story_5075_50750601_75_dialog_content = "I am the Dragon Maiden.",
  ui_story_5075_50750601_76_dialog_content = "What about me?",
  ui_story_5075_50750601_77_dialog_content = "Be ready, PlayerName, because you got the most important part.",
  ui_story_5075_50750601_78_dialog_content = "<size=50>You'll be the sea!</size>",
  ui_story_5075_50750601_79_dialog_content = "Is that necessary?",
  ui_story_5075_50750601_80_dialog_content = "What are you saying? The sea is very important.",
  ui_story_5075_50750601_81_dialog_content = "There's the music. Start dancing.",
  ui_story_5075_50750601_82_dialog_content = "Ahh—",
  ui_story_5075_50750601_83_dialog_content = "\"Blessed by destiny, the Dragon Maiden brings auspicious tidings as she descends upon the world.\"",
  ui_story_5075_50750601_84_dialog_content = "\"The vast ocean's waves are obscure, as though shrouded in smoke.\"",
  ui_story_5075_50750601_85_dialog_content = "(Okay, show off how vast and obscure you are, sea.)",
  ui_story_5075_50750601_86_dialog_content = "(Winking at me doesn't change anything! A-Anyways, guess I'd better make some waves.)",
  ui_story_5075_50750601_87_dialog_content = "\"Blessed be the Dragon Maiden...\"",
  ui_story_5075_50750601_88_dialog_content = "...",
  ui_story_5075_50750601_89_dialog_content = "(Oh no... Don't tell me you forgot your lines!)",
  ui_story_5075_50750601_90_dialog_content = "\"Countless blessings for all\"! That's the next part!",
  ui_story_5075_50750601_91_dialog_content = "(It's no good—she has already missed it. We clearly can't expect Chen'ni to remember her lines...)",
  ui_story_5075_50750601_92_dialog_content = "\"As the evil dragon comes, both sun and moon lose their light.\"",
  ui_story_5075_50750601_93_dialog_content = "(Luo Song?)",
  ui_story_5075_50750601_94_dialog_content = "\"Thunder rumbles and lightning flashes.\"",
  ui_story_5075_50750601_95_dialog_content = "(His motions are stiff and the lines are clearly wrong, but he's doing it! Well done!)",
  ui_story_5075_50750601_96_dialog_content = "(Wait, why isn't he moving?)",
  ui_story_5075_50750601_97_dialog_content = "(Hurry up! Thunder and lightning!)",
  ui_story_5075_50750601_98_dialog_content = "(That's my job too?)",
  ui_story_5075_50750601_99_dialog_content = "(Wh-Whatever, time to make some thunder.)",
  ui_story_5075_50750601_100_dialog_content = "Rumble!",
  ui_story_5075_50750601_101_dialog_content = "\"The people watch helplessly as wicked spirits roar and rampage!\"",
  ui_story_5075_50750601_102_dialog_content = "\"But soon, the Dragon Maiden appears and delivers them from destruction.\"",
  ui_story_5075_50750601_103_dialog_content = "\"With boundless strength and unwavering determination,\"",
  ui_story_5075_50750601_104_dialog_content = "\"She punches the demons and sends them flying in every direction!\"",
  ui_story_5075_50750601_105_dialog_content = "(So now the Dragon Maiden uses her fists to fight?)",
  ui_story_5075_50750601_106_dialog_content = "(Besides, you're supposed to be an evil dragon! Your lines couldn't be any more messed up!)",
  ui_story_5075_50750601_107_dialog_content = "Roar!",
  ui_story_5075_50750601_108_dialog_content = "(Of all the mess in this trainwreck of a play, why do you have to make an Eclipsite so real?)",
  ui_story_5075_50750601_109_dialog_content = "(Wait a minute!)",
  ui_story_5075_50750601_110_dialog_content = "This is a real Eclipsite!",
  ui_story_5075_50750602_1_dialog_content = "Thanks to you all for bringing such...",
  ui_story_5075_50750602_2_dialog_content = "Unique... creative renditions of the... Dragon Maiden Over Turbulent Seas.",
  ui_story_5075_50750602_3_dialog_content = "The troupe leader looks so defeated. We must have done a really terrible job.",
  ui_story_5075_50750602_4_dialog_content = "I think the wicked spirit's attack did the most damage, honestly.",
  ui_story_5075_50750602_5_dialog_content = "I thought Longzhou's Eclipsites rarely appeared in the cities?",
  ui_story_5075_50750602_6_dialog_content = "Frenzied fiendlings, an inexplicable black mist, and now Eclipsites too.",
  ui_story_5075_50750602_7_dialog_content = "What the heck is going on in Haojin City?",
  ui_story_5075_50750602_8_dialog_content = "Why are you two looking so worried?",
  ui_story_5075_50750602_9_dialog_content = "I thought we performed well, even handled the wicked spirit.",
  ui_story_5075_50750602_10_dialog_content = "Especially on PlayerName's part. I love it!",
  ui_story_5075_50750602_11_dialog_content = "If you could call that a performance...",
  ui_story_5075_50750602_12_dialog_content = "I don't think the back half of the story has anything to do with the Dragon Maiden Over Turbulent Seas.",
  ui_story_5075_50750602_13_dialog_content = "That's the way the story was told to me.",
  ui_story_5075_50750602_14_dialog_content = "Eight hundred years ago, the world was plagued by an evil black dragon.",
  ui_story_5075_50750602_15_dialog_content = "But one day, the Dragon Maiden appeared. From atop the ocean's waves, she struck down the wicked dragon with her fists.",
  ui_story_5075_50750602_16_dialog_content = "Each punch had unimaginable strength. The dragon reeled in shock as the wind from her fists pushed it miles and miles away.",
  ui_story_5075_50750602_17_dialog_content = "Before it could react, the Dragon Maiden fell upon the dragon with a flurry of punches, beating it beyond all recognition!",
  ui_story_5075_50750602_18_dialog_content = "Cool! And then? And then?",
  ui_story_5075_50750602_19_dialog_content = "A loud buzzing sound rang out in the dragon's ears as rage built up in its heart, and it viciously—",
  ui_story_5075_50750602_20_dialog_content = "Well, I believe you know what happened next better than anyone. After all—",
  ui_story_5075_50750602_21_dialog_content = "You are Chen'ni the Almighty Benevolent Dragon Divinity herself, aren't you?",
  ui_story_5075_50750602_22_dialog_content = "Wait a minute... After hearing what Li Tianxian said about fiendlings, I shouldn't be surprised that Chen'ni is a deity of some sort.",
  ui_story_5075_50750602_23_dialog_content = "But this Chen'ni we got here is the Dragon Maiden?",
  ui_story_5075_50750602_24_dialog_content = "That is me, indeed.",
  ui_story_5075_50750602_25_dialog_content = "I am honored to be in your presence, the Almighty Benevolent Dragon Divinity!",
  ui_story_5075_50750602_26_dialog_content = "That didn't take long!",
  ui_story_5075_50750602_27_dialog_content = "A genuine deity, an enlightened being, is standing right before us. It's only proper that we show our reverence.",
  ui_story_5075_50750602_28_dialog_content = "Lady Chen'ni, is there a reason for your appearance in Haojin?",
  ui_story_5075_50750602_29_dialog_content = "Someone broke the seal and disturbed my slumber. I am here for justice.",
  ui_story_5075_50750602_30_dialog_content = "Th-That sounds like a disaster!",
  ui_story_5075_50750602_31_dialog_content = "So the appearance of wicked spirits and agitated fiendlings is because the evil dragon's seal has been broken?",
  ui_story_5075_50750602_32_dialog_content = "So the black dragon is real too, huh?",
  ui_story_5075_50750602_33_dialog_content = "That's right, even though there are so many different versions of the Dragon Maiden Over Turbulent Seas, they're all based on a true historical event.",
  ui_story_5075_50750602_34_dialog_content = "Which is why the most important parts of the story are mostly the same.",
  ui_story_5075_50750602_35_dialog_content = "The evil dragon wreaking havoc on the world, the Dragon Maiden sealing it at the bottom of the sea, and the people knowing peace once more.",
  ui_story_5075_50750602_36_dialog_content = "But the event of the story happened over eight hundred years ago.",
  ui_story_5075_50750602_37_dialog_content = "How could the black dragon still be alive after all this time?",
  ui_story_5075_50750602_38_dialog_content = "The black dragon is long dead. That is not a concern.",
  ui_story_5075_50750602_39_dialog_content = "But what happened at the time was not the fault of my kin.",
  ui_story_5075_50750602_40_dialog_content = "There is a deep chasm undersea where a powerful demon was buried along with its overwhelming grudge.",
  ui_story_5075_50750602_41_dialog_content = "My fellow chanced upon it and was overtaken by the grudge, thus the ruckus at sea.",
  ui_story_5075_50750602_42_dialog_content = "Despite the seal being removed, my power remains. Although the grudge was also released, it cannot bring harm to the world without a physical vessel.",
  ui_story_5075_50750602_43_dialog_content = "Even if it possesses a new body, it still cannot move freely until fully acclimated.",
  ui_story_5075_50750602_44_dialog_content = "(So the thing I briefly sensed earlier was the powerful demon?)",
  ui_story_5075_50750602_45_dialog_content = "(That doesn't feel right... But I didn't get a good look at it. Fortunately, we still have time according to Chen'ni.)",
  ui_story_5075_50750602_46_dialog_content = "No matter how you look at it, Chen'ni has the same goal as we do.",
  ui_story_5075_50750602_47_dialog_content = "If we're working together for the time being, can I ask a small question?",
  ui_story_5075_50750602_48_dialog_content = "Yes.",
  ui_story_5075_50750602_49_dialog_content = "I believe the first time we met was at the Dragon Maiden Temple.",
  ui_story_5075_50750602_50_dialog_content = "But if you're the Dragon Maiden herself, then... why were you stealing your own offerings?",
  ui_story_5075_50750602_51_dialog_content = "... That was not stealing.",
  ui_story_5075_50750602_52_dialog_content = "I was taking gifts meant for me. How could that be stealing? Humph!",
  ui_story_5075_50750602_53_dialog_content = "Haha, my bad. You were just accepting your offerings, not stealing them.",
  ui_story_5075_50750602_54_dialog_content = "Guess I'm just used to seeing you like this.",
  ui_story_5075_50750602_55_dialog_content = "Anyways, I'm pretty sure these gold accessories belong to you, Chen'ni?",
  ui_story_5075_50750602_56_dialog_content = "I found one of these back at the Dragon Maiden Temple, and the other was given to me by Li Tianxian... uh, I mean a sugar figurine vendor. He wanted to return it to you.",
  ui_story_5075_50750602_57_dialog_content = "I'll only take one back.",
  ui_story_5075_50750602_58_dialog_content = "Since you found the other one in my temple, PlayerName, you can keep it.",
  ui_story_5075_50750602_59_dialog_content = "Should you have any needs in the future, I'll grant you one wish through it.",
  ui_story_5075_50750602_60_dialog_content = "A wish...",
  ui_story_5075_50750602_61_dialog_content = "Sorry for the interruption, folks.",
  ui_story_5075_50750602_62_dialog_content = "Oh, hello. Sorry about what happened earlier.",
  ui_story_5075_50750602_63_dialog_content = "Nah, it should be me thanking you. There's no other damage except for the broken stage.",
  ui_story_5075_50750602_64_dialog_content = "While the competition has to end like this, and we can't hand out prizes, still, please take this.",
  ui_story_5075_50750602_65_dialog_content = "It's a homemade snack, not as fancy as the ones sold out there.",
  ui_story_5075_50750602_66_dialog_content = "But it's made with a secret recipe passed down in my family, not available elsewhere. Go ahead and give it a try.",
  ui_story_5075_50750602_67_dialog_content = "This is it!",
  ui_story_5075_50750602_68_dialog_content = "I signed up for the competition because I smelled it. I see it's actually not the prize.",
  ui_story_5075_50750602_69_dialog_content = "You did all of that for a snack?",
  ui_story_5075_50750602_70_dialog_content = "Nom-nom.",
  ui_story_5075_50750602_71_dialog_content = "Yes, this is the taste. You made it the same way your grandpa made it!",
  ui_story_5075_50750602_72_dialog_content = "Well, I guess I can call my fair tour a rousing success.",
  ui_story_5075_50750602_73_dialog_content = "Let's go.",
  ui_story_5075_50750602_74_dialog_content = "It's exactly like what my grandpa made... He died years ago though, and we never sold something like this.",
  ui_story_5075_50750602_75_dialog_content = "Wait a second...!!!",
  ui_story_5075_50750602_76_dialog_content = "Have a bite too, PlayerName, Luo Song, and Ah Ding.",
  ui_story_5075_50750602_77_dialog_content = "This snack is simply fantastic. Too bad only his family can make it.",
  ui_story_5075_50750602_78_dialog_content = "Roar!",
  ui_story_5075_50750602_79_dialog_content = "Thank you, Lady Chen'ni!",
  ui_story_5075_50750602_80_dialog_content = "We hung around before, so just call me Chen'ni.",
  ui_story_5075_50750602_81_dialog_content = "Your wish is my command!",
  ui_story_5075_50750602_82_dialog_content = "How come you're not eating, PlayerName?",
  ui_story_5075_50750602_83_dialog_content = "Is this really okay?",
  ui_story_5075_50750602_84_dialog_content = "What do you mean?",
  ui_story_5075_50750602_85_dialog_content = "The troupe leader is the descendant of someone you used to know, right?",
  ui_story_5075_50750602_86_dialog_content = "Don't you have more to say to him?",
  ui_story_5075_50750602_87_dialog_content = "Well...",
  ui_story_5075_50750602_88_dialog_content = "I'm a dragon, a major fiendling, and a sea deity to everyone. Unlike normal folks, I can live a very, very long time.",
  ui_story_5075_50750602_89_dialog_content = "So I get to meet many, many people.",
  ui_story_5075_50750602_90_dialog_content = "That troupe leader is the grandson of someone who used to feed me snacks all the time.",
  ui_story_5075_50750602_91_dialog_content = "The street on the east side is where the granddaughter of a guy who rowed boats with me is getting married.",
  ui_story_5075_50750602_92_dialog_content = "An alley on the south end of the river is where the young nephew of the man who always beat me in cricket fights is being buried.",
  ui_story_5075_50750602_93_dialog_content = "The kid also happens to be his last blood relative in this world.",
  ui_story_5075_50750602_94_dialog_content = "Life is too short for everybody, so they rush everything.",
  ui_story_5075_50750602_95_dialog_content = "Then they always feel the need to prove their ties with rituals or ceremonies.",
  ui_story_5075_50750602_96_dialog_content = "If I have to get to know their descendants just because I met someone...",
  ui_story_5075_50750602_97_dialog_content = "I would be spending all my time shuttling between ceremonies.",
  ui_story_5075_50750602_98_dialog_content = "But don't you ever get lonely that way?",
  ui_story_5075_50750602_99_dialog_content = "Because of your longevity, you're always the one who has to say goodbye to your friends.",
  ui_story_5075_50750602_100_dialog_content = "No, I think it's good this way.",
  ui_story_5075_50750602_101_dialog_content = "You should feel lucky too, PlayerName.",
  ui_story_5075_50750602_102_dialog_content = "Because you get to know me who will live for a long, long time, and I will remember you.",
  ui_story_5075_50750602_103_dialog_content = "Even if you should die, you'll still be in my memories, staying with me forever.",
  ui_story_5075_50750602_104_dialog_content = "(I can always kind of understand what she means, but never fully get it.)",
  ui_story_5075_50750602_105_dialog_content = "(Whether it's the cheery smile on her face, or the feelings that she voices.)",
  ui_story_5075_50750602_106_dialog_content = "(At that moment, I suddenly understand—we really aren't the same.)",
  ui_story_5075_50750701_1_dialog_content = "We. Are. Different.",
  ui_story_5075_50750701_2_dialog_content = "So.",
  ui_story_5075_50750701_3_dialog_content = "We. Are. Incompatible.",
  ui_story_5075_50750701_4_dialog_content = "Urgh...",
  ui_story_5075_50750701_5_dialog_content = "Are you alright? Do you need a break?",
  ui_story_5075_50750701_6_dialog_content = "You've been sensing the black mist all this time. Are you sure you can keep going?",
  ui_story_5075_50750701_7_dialog_content = "Of course I can. I'm not nearly that weak.",
  ui_story_5075_50750701_8_dialog_content = "Also, the more I sense this black mist, the more I realize that it isn't much different than Darkflow.",
  ui_story_5075_50750701_9_dialog_content = "The biggest differences are its infectious and corrupting properties, which make it difficult to dispel using our usual methods to combat Darkflow.",
  ui_story_5075_50750701_10_dialog_content = "If Chen'ni is right, and the root cause of these properties is a grudge, then it may possess some form of consciousness.",
  ui_story_5075_50750701_11_dialog_content = "If so, I should be able to use my powers to disrupt it!",
  ui_story_5075_50750701_12_dialog_content = "After a couple of tries, I realized that I could use my psychic abilities to isolate the corrupting power of the black mist.",
  ui_story_5075_50750701_13_dialog_content = "If I keep practicing, I might even be able to help the fiendlings that have already been corrupted.",
  ui_story_5075_50750701_14_dialog_content = "Actually, it's fine to leave everything to me.",
  ui_story_5075_50750701_15_dialog_content = "That won't do. We're working together now, which means I can't just let you do all of the work.",
  ui_story_5075_50750701_16_dialog_content = "Then I'll leave the delicate work in your hands. If anything requires a heavier touch, my fists are always up to the task!",
  ui_story_5075_50750701_17_dialog_content = "Roar—",
  ui_story_5075_50750701_18_dialog_content = "The same goes for Ah Ding!",
  ui_story_5075_50750701_19_dialog_content = "Roar!",
  ui_story_5075_50750701_20_dialog_content = "Squeak!",
  ui_story_5075_50750701_21_dialog_content = "Isn't that the same little fiendling from before? What is it doing here?",
  ui_story_5075_50750701_22_dialog_content = "Didn't I ask you to tell it to search for your friends, Ah Ding?",
  ui_story_5075_50750701_23_dialog_content = "Roar...",
  ui_story_5075_50750701_24_dialog_content = "It didn't want to listen, huh?",
  ui_story_5075_50750701_25_dialog_content = "While I was practicing with my psychic abilities, I noticed that it's been following us from a distance this whole time.",
  ui_story_5075_50750701_26_dialog_content = "Maybe it's just scared? It might think it's safer to stay with us after it got corrupted.",
  ui_story_5075_50750701_27_dialog_content = "I would hardly consider being at our side a safe choice. After all, we're going to...",
  ui_story_5075_50750701_28_dialog_content = "Wait, did I forget to ask where we're going?",
  ui_story_5075_50750701_29_dialog_content = "Yulin Street.",
  ui_story_5075_50750701_30_dialog_content = "Where the disgusting vibe is coming from.",
  ui_story_5075_50750701_31_dialog_content = "Huh?",
  ui_story_5075_50750701_32_dialog_content = "Does this mean our destinations are actually different?",
  ui_story_5075_50750701_33_dialog_content = "?",
  ui_story_5075_50750701_34_dialog_content = "I don't think so. If that were the case, we would've run into problems long ago.",
  ui_story_5075_50750701_35_dialog_content = "It probably doesn't matter.",
  ui_story_5075_50750701_36_dialog_content = "We're at PlayerName's destination anyway.",
  ui_story_5075_50750701_37_dialog_content = "Am I seeing things? Why does every shop look even more lavish than the last?",
  ui_story_5075_50750701_38_dialog_content = "So this is Yulin Street... It's not as lively as the fair, but it's still really impressive.",
  ui_story_5075_50750701_39_dialog_content = "I know. This is where all the rich people live.",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>The clear river cuts through the entire street, bordered by tall buildings. Even in winter, they're decorated with vibrant blossoms of various colors.</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>Colorful ribbons flutter between the buildings, and when the wind blows, it sets off a chorus of tinkling silver bells.</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>In towers high and low, three thousand maidens dance, their beauty aglow. East to west, on waters that bestow, ships loaded with gold in ceaseless row.</color>",
  ui_story_5075_50750701_43_dialog_content = "What's that statue on the side of the street?",
  ui_story_5075_50750701_44_dialog_content = "A school of fish surrounding a boat. There's something familiar about the boat and the tails of those fish...",
  ui_story_5075_50750701_45_dialog_content = "Where have I seen this before?",
  ui_story_5075_50750701_46_dialog_content = "They're serpentfish. They always swim back and forth in schools.",
  ui_story_5075_50750701_47_dialog_content = "But no matter how far they go, they'll return to Longzhou's offshore to lay eggs in winter.",
  ui_story_5075_50750701_48_dialog_content = "So a lot of sailors would beseech them to guide their ships.",
  ui_story_5075_50750701_49_dialog_content = "Asking fish for help?",
  ui_story_5075_50750701_50_dialog_content = "Sure. People always make offerings to animals or fiendlings for help.",
  ui_story_5075_50750701_51_dialog_content = "Hasn't that been the way ever since ancient times?",
  ui_story_5075_50750701_52_dialog_content = "That doesn't seem to be the case, at least not right now...",
  ui_story_5075_50750701_53_dialog_content = "This statue must be many years old now, and it's covered in scratches and grime. I don't think anyone's taken care of it for a long time.",
  ui_story_5075_50750701_54_dialog_content = "Even if they were on good terms before, I'm afraid that time...",
  ui_story_5075_50750701_55_dialog_content = "That time has long since ended.",
  ui_story_5075_50750701_56_dialog_content = "Yuebai! You're finally back in Haojin.",
  ui_story_5075_50750701_57_dialog_content = "I returned some days ago, but urgent matters with the Lin Family kept me from seeing you sooner.",
  ui_story_5075_50750701_58_dialog_content = "Then it's a good thing we ran into each other here!",
  ui_story_5075_50750701_59_dialog_content = "What kind of problem is the Lin Family dealing with now?",
  ui_story_5075_50750701_60_dialog_content = "I wouldn't exactly call it a problem.",
  ui_story_5075_50750701_61_dialog_content = "It's more of a mistake.",
  ui_story_5075_50750701_62_dialog_content = "A mistake made by the Lin Family in regards to the serpentfish.",
  ui_story_5075_50750701_63_dialog_content = "Is that why you said, \"That time has long since ended\"?",
  ui_story_5075_50750701_64_dialog_content = "Yes.",
  ui_story_5075_50750701_65_dialog_content = "Please refrain from touching my tail.",
  ui_story_5075_50750701_66_dialog_content = "B-But I didn't touch your tail!",
  ui_story_5075_50750701_67_dialog_content = "I wasn't talking about you, PlayerName.",
  ui_story_5075_50750701_68_dialog_content = "Oops, guilty party.",
  ui_story_5075_50750701_69_dialog_content = "I seldom see an Aurorian with serpentfish heritage, so I just couldn't help myself.",
  ui_story_5075_50750701_70_dialog_content = "Given the theory that serpentfish and dragons are distant relatives, we're actually somewhat related.",
  ui_story_5075_50750701_71_dialog_content = "That's my honor then.",
  ui_story_5075_50750701_72_dialog_content = "No wonder I thought those fish looked familiar. They reminded me of you, Yuebai.",
  ui_story_5075_50750701_73_dialog_content = "And after taking a closer look, this boat looks just like the Shadowind!",
  ui_story_5075_50750701_74_dialog_content = "That's because it's an early version of it.",
  ui_story_5075_50750701_75_dialog_content = "It was also the very first of the Lin Family's ships to cross the sea and reach Astra many years ago.",
  ui_story_5075_50750701_76_dialog_content = "I see. But what's a sculpture of a Lin Family ship doing here?",
  ui_story_5075_50750701_77_dialog_content = "Don't you know?",
  ui_story_5075_50750701_78_dialog_content = "This shopping street once belonged to the Lin Family.",
  ui_story_5075_50750701_79_dialog_content = "Th-The entire street?",
  ui_story_5075_50750701_80_dialog_content = "Unfortunately, due to a number of recent deals as well as the Lin Family's latest incident, much of the street has been split up.",
  ui_story_5075_50750701_81_dialog_content = "Right now, only half of the street is still under the Lin Family's name.",
  ui_story_5075_50750701_82_dialog_content = "As for the ultimate fate of this remaining half, it all depends on how things progress.",
  ui_story_5075_50750701_83_dialog_content = "Half of an entire street is still pretty impressive, you know.",
  ui_story_5075_50750701_84_dialog_content = "Squeak!",
  ui_story_5075_50750701_85_dialog_content = "Ouch!",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>As you get suddenly tackled down by the pouncing fiendling, a pitch-black Darkflow strikes the ground right by your feet.</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50750701_88_dialog_content = "PlayerName! Are you alright?",
  ui_story_5075_50750701_89_dialog_content = "I'm fine. That little fiendling saved me just now.",
  ui_story_5075_50750701_90_dialog_content = "Squeak...",
  ui_story_5075_50750701_91_dialog_content = "What's wrong with it? It appears to be in a lot of pain.",
  ui_story_5075_50750701_92_dialog_content = "... Wait, when did it get infected with the black mist again?",
  ui_story_5075_50750701_93_dialog_content = "Ah Ding?",
  ui_story_5075_50750701_94_dialog_content = "Roar...",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>Ah Ding lets out a painful low growl, and the previously stable Lumina around him starts to fluctuate.</color>",
  ui_story_5075_50750701_96_dialog_content = "Don't tell me these symptoms are...",
  ui_story_5075_50750701_97_dialog_content = "Force Boost!",
  ui_story_5075_50750701_98_dialog_content = "I managed to isolate the corrupting power of the mist for now, but we need to find its source as soon as possible.",
  ui_story_5075_50750701_99_dialog_content = "Where did this giant cloud of black mist come from?",
  ui_story_5075_50750701_100_dialog_content = "I'm looking for the one who broke the seal, not you. Be cool and don't get led around by the nose.",
  ui_story_5075_50750701_101_dialog_content = "Huh? Who are you talking to, Chen'ni?",
  ui_story_5075_50750701_102_dialog_content = "The fish.",
  ui_story_5075_50750701_103_dialog_content = "The fish... You mean the statue?",
  ui_story_5075_50750701_104_dialog_content = "Psychic Scan!",
  ui_story_5075_50750701_105_dialog_content = "Is this under the sea?",
  ui_story_5075_50750701_106_dialog_content = "Who. Goes. There.",
  ui_story_5075_50750701_107_dialog_content = "A serpentfish tail?",
  ui_story_5075_50750701_108_dialog_content = "Are you related to the Lin Family?",
  ui_story_5075_50750701_109_dialog_content = "The. Lins.",
  ui_story_5075_50750701_110_dialog_content = "De—spicable.",
  ui_story_5075_50750701_111_dialog_content = "De—testable!",
  ui_story_5075_50750701_112_dialog_content = "!",
  ui_story_5075_50750701_113_dialog_content = "It hurts...",
  ui_story_5075_50750701_114_dialog_content = "Stay strong, PlayerName.",
  ui_story_5075_50750701_115_dialog_content = "I'm fine. The black mist's corrupting power was just much stronger in the place that I sensed.",
  ui_story_5075_50750701_116_dialog_content = "I saw someone else there too. He looked like... he was connected to the Lin Family somehow.",
  ui_story_5075_50750701_117_dialog_content = "It's Yoh.",
  ui_story_5075_50750701_118_dialog_content = "You know him, Yuebai?",
  ui_story_5075_50750701_119_dialog_content = "Yoh is a fiendling who was once an ally of the Lin Family.",
  ui_story_5075_50750701_120_dialog_content = "Not long ago, the guildmaster sent him on a mission to the seashore. He was investigating the reason behind the strange movements of the wicked spirits, but he never returned.",
  ui_story_5075_50750701_121_dialog_content = "... He must have become the \"physical vessel\" that Chen'ni mentioned earlier! It looks like the worst-case scenario happened after all.",
  ui_story_5075_50750701_122_dialog_content = "The power that was sealed away has found itself a new host.",
  ui_story_5075_50750701_123_dialog_content = "Squeak!",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>The little fiendling suddenly leaps out and bites down hard on the wrist of a stranger in the corner.</color>",
  ui_story_5075_50750701_125_dialog_content = "Urgh... Damn creature!",
  ui_story_5075_50750701_126_dialog_content = "Get lost!",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>The little fiendling is forcefully thrown aside, sliding far on the ground, motionless.</color>",
  ui_story_5075_50750701_128_dialog_content = "Oh no!",
  ui_story_5075_50750701_129_dialog_content = "Humph.",
  ui_story_5075_50750701_130_dialog_content = "That man... His body is covered in the black mist too! What's he holding in his arms?",
  ui_story_5075_50750701_131_dialog_content = "Who are you!",
  ui_story_5075_50750701_132_dialog_content = "You don't need to know.",
  ui_story_5075_50750701_133_dialog_content = "This isn't good! Someone stop him!",
  ui_story_5075_50750701_134_dialog_content = "It's too late!",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>The stranger shatters the object he holds on the ground and releases a massive black fog.</color>",
  ui_story_5075_50750701_136_dialog_content = "(It's just like the power I sensed in the ocean!)",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>This time, you can see it without even trying to use your psychic abilities.</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>This time, you can see it without even trying to use your psychic abilities.</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>Endless black mist carries intense Darkflow, boiling and surging like heated water.</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>All those unstable streams of energy converge into one, and then...</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>They suddenly blow up!</color>",
  ui_story_5075_50750701_142_dialog_content = "No you don't!",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>A gold figure leaps out with a lightning bolt and blocks the dark tides from the detonation, but the remaining mist still disperses.</color>",
  ui_story_5075_50750701_145_dialog_content = "You're the ones who broke the seal? Come pay for your mistake!",
  ui_story_5075_50750701_146_dialog_content = "*coughs*",
  ui_story_5075_50750701_147_dialog_content = "What's going on? Where's Chen'ni?",
  ui_story_5075_50750701_148_dialog_content = "After we ran into the black mist, she took off after him.",
  ui_story_5075_50750701_149_dialog_content = "That's way too reckless!",
  ui_story_5075_50750701_150_dialog_content = "Thankfully, I don't think anyone can really hurt her.",
  ui_story_5075_50750701_151_dialog_content = "But we are nothing like her. It doesn't look like any of us have been hurt though.",
  ui_story_5075_50750701_152_dialog_content = "We didn't get hurt... But Ah Ding and the other little guy did!",
  ui_story_5075_50750701_153_dialog_content = "Roar...",
  ui_story_5075_50750701_154_dialog_content = "That explosion just now sent the black mist flying in every direction. Their corruption seems to be intensifying too.",
  ui_story_5075_50750701_155_dialog_content = "Not only that, it looks like the mist is also attracting the Eclipsites.",
  ui_story_5075_50750701_156_dialog_content = "Prepare for battle!",
  ui_story_5075_50750701_157_dialog_content = "Graah!",
  ui_story_5075_50750702_1_dialog_content = "I won't let you wicked spirits defile the Lin Family's ancestral place!",
  ui_story_5075_50750702_2_dialog_content = "Graah—",
  ui_story_5075_50750702_3_dialog_content = "Good thing you're here to clear out these Eclipsites, Yuebai.",
  ui_story_5075_50750702_4_dialog_content = "But the mist seems to have spread all the way into the city. I'm worried that something really bad is about to happen.",
  ui_story_5075_50750702_5_dialog_content = "Isn't there anything we can do about it?",
  ui_story_5075_50750702_6_dialog_content = "There is.",
  ui_story_5075_50750702_7_dialog_content = "The situation may be far worse than before, but the Lin Family still has contingencies in place.",
  ui_story_5075_50750702_8_dialog_content = "I'll assume responsibility for escorting everyone safely to the Lin Family's estate.",
  ui_story_5075_50750702_9_dialog_content = "Afterwards, I will convince the guildmaster to allocate his in-city resources to help with this matter.",
  ui_story_5075_50750702_10_dialog_content = "Sounds good to me! But aren't you curious to know what's going on before helping us, Yuebai?",
  ui_story_5075_50750702_11_dialog_content = "The matter is closely related to the Lin Family...",
  ui_story_5075_50750702_12_dialog_content = "Besides, I don't need a reason to help a friend like you.",
  ui_story_5075_50750702_13_dialog_content = "Wait, PlayerName.",
  ui_story_5075_50750702_14_dialog_content = "What is it, Luo Song?",
  ui_story_5075_50750702_15_dialog_content = "Could I leave this little fiendling in your care for now?",
  ui_story_5075_50750702_16_dialog_content = "Of course. Let's not forget Ah Ding either.",
  ui_story_5075_50750702_17_dialog_content = "Chen'ni still hasn't returned, so all I can do is try to isolate the black mist's corruption.",
  ui_story_5075_50750702_18_dialog_content = "Roar...",
  ui_story_5075_50750702_19_dialog_content = "Ah Ding?",
  ui_story_5075_50750702_20_dialog_content = "This is where we part ways.",
  ui_story_5075_50750702_21_dialog_content = "You too, Luo Song?",
  ui_story_5075_50750702_22_dialog_content = "With the black mist spreading throughout Haojin, there are sure to be even more infected fiendlings.",
  ui_story_5075_50750702_23_dialog_content = "They're not bad, they're just following their instincts. After all, they're still animal spirits born from the wilderness.",
  ui_story_5075_50750702_24_dialog_content = "As it stands, people's opinions towards fiendlings are only getting worse.",
  ui_story_5075_50750702_25_dialog_content = "If anyone gets hurt by a fiendling as a result of the black mist's infection, I'm afraid the relationship between us will be beyond repair.",
  ui_story_5075_50750702_26_dialog_content = "Which is why I need to subdue the infected fiendlings before it's too late.",
  ui_story_5075_50750702_27_dialog_content = "It's true that we've had our share of differences with fiendlings.",
  ui_story_5075_50750702_28_dialog_content = "But that doesn't give anyone the right to decide their place in the world or their fate, for that matter.",
  ui_story_5075_50750702_29_dialog_content = "Isn't that right, Ah Ding?",
  ui_story_5075_50750702_30_dialog_content = "I praise you when you do good, and I reprimand you when you do bad.",
  ui_story_5075_50750702_31_dialog_content = "But in the end, the choice to do either is always your own.",
  ui_story_5075_50750702_32_dialog_content = "Do you want to come with me?",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>Luo Song bends down, gazing at Ah Ding.</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>Ah Ding, face down on the ground, pulls himself up and staggers to his feet.</color>",
  ui_story_5075_50750702_35_dialog_content = "Roar!",
  ui_story_5075_50750702_36_dialog_content = "That's my partner for you.",
  ui_story_5075_50750702_37_dialog_content = "But Ah Ding is in no condition to...",
  ui_story_5075_50750702_38_dialog_content = "Argh, if only the Dragon Maiden were here.",
  ui_story_5075_50750702_39_dialog_content = "You're asking a bit too much, don't you think?",
  ui_story_5075_50750702_40_dialog_content = "Deities don't appear before us just because we ask, you know?",
  ui_story_5075_50750702_41_dialog_content = "Your family would scold you for asking for help all the time, and deities are no different.",
  ui_story_5075_50750702_42_dialog_content = "Yeah, you're right.",
  ui_story_5075_50750702_43_dialog_content = "To tell the truth, worship and prayer are nothing more than wishful thinking.",
  ui_story_5075_50750702_44_dialog_content = "If deities choose to intervene, it's because they have their own reasons for doing so.",
  ui_story_5075_50750702_45_dialog_content = "But here in the mortal realm, our fists are our most reliable method of achieving our goals!",
  ui_story_5075_50750702_46_dialog_content = "No matter how hard the road may be, we can always forge ahead so long as we still have strength in our fists.",
  ui_story_5075_50750702_47_dialog_content = "Roar!",
  ui_story_5075_50750702_48_dialog_content = "Time for us to go!",
  ui_story_5075_50750702_49_dialog_content = "Best of luck, both of you.",
  ui_story_5075_50750702_50_dialog_content = "We should leave too.",
  ui_story_5075_50750702_51_dialog_content = "Come, I'll lead you to the Lin Family's estate.",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>Royal Palace of Ji Kingdom</color>",
  ui_story_5075_50750801_2_dialog_content = "My Lord, there's news from Ye Kingdom again.",
  ui_story_5075_50750801_3_dialog_content = "About the <color=#FFB400>coastal cannons</color> we ordered from the Ye Kingdom? They arrived yet?",
  ui_story_5075_50750801_4_dialog_content = "No... not yet...",
  ui_story_5075_50750801_5_dialog_content = "No? Didn't they start shipping after hiking the price last time?",
  ui_story_5075_50750801_6_dialog_content = "Ye Kingdom's message does say that.",
  ui_story_5075_50750801_7_dialog_content = "But it's been half a month, and the goods still haven't arrived. We sent letters urging them, but on their end...",
  ui_story_5075_50750801_8_dialog_content = "Let me guess, they're raising the price again?",
  ui_story_5075_50750801_9_dialog_content = "... Yes.",
  ui_story_5075_50750801_10_dialog_content = "The letter says the delivery team went missing in the mountains.",
  ui_story_5075_50750801_11_dialog_content = "And considering they're something our Ji Kingdom urgently needs, they can spare some hands to help us search.",
  ui_story_5075_50750801_12_dialog_content = "But we need to cover the costs of the search.",
  ui_story_5075_50750801_13_dialog_content = "Of course, they propose that this cost can be offset against the loan borrowed by the Ye Kingdom from us five years ago.",
  ui_story_5075_50750801_14_dialog_content = "So, I figure they're just using it as an excuse for a price hike.",
  ui_story_5075_50750801_15_dialog_content = "If we don't agree to pay, they'll keep claiming the coastal cannons are lost.",
  ui_story_5075_50750801_16_dialog_content = "And the search may go on... forever.",
  ui_story_5075_50750801_17_dialog_content = "Ridiculous!",
  ui_story_5075_50750801_18_dialog_content = "We placed the order as soon as the wicked spirits started acting up, but it got delayed again and again.",
  ui_story_5075_50750801_19_dialog_content = "It's the delivery team going missing this time. What's their excuse gonna be next? Cannons mysteriously vanishing into thin air?",
  ui_story_5075_50750801_20_dialog_content = "In the reply, make it clear that if they try to take advantage, all transactions between our kingdoms will be canceled!",
  ui_story_5075_50750801_21_dialog_content = "But, my Lord, wicked spirits have been running wilder everywhere lately.",
  ui_story_5075_50750801_22_dialog_content = "Especially along the coast, all regions are looking to the palace for support.",
  ui_story_5075_50750801_23_dialog_content = "If Ye Kingdom's coastal cannons don't arrive soon, it might be tough to hold the defense line longer.",
  ui_story_5075_50750801_24_dialog_content = "Tough to hold the defense line?",
  ui_story_5075_50750801_25_dialog_content = "Is Ye Kingdom the only supplier left in Longzhou?",
  ui_story_5075_50750801_26_dialog_content = "Our Ji Kingdom prospers with abundant goods as well as flocks of traders, and the daily profits are beyond measure.",
  ui_story_5075_50750801_27_dialog_content = "If shipping by sea is challenging now, we may turn to river transport. Since Ye Kingdom refuses fair trade, we'll look for someone else.",
  ui_story_5075_50750801_28_dialog_content = "Money makes everything possible. As long as the price is right, even the mighty forces of Yangjing will be at my command.",
  ui_story_5075_50750801_29_dialog_content = "What about Ye Kingdom's demands?",
  ui_story_5075_50750801_30_dialog_content = "Reject them all.",
  ui_story_5075_50750801_31_dialog_content = "Yes, my Lord.",
  ui_story_5075_50750801_32_dialog_content = "Humph, now even Ye Kingdom dares to play games with me.",
  ui_story_5075_50750801_33_dialog_content = "They might have conveniently forgotten the embarrassment when they begged for a loan from our Ji Kingdom years ago.",
  ui_story_5075_50750801_34_dialog_content = "Speaking of which, that year is also when Zhuohua came to Ji Kingdom.",
  ui_story_5075_50750801_35_dialog_content = "Chief Advisor, what do you think? If Zhuohua really becomes my daughter-in-law, that money might be negotiable.",
  ui_story_5075_50750801_36_dialog_content = "My Lord, jest not. Zhuohua is an aspiring, determined woman. This matter is no joke.",
  ui_story_5075_50750801_37_dialog_content = "Humph, I'm well aware of that.",
  ui_story_5075_50750801_38_dialog_content = "It's just rare to find someone who can keep the crown prince in line so well...",
  ui_story_5075_50750801_39_dialog_content = "Let's not dwell on trivial matters of kids. My Lord, have you considered a strategy for the current turbulent situation?",
  ui_story_5075_50750801_40_dialog_content = "Over the years, our Ji Kingdom has placed a heavy emphasis on commerce. Necessities like food and machinery all rely on trade with other kingdoms.",
  ui_story_5075_50750801_41_dialog_content = "If there are more situations like today's incident with Ye Kingdom...",
  ui_story_5075_50750801_42_dialog_content = "Ji Kingdom has been centered around commerce for centuries. Coming up with a new strategy is no easy feat.",
  ui_story_5075_50750801_43_dialog_content = "Moreover, the threat of wicked spirits may not last.",
  ui_story_5075_50750801_44_dialog_content = "Let's talk about this some other day.",
  ui_story_5075_50750801_45_dialog_content = "I'm tired. I'm going back for a rest now.",
  ui_story_5075_50750801_46_dialog_content = "... Understood.",
  ui_story_5075_50750801_47_dialog_content = "Sir? You're here.",
  ui_story_5075_50750801_48_dialog_content = "I heard the wicked spirits out in the bay have grown in power, and the fiendling case is still a mystery.",
  ui_story_5075_50750801_49_dialog_content = "Also, after parting ways in the palace, I have not heard from PlayerName since!",
  ui_story_5075_50750801_50_dialog_content = "What insight can you give me, sir?",
  ui_story_5075_50750801_51_dialog_content = "Don't worry. That young one is safe and sound, and the tasks assigned to him are going well.",
  ui_story_5075_50750801_52_dialog_content = "But I figure there's more you wish to ask about, right?",
  ui_story_5075_50750801_53_dialog_content = "I shall not beat around the bushes and be straight with you then.",
  ui_story_5075_50750801_54_dialog_content = "You advised PlayerName to stay covert and not to alert anyone in the court.",
  ui_story_5075_50750801_55_dialog_content = "Was it because you suspected potential foul play or malice?",
  ui_story_5075_50750801_56_dialog_content = "For your question, instead of asking me, why not check with your guard?",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>Jiu</color>? She's in...",
  ui_story_5075_50750801_58_dialog_content = "No need to tell me. I'm an old man, and I can't grasp the games of you young girls.",
  ui_story_5075_50750801_59_dialog_content = "Just see it for yourselves.",
  ui_story_5075_50750801_60_dialog_content = "... I see. Thank you for the edification.",
  ui_story_5075_50750801_61_dialog_content = "Oh, here's one more thing. Allow me to apologize to you.",
  ui_story_5075_50750801_62_dialog_content = "When you see the young one later, please convey my apologies to him as well.",
  ui_story_5075_50750801_63_dialog_content = "Earlier, I passed something to the kid in your name.",
  ui_story_5075_50750801_64_dialog_content = "I hope it proves useful in due course.",
  ui_story_5075_50750801_65_dialog_content = "(He is indeed very cautious of someone in the court.)",
  ui_story_5075_50750801_66_dialog_content = "(But who can be it to make him so wary?)",
  ui_story_5075_50750801_67_dialog_content = "(I wonder if it has anything to do with the case that Jiu is investigating...)",
  ui_story_5075_50750801_68_dialog_content = "(Speaking of which, why is the palace quiet regarding the espionage in the city?)",
  ui_story_5075_50750801_69_dialog_content = "(Only Jiu managed to uncover it? Or, did someone let her uncover it intentionally?)",
  ui_story_5075_50750801_70_dialog_content = "(But she is just a guard to a hostage princess, and she's only doing it for me.)",
  ui_story_5075_50750801_71_dialog_content = "(It is not necessary for anyone in the court to do this even if they have ulterior motives, unless...)",
  ui_story_5075_50750801_72_dialog_content = "(The mastermind behind the plot isn't working for the Ji Kingdom but...)",
  ui_story_5075_50750801_73_dialog_content = "Beep.",
  ui_story_5075_50750801_74_dialog_content = "A messenger bird from <color=#FFB400>Ministress Armilla</color>?",
  ui_story_5075_50750801_75_dialog_content = "She cited they didn't work well enough to avoid the guards as the reason she never sent me anything.",
  ui_story_5075_50750801_76_dialog_content = "I knew it was just an excuse.",
  ui_story_5075_50750801_77_dialog_content = "...",
  ui_story_5075_50750801_78_dialog_content = "How audacious of you, Xuan Ji!",
  ui_story_5075_50750801_79_dialog_content = "I must leave the palace now.",
  ui_story_5075_50750801_80_dialog_content = "Chief Advisor, as per your instructions, we've removed the guards from the surroundings.",
  ui_story_5075_50750801_81_dialog_content = "Princess Zhuohua has received the letter as well.",
  ui_story_5075_50750801_82_dialog_content = "Good.",
  ui_story_5075_50750902_1_dialog_content = "Here we are. Welcome to the Lin Family's Yulin Street estate.",
  ui_story_5075_50750902_2_dialog_content = "Huh? Isn't this the same address that was written on that note?",
  ui_story_5075_50750902_3_dialog_content = "Note?",
  ui_story_5075_50750902_4_dialog_content = "I received a box of food from the palace earlier today, and it contained a small map with this address marked on it.",
  ui_story_5075_50750902_5_dialog_content = "It also came with this insignia, but I'm not sure what I'm supposed to do with it.",
  ui_story_5075_50750902_6_dialog_content = "This is... an insignia from the Inspection Office.",
  ui_story_5075_50750902_7_dialog_content = "Young one, do you know that besides the navy, the Ji Kingdom doesn't maintain any regular army on land?",
  ui_story_5075_50750902_8_dialog_content = "Guarding vital routes, investigating treachery, and eliminating wicked spirits—all fall under the responsibility of the Inspection Office.",
  ui_story_5075_50750902_9_dialog_content = "And the insignia in your hand allows you to mobilize the Inspection Office's forces.",
  ui_story_5075_50750902_10_dialog_content = "Apart from the royal palace guard, what you're holding is the command of the mightiest force in Haojin.",
  ui_story_5075_50750902_11_dialog_content = "You mean I've been carrying something that important all along?",
  ui_story_5075_50750902_12_dialog_content = "Huh? Wait, who are you?",
  ui_story_5075_50750902_13_dialog_content = "Guildmaster, there's no need for you to come out and greet us.",
  ui_story_5075_50750902_14_dialog_content = "Heard some disturbance outside, so I came out to see what was going on.",
  ui_story_5075_50750902_15_dialog_content = "I didn't expect you to have guests.",
  ui_story_5075_50750902_16_dialog_content = "You must be PlayerName, right?",
  ui_story_5075_50750902_17_dialog_content = "I've often heard your name from Zhong Xu, Liqing, and Yuebai. It's my fortune to finally meet you today.",
  ui_story_5075_50750902_18_dialog_content = "But now is not the time for small talk.",
  ui_story_5075_50750902_19_dialog_content = "Young one, can you tell me why you looked so surprised when you saw me?",
  ui_story_5075_50750902_20_dialog_content = "Ah, sorry about that. Still, I feel like I've seen you somewhere before.",
  ui_story_5075_50750902_21_dialog_content = "I think it was at the bottom of the ocean... in the memories of the fiendling who is controlling the black mist.",
  ui_story_5075_50750902_22_dialog_content = "Is it Yoh?",
  ui_story_5075_50750902_23_dialog_content = "I believe so.",
  ui_story_5075_50750902_24_dialog_content = "So you're aware of Yoh and his grudge against the Lin Family. What exactly happened between you?",
  ui_story_5075_50750902_25_dialog_content = "That's a long story.",
  ui_story_5075_50750902_26_dialog_content = "Let's talk inside.",
  ui_story_5075_50750902_27_dialog_content = "I have some matters to attend to. Yuebai, please entertain our guest for now.",
  ui_story_5075_50750902_28_dialog_content = "Very well.",
  ui_story_5075_50750902_29_dialog_content = "Would you like some tea?",
  ui_story_5075_50750902_30_dialog_content = "Oh, no thank you.",
  ui_story_5075_50750902_31_dialog_content = "Understood. Maybe some other time.",
  ui_story_5075_50750902_32_dialog_content = "Hahaha... I almost forgot about your usual way of doing things.",
  ui_story_5075_50750902_33_dialog_content = "?",
  ui_story_5075_50750902_34_dialog_content = "It's nothing. I just don't think we need any of those stuffy formalities anymore.",
  ui_story_5075_50750902_35_dialog_content = "Let's get down to business. What's the story between Yoh and the Lins?",
  ui_story_5075_50750902_36_dialog_content = "You see, the shared history between the Lin Family and the fiendlings goes far into the past.",
  ui_story_5075_50750902_37_dialog_content = "At the time, the Lin Family was but a small guild, one that was on the verge of bankruptcy due to years of poor business.",
  ui_story_5075_50750902_38_dialog_content = "In a final act of desperation, the guildmaster exchanged the family's remaining wealth for a merchant ship, hoping to find a better means of surviving across the sea.",
  ui_story_5075_50750902_39_dialog_content = "Needless to say, he succeeded.",
  ui_story_5075_50750902_40_dialog_content = "That was the start of the Lin Family's business dealings with Astra.",
  ui_story_5075_50750902_41_dialog_content = "I remember Carleen telling me this story. Twin Pavilions Bay also began to prosper at that time.",
  ui_story_5075_50750902_42_dialog_content = "Then it seems like you know the rest.",
  ui_story_5075_50750902_43_dialog_content = "More important to our current situation, however, is what happened afterward. On his return trip to Longzhou, the guildmaster's ship accidentally sailed into becalmed waters.",
  ui_story_5075_50750902_44_dialog_content = "The Lin Family didn't have armillary spheres at the time, nor did they have skilled artisans like Xuan Ji to rescue them.",
  ui_story_5075_50750902_45_dialog_content = "The guildmaster and his crew spent a fortnight drifting aimlessly through the sea, and they came dangerously close to depleting their food stocks.",
  ui_story_5075_50750902_46_dialog_content = "That was when they encountered a school of serpentfish.",
  ui_story_5075_50750902_47_dialog_content = "Chen'ni said that the serpentfish return to Longzhou in huge schools every winter to lay their eggs.",
  ui_story_5075_50750902_48_dialog_content = "So the serpentfish rescued the guildmaster?",
  ui_story_5075_50750902_49_dialog_content = "Precisely.",
  ui_story_5075_50750902_50_dialog_content = "They followed the school of serpentfish, which they saw as a good omen, and it led them out of the becalmed waters and back to Longzhou's shores.",
  ui_story_5075_50750902_51_dialog_content = "For that reason, he only chartered return trips from Astra in the winter months.",
  ui_story_5075_50750902_52_dialog_content = "In exchange for ample offerings of food, the serpentfish guided the Lin Family's vessels safely across the sea.",
  ui_story_5075_50750902_53_dialog_content = "And so the serpentfish became a totem of sorts for the Lin Family.",
  ui_story_5075_50750902_54_dialog_content = "It's also the namesake of this entire street.",
  ui_story_5075_50750902_55_dialog_content = "But following the death of that former guildmaster, the Lin Guild only grew in scale with every passing generation.",
  ui_story_5075_50750902_56_dialog_content = "Soon, the guild's growing demands could not be met with just a single return trip in winter.",
  ui_story_5075_50750902_57_dialog_content = "At that point, the guildmaster at the time began asking the serpentfish for more and more escorts across the sea.",
  ui_story_5075_50750902_58_dialog_content = "Wait, he negotiated... with fish?",
  ui_story_5075_50750902_59_dialog_content = "Even though I'm standing right in front of you, you still haven't realized it yet, have you?",
  ui_story_5075_50750902_60_dialog_content = "Back then, the leader of the serpentfish was a <color=#FFB400>fiendling</color>.",
  ui_story_5075_50750902_61_dialog_content = "The Lin Family's serpentfish bloodline also began at that time.",
  ui_story_5075_50750902_62_dialog_content = "But by demanding more escorts from the serpentfish without considering their natural tendencies, the Lin Family failed to honor their original agreement.",
  ui_story_5075_50750902_63_dialog_content = "As a result, the ties between them began to gradually deteriorate.",
  ui_story_5075_50750902_64_dialog_content = "At one point, a Lin Family ship even destroyed a serpentfish habitat.",
  ui_story_5075_50750902_65_dialog_content = "This incident angered the current leader of the serpentfish, and he resolved to completely terminate their cooperation with the Lin Family.",
  ui_story_5075_50750902_66_dialog_content = "I still remember how the newly-transformed Yoh barged into my courtyard and shouted how much he despised me.",
  ui_story_5075_50750902_67_dialog_content = "Welcome back, guildmaster.",
  ui_story_5075_50750902_68_dialog_content = "I'm sorry, you...",
  ui_story_5075_50750902_69_dialog_content = "Haha, I heard what you said just now.",
  ui_story_5075_50750902_70_dialog_content = "This kind of thing must be difficult for a young one like you to accept.",
  ui_story_5075_50750902_71_dialog_content = "I won't justify the actions of the Lin Family. What our predecessors did was indeed unfaithful.",
  ui_story_5075_50750902_72_dialog_content = "However, as a businessman, I'm well aware that the Lin Family ultimately benefited from it, becoming the top player in Haojin's business sector.",
  ui_story_5075_50750902_73_dialog_content = "If I were the one to call the shots during that time, I probably would have done the same thing.",
  ui_story_5075_50750902_74_dialog_content = "If we hadn't received information about the armillary sphere beforehand, the Lin Family wouldn't have released him so easily.",
  ui_story_5075_50750902_75_dialog_content = "They might have kept him captive, using him as a pawn.",
  ui_story_5075_50750902_76_dialog_content = "He hates me, hates the Lin Family, and rightfully so.",
  ui_story_5075_50750902_77_dialog_content = "Breaking promises and betraying trust—indeed, the Lin Family committed such deeds in the past.",
  ui_story_5075_50750902_78_dialog_content = "Now, the Lin Family is reaping what it sowed.",
  ui_story_5075_50750902_79_dialog_content = "Wicked spirits roam the coastal areas, yet the Ji Kingdom is still unable to establish a stable defense line.",
  ui_story_5075_50750902_80_dialog_content = "The coastal cannons we ordered from Ye Kingdom haven't arrived yet, as I heard.",
  ui_story_5075_50750902_81_dialog_content = "The trading ships of the Lin Family have long been unable to sail, and coastal businesses are stagnant. It never rains but it pours.",
  ui_story_5075_50750902_82_dialog_content = "As soon as I extracted myself from the Maritime Trade Offices, I went shamelessly straight to Yoh, disregarding Zhong's better judgment.",
  ui_story_5075_50750902_83_dialog_content = "I hoped he could help the Lin Family explore the water routes and protect the trading ships. Of course, I was kicked out.",
  ui_story_5075_50750902_84_dialog_content = "According to PlayerName, he went to investigate the situation at sea after all...",
  ui_story_5075_50750902_85_dialog_content = "But then he was corrupted by the evil dragon's influence, causing him to lose control and infect every nearby fiendling with his grudge.",
  ui_story_5075_50750902_86_dialog_content = "... The Lin Family bears responsibility for this incident, and it falls to us to rectify it.",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5075_50750902_88_dialog_content = "Drive those fiendlings out!",
  ui_story_5075_50750902_89_dialog_content = "What's going on outside?",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>Luo Song faces a mob of angry townspeople in the center of the street, protecting a number of fiendlings lying unconscious on the ground.</color>",
  ui_story_5075_50751001_2_dialog_content = "Calm down, everyone! These fiendlings never meant to harm anyone!",
  ui_story_5075_50751001_3_dialog_content = "I've already subdued them. All that remains is to remove the corruption from their bodies and—",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>A stone flies out of the crowd, hitting Luo Song.</color>",
  ui_story_5075_50751001_6_dialog_content = "Roar!",
  ui_story_5075_50751001_7_dialog_content = "Ah Ding! You need to calm down too!",
  ui_story_5075_50751001_8_dialog_content = "I'm fine, I promise. We can't afford to fight with them, not right now.",
  ui_story_5075_50751001_9_dialog_content = "People are already injured. Who cares if they meant it or not!",
  ui_story_5075_50751001_10_dialog_content = "I told you those fiendlings are no good! Stealing stuff is one thing, but now they're killing people!",
  ui_story_5075_50751001_11_dialog_content = "Haojin has been peaceful for centuries, but there are even wicked spirits in the city today!",
  ui_story_5075_50751001_12_dialog_content = "And you still claim it's not the fiendlings causing trouble? They're obviously the same! Equally evil!",
  ui_story_5075_50751001_13_dialog_content = "You folks know magic, so it's easy for you to talk without feeling fear.",
  ui_story_5075_50751001_14_dialog_content = "You're not feared of them, but we are!",
  ui_story_5075_50751001_15_dialog_content = "We can't let these ominous things stay in the city. Drive them all out!",
  ui_story_5075_50751001_16_dialog_content = "Drive them out! DRIVE THEM OUT!",
  ui_story_5075_50751001_17_dialog_content = "I have to help him—",
  ui_story_5075_50751001_18_dialog_content = "Wait. If you go out there unprepared, you'll only make things worse.",
  ui_story_5075_50751001_19_dialog_content = "An angry mob won't listen to reason, no matter if it's right or wrong.",
  ui_story_5075_50751001_20_dialog_content = "Aside from an even more powerful display of force, the only way to make them calm down is by offering them an undeniable guarantee that things will get better.",
  ui_story_5075_50751001_21_dialog_content = "I have that insignia! Doesn't that mean I can call on the Inspection Office to help us?",
  ui_story_5075_50751001_22_dialog_content = "The Inspection Office should be handling the Eclipsites scattered throughout the city as we speak.",
  ui_story_5075_50751001_23_dialog_content = "Besides, if they were to intervene... I'm afraid these people would only become more agitated.",
  ui_story_5075_50751001_24_dialog_content = "But there has to be something we can do...",
  ui_story_5075_50751001_25_dialog_content = "I already said there is, didn't I? More specifically, the Lin Family has a solution.",
  ui_story_5075_50751001_26_dialog_content = "Guildmaster, I have a favor to ask of you.",
  ui_story_5075_50751001_27_dialog_content = "I formally request the authority to <color=#FFB400>act on behalf of the Lin Guildmaster</color> of Haojin.",
  ui_story_5075_50751001_28_dialog_content = "Please grant me the right to allocate the Lin Family's people and resources to resolve this incident.",
  ui_story_5075_50751001_29_dialog_content = "What's your plan?",
  ui_story_5075_50751001_30_dialog_content = "Despite the Lin Guild's diminished prominence in recent years, the fact remains that we are still a long-standing organization with close ties to the people.",
  ui_story_5075_50751001_31_dialog_content = "I wish to offer the people of this city a promise of safety in the guild's name and send our medics to treat the wounded.",
  ui_story_5075_50751001_32_dialog_content = "Do you understand what's at stake with your casually spoken words?",
  ui_story_5075_50751001_33_dialog_content = "Yeah, the Lin Family does hold considerable wealth, but not to the point where we can just take on the welfare of a whole city's populace.",
  ui_story_5075_50751001_34_dialog_content = "Moreover, the Lin Family was involved in a smuggling case before, and it took a lot of effort to clear our name.",
  ui_story_5075_50751001_35_dialog_content = "The business world is just like a battleground—it's okay to play dirty behind the scenes, but our public image has to stay clean.",
  ui_story_5075_50751001_36_dialog_content = "You're using the Lin Family's name to vouch for the fiendlings. Any slip-up, and the Lin Family will become a public target.",
  ui_story_5075_50751001_37_dialog_content = "I'm well aware of this.",
  ui_story_5075_50751001_38_dialog_content = "But Yoh is behind the fiendling threat, and the Lins are the cause of the grudge in the first place.",
  ui_story_5075_50751001_39_dialog_content = "The Lins must be held accountable.",
  ui_story_5075_50751001_40_dialog_content = "The times have changed, indeed.",
  ui_story_5075_50751001_41_dialog_content = "Ji Kingdom values commerce, and the merchants always prioritize profits.",
  ui_story_5075_50751001_42_dialog_content = "When I was young, everyone fought over the smallest gain, coveting even a bowl of rice in a beggar's hand.",
  ui_story_5075_50751001_43_dialog_content = "And the Lins would even sacrifice the serpentfish they had enshrined for generations to serve their interests.",
  ui_story_5075_50751001_44_dialog_content = "So now you want me to put everything I worked hard for on the line just because of \"accountability\"?",
  ui_story_5075_50751001_45_dialog_content = "My words are far from empty, guildmaster. I know that I can make them a reality.",
  ui_story_5075_50751001_46_dialog_content = "Wait, you two! This isn't the time for arguing...",
  ui_story_5075_50751001_47_dialog_content = "I have a mantra for you to learn.",
  ui_story_5075_50751001_48_dialog_content = "No matter what problems you run into, just repeat it, and most everything will be fine.",
  ui_story_5075_50751001_49_dialog_content = "(Even though I doubt it'll help, I won't know unless I try!)",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>Merry... <size=45>Merry New Year!</size></color>",
  ui_story_5075_50751001_51_dialog_content = "...",
  ui_story_5075_50751001_52_dialog_content = "...",
  ui_story_5075_50751001_53_dialog_content = "Hahaha... It's a new year.",
  ui_story_5075_50751001_54_dialog_content = "Bid farewell to the old and welcome the new—time for a fresh start.",
  ui_story_5075_50751001_55_dialog_content = "After all the preparations, the official day of the Spring Festival is tomorrow, isn't it?",
  ui_story_5075_50751001_56_dialog_content = "Indeed.",
  ui_story_5075_50751001_57_dialog_content = "Is everything ready? How about the New Year's Eve dinner?",
  ui_story_5075_50751001_58_dialog_content = "Most of our ingredients have been placed in cold storage, and fresh vegetables will be delivered to us on that day.",
  ui_story_5075_50751001_59_dialog_content = "The guild's accounts were settled two days ago. A summary has been placed in your study for you to read at your convenience.",
  ui_story_5075_50751001_60_dialog_content = "Our guild's business struggled yet again this year, but I still saw fit to reward the guards and workers with an additional two months' worth of wages.",
  ui_story_5075_50751001_61_dialog_content = "You sure have a mind of your own.",
  ui_story_5075_50751001_62_dialog_content = "When sailing the ever-capricious sea, a captain must respond swiftly and decisively.",
  ui_story_5075_50751001_63_dialog_content = "A tailwind or surging current can be missed entirely if I fail to seize it in time.",
  ui_story_5075_50751001_64_dialog_content = "Do you think what we're facing now is a tailwind to the Lin Family?",
  ui_story_5075_50751001_65_dialog_content = "If you're sure about it, I'll agree to your request.",
  ui_story_5075_50751001_66_dialog_content = "Thank goodness...",
  ui_story_5075_50751001_67_dialog_content = "<size=45>I cannot.</size>",
  ui_story_5075_50751001_68_dialog_content = "Hey—",
  ui_story_5075_50751001_69_dialog_content = "I know all too well that any scheme or calculation can be instantly washed away by a large enough wave.",
  ui_story_5075_50751001_70_dialog_content = "When that happens, the only thing that will keep the ship from capsizing is a strong and stable keel.",
  ui_story_5075_50751001_71_dialog_content = "A ship's backbone should never bend or break.",
  ui_story_5075_50751001_72_dialog_content = "...",
  ui_story_5075_50751001_73_dialog_content = "Maybe your assessment on the present situation is correct, but I remain a product of the old era.",
  ui_story_5075_50751001_74_dialog_content = "From where I stand, your actions are too radical and risky.",
  ui_story_5075_50751001_75_dialog_content = "Guildmaster—",
  ui_story_5075_50751001_76_dialog_content = "However, you're the captain of the Shadowind, holding the shipping routes crucial to the Lin Family.",
  ui_story_5075_50751001_77_dialog_content = "In the eyes of others, what you say speaks for the entire Lin Family.",
  ui_story_5075_50751001_78_dialog_content = "Does this mean...",
  ui_story_5075_50751001_79_dialog_content = "I may be old-fashioned, but above all, I am a businessman who considers various factors and weighs pros and cons.",
  ui_story_5075_50751001_80_dialog_content = "You're a captain able to master the intricate modern ships and are certainly free to do what you will.",
  ui_story_5075_50751001_81_dialog_content = "If you succeed, you'll be a hero to the Lin Guild, and I'll put you in charge of the sea routes near Longzhou as well.",
  ui_story_5075_50751001_82_dialog_content = "If it doesn't work out, you'll be someone who has violated the guildmaster's command, acting without permission.",
  ui_story_5075_50751001_83_dialog_content = "The family may disown you soon, and you might even lose your last name.",
  ui_story_5075_50751001_84_dialog_content = "Can you accept these conditions?",
  ui_story_5075_50751001_85_dialog_content = "<size=45>I accept.</size>",
  ui_story_5075_50751001_86_dialog_content = "Let's go, PlayerName.",
  ui_story_5075_50751001_87_dialog_content = "Sure... Oh, but just a second.",
  ui_story_5075_50751001_88_dialog_content = "Can you keep this insignia safe for me for the time being, Guildmaster?",
  ui_story_5075_50751001_89_dialog_content = "You would trust me with something so important?",
  ui_story_5075_50751001_91_dialog_content = "Don't forget that I'm a deceitful and unscrupulous person.",
  ui_story_5075_50751001_92_dialog_content = "Haha... I'd be lying if I said I was completely reassured with this decision.",
  ui_story_5075_50751001_93_dialog_content = "But I don't see any opportunity to use it any time soon, and the map that came with it also pointed me your way.",
  ui_story_5075_50751001_94_dialog_content = "You keep insisting you're not trustworthy, but Yuebai and Zhong Xu still believe in you.",
  ui_story_5075_50751001_95_dialog_content = "And I trust their judgment.",
  ui_story_5075_50751001_96_dialog_content = "My psychic abilities also tell me that even if you try to do something bad with it, someone here will stop you.",
  ui_story_5075_50751001_97_dialog_content = "Well, in that case, I'll take it.",
  ui_story_5075_50751001_98_dialog_content = "Thank you.",
  ui_story_5075_50751001_99_dialog_content = "Come on, Yuebai, let's go—",
  ui_story_5075_50751001_100_dialog_content = "Haha, the younger generation.",
  ui_story_5075_50751001_101_dialog_content = "Always heading into risky places, they're still too impulsive. It's hard to feel at ease about the future of the Lin Family.",
  ui_story_5075_50751001_102_dialog_content = "Well, your expression says otherwise.",
  ui_story_5075_50751001_103_dialog_content = "It practically screams, \"The Lins have plenty of successors waiting in the wings.\"",
  ui_story_5075_50751001_104_dialog_content = "Hahaha, Zhong Xu, you do have sharp eyes.",
  ui_story_5075_50751001_105_dialog_content = "I had hoped to slowly untangle past issues and leave things clean for the next generation.",
  ui_story_5075_50751001_106_dialog_content = "I didn't expect her to be one step ahead of me and that she had already taken up this responsibility before I could step in.",
  ui_story_5075_50751001_107_dialog_content = "But Zhong Xu, you've been watching from the shadows. Why not lend a hand?",
  ui_story_5075_50751001_108_dialog_content = "PlayerName has already noticed your involvement.",
  ui_story_5075_50751001_109_dialog_content = "So did you.",
  ui_story_5075_50751001_110_dialog_content = "Our young friend even brought the insignia of the Inspection Office here, yet you still refused to talk about your deal with the Chief Advisor.",
  ui_story_5075_50751001_111_dialog_content = "It's obvious you promised him you'd help. As soon as our young friend got here, I was urged to mobilize the Lin guards.",
  ui_story_5075_50751001_112_dialog_content = "So why put on the act?",
  ui_story_5075_50751001_113_dialog_content = "The way we beat around the bushes, it's difficult for us old folks to communicate with young people.",
  ui_story_5075_50751001_114_dialog_content = "Just think of it as my preparation for the Spring Festival, a ceremony of bidding farewell to the old and welcoming the new.",
  ui_story_5075_50751001_115_dialog_content = "See? It's not even the Spring Festival yet, and we're already hearing so many nice words.",
  ui_story_5075_50751001_116_dialog_content = "This is a good omen, isn't it?",
  ui_story_5075_50751001_117_dialog_content = "Stop talking nonsense! This guy is defending the fiendling. He's definitely up to no good.",
  ui_story_5075_50751001_118_dialog_content = "Step aside now and let us drive out this evil being before it's too late.",
  ui_story_5075_50751001_119_dialog_content = "Otherwise, even if you have magic, we won't be easy on you.",
  ui_story_5075_50751001_120_dialog_content = "I know you're all scared, but we have to be reasonable about this—",
  ui_story_5075_50751001_121_dialog_content = "Drive them all out!",
  ui_story_5075_50751001_122_dialog_content = "Drive them out!",
  ui_story_5075_50751001_123_dialog_content = "Roar!",
  ui_story_5075_50751001_124_dialog_content = "This is bad. I wasn't able to round up all of the fiendlings...",
  ui_story_5075_50751001_125_dialog_content = "Serpent's Constriction!",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>Mu Yuebai swiftly slices through the pack of fiendlings like a razor-sharp dagger.</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>The crowd barely has time to react. The fiendling that was rabid just a second ago has already lost consciousness, collapsing to the ground.</color>",
  ui_story_5075_50751002_3_dialog_content = "Who... Who is that? So incredible!",
  ui_story_5075_50751002_4_dialog_content = "I know! That's Captain Mu from the Lin Guild.",
  ui_story_5075_50751002_5_dialog_content = "But her tail... She's got fiendling blood in her, doesn't she...",
  ui_story_5075_50751002_6_dialog_content = "How could you say that? She just saved us!",
  ui_story_5075_50751002_7_dialog_content = "Everyone, please listen to what I have to say.",
  ui_story_5075_50751002_8_dialog_content = "I know that today has been a terrifying day. Some have gotten injured while others have incurred losses.",
  ui_story_5075_50751002_9_dialog_content = "I share in everyone's frustrations.",
  ui_story_5075_50751002_10_dialog_content = "But these fiendlings aren't responsible for the troubles we've been experiencing. They're merely the puppets of an even more sinister culprit.",
  ui_story_5075_50751002_11_dialog_content = "By fighting against only the fiendlings, we are playing right into their hands.",
  ui_story_5075_50751002_12_dialog_content = "You share their bloodline, and that's why you'd say that!",
  ui_story_5075_50751002_13_dialog_content = "But I am more Aurorian than serpentfish, that much has always been true. Furthermore, the Lin Family does business with people, not fiendlings.",
  ui_story_5075_50751002_14_dialog_content = "Why would I hurt our guild's prospects by working against you?",
  ui_story_5075_50751002_15_dialog_content = "...",
  ui_story_5075_50751002_16_dialog_content = "Words are often unfounded, and I know I don't have the right to ask you to believe in my words.",
  ui_story_5075_50751002_17_dialog_content = "But in the name of the Lin Guild, I vow to provide you all with undeniable evidence of the truth behind this incident.",
  ui_story_5075_50751002_18_dialog_content = "We cannot allow ourselves to be misled and exploited by our enemy. Doing so will only allow them to operate with full impunity.",
  ui_story_5075_50751002_19_dialog_content = "Even if you say that...",
  ui_story_5075_50751002_20_dialog_content = "(They're still not entirely convinced, but what can we offer them as proof? ... Wait, I got it!)",
  ui_story_5075_50751002_21_dialog_content = "Force Boost!",
  ui_story_5075_50751002_22_dialog_content = "(Please, even if it's just a little bit, let me show everyone what I see...)",
  ui_story_5075_50751002_23_dialog_content = "Everyone! Please take a closer look at these fiendlings!",
  ui_story_5075_50751002_24_dialog_content = "What the heck is that?",
  ui_story_5075_50751002_25_dialog_content = "This is what the true culprit is using to control these fiendlings.",
  ui_story_5075_50751002_26_dialog_content = "As long as they're still infected with this power, chasing the fiendlings out of town won't change anything.",
  ui_story_5075_50751002_27_dialog_content = "They... actually don't seem to be lying.",
  ui_story_5075_50751002_28_dialog_content = "The Lins have indeed done a lot for everyone over the years, but...",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>They huddle together and, after a brief whispered discussion, send a representative.</color>",
  ui_story_5075_50751002_30_dialog_content = "Fine, we'll trust you for now.",
  ui_story_5075_50751002_31_dialog_content = "It's getting late, and we don't want to waste time here.",
  ui_story_5075_50751002_32_dialog_content = "But there are still some fiendlings lurking in the city. Who knows what they might do while you're investigating?",
  ui_story_5075_50751002_33_dialog_content = "So, we have a condition.",
  ui_story_5075_50751002_34_dialog_content = "You've got to sort this out before the Spring Festival, so we can all enjoy a good holiday.",
  ui_story_5075_50751002_35_dialog_content = "Understood.",
  ui_story_5075_50751002_36_dialog_content = "That's right! It's the New Year! Everyone wants this problem resolved as soon as possible!",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>Mu Yuebai sends people out to placate the crowd as they eventually disperse.</color>",
  ui_story_5075_50751002_38_dialog_content = "Thanks for your help.",
  ui_story_5075_50751002_39_dialog_content = "Taking on that many people on my own would have been truly exhausting.",
  ui_story_5075_50751002_40_dialog_content = "When you say \"taking on,\" you don't mean...",
  ui_story_5075_50751002_41_dialog_content = "Never mind. The Spring Festival is just a day away, so we'd better hurry.",
  ui_story_5075_50751002_42_dialog_content = "Thankfully, we've managed to dig up plenty of clues.",
  ui_story_5075_50751002_43_dialog_content = "To start, someone destroyed Chen'ni's seal, allowing the power of the black dragon to rise out of the sea.",
  ui_story_5075_50751002_44_dialog_content = "While that power has a number of unique properties, at the end of the day it's still just a type of Darkflow.",
  ui_story_5075_50751002_45_dialog_content = "That Darkflow, in turn, has attracted a lot of Eclipsites to Haojin's shores, preventing the Lin Family's ships from leaving and effectively stopping their business.",
  ui_story_5075_50751002_46_dialog_content = "It forced the Lin Guildmaster to seek out Yoh, the fiendling he worked with, and ask him to find the motive for the congregating Eclipsites.",
  ui_story_5075_50751002_47_dialog_content = "Only for Yoh to be tainted by the dark mist during the investigation and left with nothing but hatred for the Lin Family.",
  ui_story_5075_50751002_48_dialog_content = "And after acquiring a physical vessel, the black mist became even more active and started affecting the fiendlings in the area.",
  ui_story_5075_50751002_49_dialog_content = "Its influence eventually crept into the city of Haojin.",
  ui_story_5075_50751002_50_dialog_content = "Therefore, we have to find Yoh first and remove the corruption from him.",
  ui_story_5075_50751002_51_dialog_content = "After that, we need to find a way to seal the black mist away, just like Chen'ni did in the past.",
  ui_story_5075_50751002_52_dialog_content = "Then what are we waiting for?",
  ui_story_5075_50751002_53_dialog_content = "Squeak!",
  ui_story_5075_50751002_54_dialog_content = "Fiendling Guardian Flame!",
  ui_story_5075_50751002_55_dialog_content = "Argh, the black mist has spread to most of the city! More and more fiendlings are succumbing to its effects.",
  ui_story_5075_50751002_56_dialog_content = "You should stay here, Luo Song.",
  ui_story_5075_50751002_57_dialog_content = "They need your help.",
  ui_story_5075_50751002_58_dialog_content = "Fine. But before you go, here—",
  ui_story_5075_50751002_59_dialog_content = "What is this?",
  ui_story_5075_50751002_60_dialog_content = "A fist bump.",
  ui_story_5075_50751002_61_dialog_content = "This will make us friends in a common struggle.",
  ui_story_5075_50751002_62_dialog_content = "When you come back, I'll treat you to some of the freshest water chestnuts in the world.",
  ui_story_5075_50751002_63_dialog_content = "Alright!",
  ui_story_5075_50751002_64_dialog_content = "I'm off to search for more corrupted fiendlings. Do your best out there!",
  ui_story_5075_50751002_65_dialog_content = "I will! Now to find Yuebai... Huh?",
  ui_story_5075_50751002_66_dialog_content = "Your Excellency, we've finally found you again.",
  ui_story_5075_50751002_67_dialog_content = "You really know how to... wander around.",
  ui_story_5075_50751002_68_dialog_content = "It's the steward... Wh-What brings you out here, sir?",
  ui_story_5075_50751002_69_dialog_content = "Given the surge of evil beings in the city, it's our duty to guarantee your safety.",
  ui_story_5075_50751002_70_dialog_content = "Please follow us back to the Royal Guesthouse.",
  ui_story_5075_50751002_71_dialog_content = "I'm sorry, but I can't go back right now. I still have something important to do.",
  ui_story_5075_50751002_72_dialog_content = "Please, don't make things hard for us. You're a distinguished guest who came a long way to our Ji Kingdom.",
  ui_story_5075_50751002_73_dialog_content = "If anything happens to you, we might end up losing our heads. Please understand our situation.",
  ui_story_5075_50751002_74_dialog_content = "Escort the esteemed emissary back to the guesthouse!",
  ui_story_5075_50751002_75_dialog_content = "Wait! Let go of me—",
  ui_story_5075_50751002_76_dialog_content = "I'm back, PlayerName.",
  ui_story_5075_50751002_77_dialog_content = "... PlayerName?",
  ui_story_5075_50751101_1_dialog_content = "Flowers, Endlessly Blooming!",
  ui_story_5075_50751101_2_dialog_content = "Hmm...",
  ui_story_5075_50751101_3_dialog_content = "All of you appear to be skilled assassins, yet none of your moves are lethal.",
  ui_story_5075_50751101_4_dialog_content = "Is the intention to distract and delay me?",
  ui_story_5075_50751101_5_dialog_content = "...",
  ui_story_5075_50751101_6_dialog_content = "Even when I feigned strikes to the vitals, you didn't fight back.",
  ui_story_5075_50751101_7_dialog_content = "Several are hurt while I remain unscathed.",
  ui_story_5075_50751101_8_dialog_content = "Heheh. I think I finally understand what PlayerName meant now.",
  ui_story_5075_50751101_9_dialog_content = "It is odd to be treated so kindly out of the blue.",
  ui_story_5075_50751101_10_dialog_content = "But there's a reason behind every peculiarity in the world.",
  ui_story_5075_50751101_11_dialog_content = "What Ministress Armilla wrote in her message, what Jiu mentioned before she left, and the advice from my mentor.",
  ui_story_5075_50751101_12_dialog_content = "Only an idiot can't figure out with this many clues.",
  ui_story_5075_50751101_13_dialog_content = "You are spies for the Ye Kingdom, right?",
  ui_story_5075_50751101_14_dialog_content = "!",
  ui_story_5075_50751101_15_dialog_content = "Your Highness, you've guessed right. Now you should know we mean no harm to you.",
  ui_story_5075_50751101_16_dialog_content = "Things are getting complicated in Haojin City. So please, Your Highness, head back to the palace for your safety.",
  ui_story_5075_50751101_17_dialog_content = "Will my leaving the palace now foul up your plans?",
  ui_story_5075_50751101_18_dialog_content = "Between two kingdoms, the back-and-forth conflicts, both open and behind the scenes, are a common occurrence.",
  ui_story_5075_50751101_19_dialog_content = "Your Highness, you're kind-hearted, and <color=#FFB400>our lord</color> doesn't want to see you in a tough spot. So, please head back.",
  ui_story_5075_50751101_20_dialog_content = "... <color=#FFB400>Your lord</color>.",
  ui_story_5075_50751101_21_dialog_content = "Your Highness, if you insist on going against our advice, we'll have to resort to force.",
  ui_story_5075_50751101_22_dialog_content = "Go get her!",
  ui_story_5075_50751101_23_dialog_content = "Rise be the Wind!",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5075_50751101_25_dialog_content = "Are you hurt, Your Highness?",
  ui_story_5075_50751101_26_dialog_content = "Jiu? I thought they had you occupied, and you wouldn't make it back for a while.",
  ui_story_5075_50751101_27_dialog_content = "My duty is to protect you.",
  ui_story_5075_50751101_28_dialog_content = "As long as you need me, I'll be back by your side wherever I may be.",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>Suddenly, a hand grabs Jiu's ankle.</color>",
  ui_story_5075_50751101_30_dialog_content = "Frost... Blade... You can't...",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5075_50751101_32_dialog_content = "I have a feeling I will be asking a lot from you later.",
  ui_story_5075_50751101_33_dialog_content = "But we have a pressing issue on hand. Come with me to see PlayerName at once.",
  ui_story_5075_50751101_34_dialog_content = "Do you know where PlayerName is, Your Highness?",
  ui_story_5075_50751101_35_dialog_content = "I was in too much a hurry to ask...",
  ui_story_5075_50751101_36_dialog_content = "Can I interest you in a little divination?",
  ui_story_5075_50751101_37_dialog_content = "... Li Tianxian.",
  ui_story_5075_50751101_38_dialog_content = "Have you been watching all this time?",
  ui_story_5075_50751101_39_dialog_content = "What are you saying? I just sold out my sugar figurines and got a hunch.",
  ui_story_5075_50751101_40_dialog_content = "I had a feeling I'd run into someone important this way, so here I am, trying my luck.",
  ui_story_5075_50751101_41_dialog_content = "But I didn't see anything I wasn't supposed to see. Honest.",
  ui_story_5075_50751101_42_dialog_content = "Never mind. Forget it.",
  ui_story_5075_50751101_43_dialog_content = "I see it's hard to get new clients. PlayerName is still the best for believing everything I say.",
  ui_story_5075_50751101_44_dialog_content = "... You saw PlayerName?",
  ui_story_5075_50751101_45_dialog_content = "Sure did. Got a plum blossom candy and a poem from me too.",
  ui_story_5075_50751101_46_dialog_content = "But no need to thank me.",
  ui_story_5075_50751101_47_dialog_content = "That is absurd. Why should I thank you?",
  ui_story_5075_50751101_48_dialog_content = "But if you could tell me where PlayerName is, I would be grateful.",
  ui_story_5075_50751101_49_dialog_content = "Over there at Yulin Street, though you better hurry.",
  ui_story_5075_50751101_50_dialog_content = "Or somebody will beat you to it.",
  ui_story_5075_50751101_51_dialog_content = "... Let's go, Jiu.",
  ui_story_5075_50751101_52_dialog_content = "Just a minute. I'm elated about selling out all the sugar figurines today.",
  ui_story_5075_50751101_53_dialog_content = "So I'll give you a reading for free.",
  ui_story_5075_50751101_54_dialog_content = "As far as I can tell, you'll be heading southeastward to meet someone important.",
  ui_story_5075_50751101_55_dialog_content = "That's where Yulin Street is. You told me the location yourself.",
  ui_story_5075_50751101_56_dialog_content = "But can't you just go with the flow and admit that's where you're heading?",
  ui_story_5075_50751101_57_dialog_content = "I have no time for your nonsense.",
  ui_story_5075_50751101_58_dialog_content = "That's the fate I have concluded from your reading.",
  ui_story_5075_50751101_59_dialog_content = "Princess Dantang, we consult the spirits and deities in most divinations.",
  ui_story_5075_50751101_60_dialog_content = "But the most accurate divination is to consult oneself.",
  ui_story_5075_50751101_61_dialog_content = "Your thoughts and your actions determine your fate.",
  ui_story_5075_50751101_62_dialog_content = "Oops, sorry for taking up more of your time. I'm done and shall not keep you.",
  ui_story_5075_50751101_63_dialog_content = "...",
  ui_story_5075_50751101_64_dialog_content = "Thank you very much.",
  ui_story_5075_50751101_65_dialog_content = "Don't mention it, though I'd appreciate future businesses.",
  ui_story_5075_50751101_66_dialog_content = "Worry not, I don't plan to.",
  ui_story_5075_50751102_1_dialog_content = "Urgh...",
  ui_story_5075_50751102_2_dialog_content = "This... doesn't look like the guesthouse.",
  ui_story_5075_50751102_3_dialog_content = "For all your talk about hospitality, this is the first time I've ever seen someone knock out and kidnap their guest.",
  ui_story_5075_50751102_4_dialog_content = "If you had just cooperated, I never intended to show up before you like this.",
  ui_story_5075_50751102_5_dialog_content = "After all, the role of the Royal Guesthouse's steward is quite convenient, and I didn't want to change it.",
  ui_story_5075_50751102_6_dialog_content = "I didn't think you'd cause so much trouble, even getting the Lins to lend you a hand.",
  ui_story_5075_50751102_7_dialog_content = "In the worst-case scenario, you might actually resolve the mess we've intentionally stirred up.",
  ui_story_5075_50751102_8_dialog_content = "So you people are behind this?",
  ui_story_5075_50751102_9_dialog_content = "Breaking the dragon's seal, spreading the black mist throughout the city, pitting people and fiendlings against each other.",
  ui_story_5075_50751102_10_dialog_content = "What exactly are you after?",
  ui_story_5075_50751102_11_dialog_content = "That's not something you should be concerned about.",
  ui_story_5075_50751102_12_dialog_content = "Just take a break in this hiding spot for now. Once everything settles, <color=#FFB400>we</color> will let you go.",
  ui_story_5075_50751102_13_dialog_content = "By <color=#FFB400>\"we,\"</color> do you mean your allies within the Ji Kingdom's government?",
  ui_story_5075_50751102_14_dialog_content = "The Chief Advisor told you that, didn't he?",
  ui_story_5075_50751102_15_dialog_content = "That old geezer messed with many of our actions even before realizing our presence.",
  ui_story_5075_50751102_16_dialog_content = "But he won't be around much longer.",
  ui_story_5075_50751102_17_dialog_content = "And this is all thanks to you.",
  ui_story_5075_50751102_18_dialog_content = "Me?",
  ui_story_5075_50751102_19_dialog_content = "I heard your conversation with the Chief Advisor and Her Highness the day you arrived at the palace.",
  ui_story_5075_50751102_20_dialog_content = "Don't be fooled by the high walls of the palace. Inside there, it's the place with the least secrets in the world.",
  ui_story_5075_50751102_21_dialog_content = "He probably realized our agent was slowly infiltrating the government, but couldn't ascertain who.",
  ui_story_5075_50751102_22_dialog_content = "That's why he wants to use someone like you, an outsider.",
  ui_story_5075_50751102_23_dialog_content = "But his move has given me an opening.",
  ui_story_5075_50751102_24_dialog_content = "I know the old man passed you the Inspection Office's insignia through that meal box.",
  ui_story_5075_50751102_25_dialog_content = "If you indeed used the Inspection Office's force to resolve the current predicament, his action would just be considered expedience.",
  ui_story_5075_50751102_26_dialog_content = "There's room for justification even if someone looks into it.",
  ui_story_5075_50751102_27_dialog_content = "But if someone finds out the insignia is on you before you can do anything with it...",
  ui_story_5075_50751102_28_dialog_content = "Being the Chief Advisor and handing over such a vital item to a foreigner, especially someone from another continent...",
  ui_story_5075_50751102_29_dialog_content = "Someone whose movements are shrouded in mystery in Haojin's most tumultuous times.",
  ui_story_5075_50751102_30_dialog_content = "Who could believe you're not conspiring, plotting against the Ji Kingdom?",
  ui_story_5075_50751102_31_dialog_content = "Everyone in the government will surely condemn him for treason.",
  ui_story_5075_50751102_32_dialog_content = "Let me see, where did you hide the insignia? In your pocket? Sleeve?",
  ui_story_5075_50751102_33_dialog_content = "You can stop searching. I don't have it on me anymore.",
  ui_story_5075_50751102_34_dialog_content = "When the Chief Advisor asked me to operate in secret, I had a feeling it was because of the people around me.",
  ui_story_5075_50751102_35_dialog_content = "After I received that box of food, I was even more convinced that someone at the Royal Guesthouse couldn't be trusted.",
  ui_story_5075_50751102_36_dialog_content = "If that's the case, then it was only a matter of time before you discovered it.",
  ui_story_5075_50751102_37_dialog_content = "That's why I had to get out of there as soon as possible.",
  ui_story_5075_50751102_38_dialog_content = "What's the point? You still haven't found the opportunity to mobilize the Inspection Office.",
  ui_story_5075_50751102_39_dialog_content = "Plus, as someone from a distant land, the number of people you know in Longzhou is exceedingly limited.",
  ui_story_5075_50751102_40_dialog_content = "Even if you're acquainted with Princess Zhuohua, she's in the palace, and I've ordered spies to monitor her all the time, leaving you no chance to communicate with each other.",
  ui_story_5075_50751102_41_dialog_content = "Whoever you give the insignia to can be revealed with a simple investigation.",
  ui_story_5075_50751102_42_dialog_content = "Oh, I see. It's the Lin Family, right?",
  ui_story_5075_50751102_43_dialog_content = "The Lin Guildmaster would take on any risk as long as it's profitable.",
  ui_story_5075_50751102_44_dialog_content = "But giving the Inspection Office's command to a merchant with a tainted history... Hahaha!",
  ui_story_5075_50751102_45_dialog_content = "Even in the Ji Kingdom, where commerce and merchants are valued, the absurdity of your action is unprecedented, making it easy to pin a crime.",
  ui_story_5075_50751102_46_dialog_content = "For a second there, I really thought you had some hidden cards, yet it turns out you're merely a naive kid.",
  ui_story_5075_50751102_47_dialog_content = "I need to keep an eye on my crew. There is no time to waste on you.",
  ui_story_5075_50751102_48_dialog_content = "Who said I gave the insignia to the Lin Family?",
  ui_story_5075_50751102_49_dialog_content = "If not the Lins, it's probably those two who hung around with you earlier.",
  ui_story_5075_50751102_50_dialog_content = "Commoners or merchants, not much difference there—",
  ui_story_5075_50751102_51_dialog_content = "It wasn't a commoner.",
  ui_story_5075_50751102_52_dialog_content = "<size=45>It was <color=#FFB400>Princess Zhuohua</color>.</size>",
  ui_story_5075_50751102_53_dialog_content = "Didn't you listen? I said there are spies around the princess, and she can't possibly...",
  ui_story_5075_50751102_54_dialog_content = "<size=45>She'll be here soon enough.</size>",
  ui_story_5075_50751102_55_dialog_content = "The insignia is a symbol of the Inspection Office, the address belongs to the Lin Family, and the one who guided me is her mentor.",
  ui_story_5075_50751102_56_dialog_content = "And they're all held together by begonias.",
  ui_story_5075_50751102_57_dialog_content = "Dantang is the only one who could make full use of both of these!",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5075_50751102_59_dialog_content = "Don't move or you'll lose your head.",
  ui_story_5075_50751102_60_dialog_content = "Are you all right, PlayerName?",
  ui_story_5075_50751102_61_dialog_content = "Dantang! Jiu!",
  ui_story_5075_50751102_62_dialog_content = "You... How did you... Ah!",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>Dantang suddenly yanks at the face of the Royal Guesthouse's steward.</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>A mask, thin as a cicada's wing, gets peeled off, uncovering a strange new face beneath.</color>",
  ui_story_5075_50751102_65_dialog_content = "You're indeed not the real steward of the Royal Guesthouse but an impersonator.",
  ui_story_5075_50751102_66_dialog_content = "... So what if you catch me? It won't change a thing.",
  ui_story_5075_50751102_67_dialog_content = "Our lord's wisdom is unparalleled. We, the <color=#FFB400>Fate Riders</color>, are everywhere.",
  ui_story_5075_50751102_68_dialog_content = "Our plan is almost finished. The seal at the sea's bottom has been broken, and the slumbering nightmare has already awakened!",
  ui_story_5075_50751102_69_dialog_content = "When Haojin falls into chaos, we'll swoop in and take Ji Kingdom without breaking a sweat.",
  ui_story_5075_50751102_70_dialog_content = "Unless you have a deity on your side, otherwise—urgh!",
  ui_story_5075_50751102_71_dialog_content = "Did someone call for help?",
  ui_story_5075_50751102_72_dialog_content = "Grr! Pff-urgh!",
  ui_story_5075_50751102_73_dialog_content = "Chen'ni? What are you doing here?",
  ui_story_5075_50751102_74_dialog_content = "I was chasing the culprit who broke the seal, but I lost the rascal eventually.",
  ui_story_5075_50751102_75_dialog_content = "So I decided to follow the scent, investigating everywhere the guy went and everyone who had contact with him.",
  ui_story_5075_50751102_76_dialog_content = "Including here!",
  ui_story_5075_50751102_77_dialog_content = "Grr! Urgh!",
  ui_story_5075_50751102_78_dialog_content = "And I even met the sugar figurine vendor.",
  ui_story_5075_50751102_79_dialog_content = "That sugar figurine vendor who made plum blossom candies?",
  ui_story_5075_50751102_80_dialog_content = "That's the one! He's so generous and offered me a bunch of figurines.",
  ui_story_5075_50751102_81_dialog_content = "He only wanted one thing—that was for me to plant a plum flower twig everywhere I go.",
  ui_story_5075_50751102_82_dialog_content = "So did you do it?",
  ui_story_5075_50751102_83_dialog_content = "Of course. I got my offerings, so I have to keep my promises.",
  ui_story_5075_50751102_84_dialog_content = "I planted one outside this house too.",
  ui_story_5075_50751102_85_dialog_content = "Thank goodness... Dantang!",
  ui_story_5075_50751102_86_dialog_content = "I'm here.",
  ui_story_5075_50751102_87_dialog_content = "I got the insignia from the Lin Guildmaster and the Family Guard's assistance.",
  ui_story_5075_50751102_88_dialog_content = "The guards are ready for Zhong Xu's order to suppress the Eclipsites and frenzied fiendlings in the city.",
  ui_story_5075_50751102_89_dialog_content = "Once the Inspection Office has dealt with the so-called Fate Riders, they'll join the fray too.",
  ui_story_5075_50751102_90_dialog_content = "Thank you... for keeping in mind the flower I love.",
  ui_story_5075_50751102_91_dialog_content = "Haha, I'm just glad it worked out! How are things looking outside?",
  ui_story_5075_50751102_92_dialog_content = "We are still holding in the city, but it's up to Yuebai for the outskirts.",
  ui_story_5075_50751102_93_dialog_content = "Good. As for outside of the city, the steward of the Royal Guesthouse... This man just said their plan is nearing completion.",
  ui_story_5075_50751102_94_dialog_content = "It's possible that Yoh has fully merged with the black mist by now.",
  ui_story_5075_50751102_95_dialog_content = "We need to find him and put a stop to this right away!",
  ui_story_5075_50751102_96_dialog_content = "Then come with me.",
  ui_story_5075_50751102_97_dialog_content = "I've arranged for a small vessel to take us directly to the bay.",
  ui_story_5075_50751102_98_dialog_content = "Dantang has the city. I'll go with Yuebai to find Yoh... Huh?",
  ui_story_5075_50751102_99_dialog_content = "Uh... Dragon Maiden?",
  ui_story_5075_50751102_100_dialog_content = "I don't quite get this, but somebody punished the guy who broke the seal for me, right?",
  ui_story_5075_50751102_101_dialog_content = "I'll come with you to the seashore!",
  ui_story_5075_50751102_102_dialog_content = "The mirage created by Yoh might be too formidable for a Caelestite's powers to conquer alone.",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_2_dialog_content = "Hmm... Sorry, I must've fallen asleep. Are we there yet, Yue...",
  ui_story_5075_50751201_3_dialog_content = "Huh?",
  ui_story_5075_50751201_4_dialog_content = "Whose name was I trying to say just now?",
  ui_story_5075_50751201_5_dialog_content = "More importantly, what am I doing on this ship?",
  ui_story_5075_50751201_6_dialog_content = "Urgh... My head hurts.",
  ui_story_5075_50751201_7_dialog_content = "Hey, you're daydreaming again? Move it, and keep shifting that cargo! We're setting sail soon.",
  ui_story_5075_50751201_8_dialog_content = "L-Load the cargo? Me?",
  ui_story_5075_50751201_9_dialog_content = "Ain't nobody else here.",
  ui_story_5075_50751201_10_dialog_content = "Wasn't it you who said your kin, Soroz or whatever, got sick, and you needed to work to collect medicine money fast?",
  ui_story_5075_50751201_11_dialog_content = "Who knows if this overseas voyage they talk about will be of a safe return.",
  ui_story_5075_50751201_12_dialog_content = "Good thing that the Lin Guild may be small, but they're willing to pay big for this trip, even giving half upfront.",
  ui_story_5075_50751201_13_dialog_content = "With this money, I can finally get some good grub for my wife and kids.",
  ui_story_5075_50751201_14_dialog_content = "Your family won't have to worry about medicine money for a while, right?",
  ui_story_5075_50751201_15_dialog_content = "(Something's not right about this, but what he's saying does make sense...)",
  ui_story_5075_50751201_16_dialog_content = "(Argh... My head is hurting again.)",
  ui_story_5075_50751201_17_dialog_content = "(I'd better just load this cargo.)",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_19_dialog_content = "Huh? What's going on?",
  ui_story_5075_50751201_20_dialog_content = "Where's all this fog coming from?",
  ui_story_5075_50751201_21_dialog_content = "Lost your mind from hunger? We've been stuck in this fog for almost two weeks now, just going in circles.",
  ui_story_5075_50751201_22_dialog_content = "Looks like all of us on this ship might meet our end here.",
  ui_story_5075_50751201_23_dialog_content = "Got my wife and kids waiting back home, I can't die now...",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>His sigh elicits a wave of sorrowful weeps.</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>The crew and merchants lie scattered across the deck, their breaths tinged with weary despair.</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5075_50751201_27_dialog_content = "(Did something just crash into the ship?)",
  ui_story_5075_50751201_28_dialog_content = "Quick... Come over and look!",
  ui_story_5075_50751201_29_dialog_content = "Those fish, those fish are pushing the ship from below!",
  ui_story_5075_50751201_30_dialog_content = "They're serpentfish! We're in luck! It's winter, and they always go back to Longzhou at this time of the year!",
  ui_story_5075_50751201_31_dialog_content = "Follow them, and we can get out of here!",
  ui_story_5075_50751201_32_dialog_content = "See that? It's a divine blessing! Deities must've heard us!",
  ui_story_5075_50751201_33_dialog_content = "(Am I hallucinating or something? That serpentfish at the very front... Why does it look so familiar?)",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_35_dialog_content = "I am... a serpentfish.",
  ui_story_5075_50751201_36_dialog_content = "I hunt for my food as I travel the seas, and occasionally I seek the advice of fellow Luminatics users.",
  ui_story_5075_50751201_37_dialog_content = "Every winter, we return to Longzhou, the place of our birth.",
  ui_story_5075_50751201_38_dialog_content = "One day, we discovered a ship lost at sea.",
  ui_story_5075_50751201_39_dialog_content = "It followed us back to the shores of Longzhou, where their leader made a pact with our own.",
  ui_story_5075_50751201_40_dialog_content = "Every winter since then, we have escorted that ship on our voyages to Longzhou.",
  ui_story_5075_50751201_41_dialog_content = "We guided its course, and in return, they offered us food.",
  ui_story_5075_50751201_42_dialog_content = "It was an agreeable exchange, one that should have made us happy.",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_44_dialog_content = "Boss, boss? Zoning out at the serpentfish again?",
  ui_story_5075_50751201_45_dialog_content = "Sorry, but for some reason, one of those serpentfish looks really familiar.",
  ui_story_5075_50751201_46_dialog_content = "They all look the same. What's there to see? Here, check this out.",
  ui_story_5075_50751201_47_dialog_content = "Here's your cut from the overseas voyage.",
  ui_story_5075_50751201_48_dialog_content = "That's way too much!",
  ui_story_5075_50751201_49_dialog_content = "Ever since the Lins started the ocean route, we've been making more and more. This is but a trifle.",
  ui_story_5075_50751201_50_dialog_content = "Interested in making some more cash?",
  ui_story_5075_50751201_51_dialog_content = "I-I can make even more?",
  ui_story_5075_50751201_52_dialog_content = "I've talked with the others before coming here. The business of the Lin Guild is expanding.",
  ui_story_5075_50751201_53_dialog_content = "There is more and more need for trading with places like Astra. Just one voyage a year won't even come close to meeting the demand!",
  ui_story_5075_50751201_54_dialog_content = "How about we team up and talk to the guildmaster about adding another run?",
  ui_story_5075_50751201_55_dialog_content = "Two trips a year, how does that sound?",
  ui_story_5075_50751201_56_dialog_content = "But I think the serpentfish only return to Longzhou in winter?",
  ui_story_5075_50751201_57_dialog_content = "They're just roaming the sea most of the time. An additional journey back to Longzhou shouldn't matter much.",
  ui_story_5075_50751201_58_dialog_content = "With the extra money we earn, we can buy more fish food for them, right?",
  ui_story_5075_50751201_59_dialog_content = "I don't think the serpentfish really care about that.",
  ui_story_5075_50751201_60_dialog_content = "Tsk, seems impossible to talk you into this. Never mind then. Everyone else is on board, so your not going is not a big deal.",
  ui_story_5075_50751201_61_dialog_content = "Wait, I'm not—",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_63_dialog_content = "Afterward, our leader told us that we would have to return to Longzhou in the summer as well.",
  ui_story_5075_50751201_64_dialog_content = "The summer waters are hot and unpleasant.",
  ui_story_5075_50751201_65_dialog_content = "But our friends aboard the ship needed our help.",
  ui_story_5075_50751201_66_dialog_content = "So we agreed.",
  ui_story_5075_50751201_67_dialog_content = "Even though the voyage was long and tiring, we agreed.",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_69_dialog_content = "Today, I've gathered everyone here to make an announcement.",
  ui_story_5075_50751201_70_dialog_content = "We've secured a business deal from Yangjing, and to meet the demand, we must make another long voyage this year.",
  ui_story_5075_50751201_71_dialog_content = "But wait, our agreement with the serpentfish only covers a single trip per year.",
  ui_story_5075_50751201_72_dialog_content = "Asking them to guide us to Longzhou in summer is already a breach of contract, not to mention—",
  ui_story_5075_50751201_73_dialog_content = "This is a deal from Yangjing, something many guilds dream of.",
  ui_story_5075_50751201_74_dialog_content = "Do you even realize how much profit this deal will bring to the Lins?",
  ui_story_5075_50751201_75_dialog_content = "I understand this decision is unfair to the serpentfish, and I will personally apologize to the fiendling afterward.",
  ui_story_5075_50751201_76_dialog_content = "That's our plan now.",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_78_dialog_content = "That year, we returned to Longzhou three times.",
  ui_story_5075_50751201_79_dialog_content = "Our leader said that was only temporary, and that our friends were in trouble.",
  ui_story_5075_50751201_80_dialog_content = "But the next year saw three trips as well. The year after that was no different.",
  ui_story_5075_50751201_81_dialog_content = "Several of our kind had already disappeared.",
  ui_story_5075_50751201_82_dialog_content = "After that, our leader passed away unexpectedly.",
  ui_story_5075_50751201_83_dialog_content = "And so, I became the new leader of the serpentfish.",
  ui_story_5075_50751201_84_dialog_content = "Our friends aboard the ship appeared one day. They brought me ashore and placed me in a tank within a wooden building.",
  ui_story_5075_50751201_85_dialog_content = "The tank was so small and cramped.",
  ui_story_5075_50751201_86_dialog_content = "It was unbearable.",
  ui_story_5075_50751201_87_dialog_content = "The fourth year saw another three trips to Longzhou.",
  ui_story_5075_50751201_88_dialog_content = "But even during our voyages, they refused to let me swim in the ocean.",
  ui_story_5075_50751201_89_dialog_content = "They brought my tank aboard their ship and kept me well-fed. They said that my only concern was to instruct my kind from up there.",
  ui_story_5075_50751201_90_dialog_content = "They called it \"worship,\" a way of showing their respect to fiendlings.",
  ui_story_5075_50751201_91_dialog_content = "Already able to shift your form, huh?",
  ui_story_5075_50751201_92_dialog_content = "...",
  ui_story_5075_50751201_93_dialog_content = "But you still can't speak, can you?",
  ui_story_5075_50751201_94_dialog_content = "Would you like to learn? I can teach you. Consider it a compensation...",
  ui_story_5075_50751201_95_dialog_content = "Never mind, you can't understand what I'm saying anyway.",
  ui_story_5075_50751201_96_dialog_content = "Plus, the wrongs I've done to you are not something a few small acts can fix.",
  ui_story_5075_50751201_97_dialog_content = "(I knew that he was their leader.)",
  ui_story_5075_50751201_98_dialog_content = "(He taught me to speak and read their language.)",
  ui_story_5075_50751201_99_dialog_content = "(But I also knew that he was a wicked, wicked man.)",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_101_dialog_content = "Four trips?",
  ui_story_5075_50751201_102_dialog_content = "The Qi Family has been eyeing the Imperial Merchant title, wanting to challenge our Lin Guild.",
  ui_story_5075_50751201_103_dialog_content = "Without more notable accomplishments, we might be out of the game.",
  ui_story_5075_50751201_104_dialog_content = "We cannot let the century-old glory of the Lin Family be tarnished under our watch.",
  ui_story_5075_50751201_105_dialog_content = "For the last few years, the serpentfish have been dying in greater and greater numbers! Don't pretend that you don't know!",
  ui_story_5075_50751201_106_dialog_content = "And? So what?",
  ui_story_5075_50751201_107_dialog_content = "What do you mean, \"So what?\" What do you plan to do about it?",
  ui_story_5075_50751201_108_dialog_content = "When we needed to ship more goods, we started doing two trips. After receiving an urgent request, it went up to three.",
  ui_story_5075_50751201_109_dialog_content = "The Lin Family owes its immense success to the serpentfish!",
  ui_story_5075_50751201_110_dialog_content = "They saved us from certain death and even agreed to help us, and this is how we repay them?",
  ui_story_5075_50751201_111_dialog_content = "Stop trying to hide your greed with such high-sounding excuses!",
  ui_story_5075_50751201_112_dialog_content = "PlayerName...",
  ui_story_5075_50751201_113_dialog_content = "Urgh... Who was that just now?",
  ui_story_5075_50751201_114_dialog_content = "You take pay from our Lin Guild but seem more devoted to the serpentfish, huh?",
  ui_story_5075_50751201_115_dialog_content = "We have no use for someone like you. You're dismissed.",
  ui_story_5075_50751201_116_dialog_content = "I have to attend a meeting about the fourth voyage. You go settle your monthly payment with the steward yourself.",
  ui_story_5075_50751201_117_dialog_content = "... Are you sure you want to go through with this?",
  ui_story_5075_50751201_118_dialog_content = "What do you want?",
  ui_story_5075_50751201_119_dialog_content = "I'm going to return the serpentfish leader back to the sea.",
  ui_story_5075_50751201_120_dialog_content = "There! I found the tank!",
  ui_story_5075_50751201_121_dialog_content = "I'm sorry, but to return you to the ocean, I'll have to take you out of the water for a while.",
  ui_story_5075_50751201_122_dialog_content = "Stop him!",
  ui_story_5075_50751201_123_dialog_content = "Where did all of these people come from? I have to find a way past them...",
  ui_story_5075_50751201_124_dialog_content = "Force Boost!",
  ui_story_5075_50751201_125_dialog_content = "Urgh!",
  ui_story_5075_50751201_126_dialog_content = "... Huh? What's that power?",
  ui_story_5075_50751201_127_dialog_content = "PlayerName!",
  ui_story_5075_50751201_128_dialog_content = "... Chen'ni?",
  ui_story_5075_50751201_129_dialog_content = "About time you notice me.",
  ui_story_5075_50751201_130_dialog_content = "As soon as our vessel got into the bay, you and Yuebai dozed off. I couldn't wake you up no matter what I tried.",
  ui_story_5075_50751201_131_dialog_content = "I was so bored and wanted you two to get up.",
  ui_story_5075_50751201_132_dialog_content = "I remember now! The moment we sailed into the bay, a huge wave of black mist came right at us!",
  ui_story_5075_50751201_133_dialog_content = "That power must be what trapped us in this dream... Or is it some kind of illusion?",
  ui_story_5075_50751201_134_dialog_content = "Either way.",
  ui_story_5075_50751201_135_dialog_content = "You're way too calm about this!",
  ui_story_5075_50751201_136_dialog_content = "That's not what's important.",
  ui_story_5075_50751201_137_dialog_content = "You'd better go check Yuebai now.",
  ui_story_5075_50751201_138_dialog_content = "She seems to be suffering badly.",
  ui_story_5075_50751201_139_dialog_content = "Is this the black mist's corruption? Chen'ni, can't you...",
  ui_story_5075_50751201_140_dialog_content = "I can, but not this time.",
  ui_story_5075_50751201_141_dialog_content = "But why—",
  ui_story_5075_50751201_142_dialog_content = "It's not good to rely on deities for everything.",
  ui_story_5075_50751201_143_dialog_content = "You gotta handle your own business.",
  ui_story_5075_50751201_144_dialog_content = "... I understand.",
  ui_story_5075_50751201_145_option_content = "Psychic Scan!",
  ui_story_5075_50751201_146_dialog_content = "Yuebai! Where are you?",
  ui_story_5075_50751201_147_dialog_content = "PlayerName.",
  ui_story_5075_50751201_148_dialog_content = "This serpentfish... Is that you, Yuebai?",
  ui_story_5075_50751201_149_dialog_content = "Stop!",
  ui_story_5075_50751201_150_dialog_content = "Not this again!",
  ui_story_5075_50751201_151_dialog_content = "... Come on, we have to get to the beach!",
  ui_story_5075_50751201_152_dialog_content = "Phew... We... We made it.",
  ui_story_5075_50751201_153_dialog_content = "Why do I have to exhaust myself even in a dream?",
  ui_story_5075_50751201_154_dialog_content = "Let's just get you in the water for now, Yuebai. After that, we'll...",
  ui_story_5075_50751201_155_dialog_content = "Yuebai?",
  ui_story_5075_50751201_156_dialog_content = "(I lost sight of her as soon as she went in...)",
  ui_story_5075_50751201_157_dialog_content = "(The water... It's full of black mist!)",
  ui_story_5075_50751201_158_dialog_content = "...",
  ui_story_5075_50751201_159_dialog_content = "(Leader, I'm tired. Leader, I'm hungry. Leader, it hurts.)",
  ui_story_5075_50751201_160_dialog_content = "(I hate this. I want to go back. Leader, please save me.)",
  ui_story_5075_50751201_161_dialog_content = "(Save us. Leader... Save us.)",
  ui_story_5075_50751201_162_dialog_content = "(The others are calling to me.)",
  ui_story_5075_50751201_163_dialog_content = "(So confused. So chaotic. These voices... The hearts of the serpentfish are crying out.)",
  ui_story_5075_50751201_164_dialog_content = "Those. Voices.",
  ui_story_5075_50751201_165_dialog_content = "They. Call. Out. Everyday.",
  ui_story_5075_50751201_166_dialog_content = "Always. Always.",
  ui_story_5075_50751201_167_dialog_content = "They. Hate.",
  ui_story_5075_50751201_168_dialog_content = "Yoh.",
  ui_story_5075_50751201_169_dialog_content = "I see now.",
  ui_story_5075_50751201_170_dialog_content = "What I experienced just now were your own memories.",
  ui_story_5075_50751201_171_dialog_content = "The. Lins.",
  ui_story_5075_50751201_172_dialog_content = "Betrayers. They.",
  ui_story_5075_50751201_173_dialog_content = "People. Can't. Be. Trusted.",
  ui_story_5075_50751201_174_dialog_content = "You. Are. Fish. Too.",
  ui_story_5075_50751201_175_dialog_content = "Should. Detest!",
  ui_story_5075_50751201_176_dialog_content = "Yuebai! Can you hear me?",
  ui_story_5075_50751201_177_dialog_content = "I'm coming to find you!",
  ui_story_5075_50751201_178_dialog_content = "There's no need, PlayerName.",
  ui_story_5075_50751201_179_dialog_content = "Huh?",
  ui_story_5075_50751201_180_dialog_content = "The Lin Family did this to Yoh.",
  ui_story_5075_50751201_181_dialog_content = "And since I was given full authority over the Lin Family today, Yoh is fully justified in exacting his vengeance upon me.",
  ui_story_5075_50751201_182_dialog_content = "...",
  ui_story_5075_50751201_183_dialog_content = "The black mist is stopping?",
  ui_story_5075_50751201_184_dialog_content = "No... Not right...",
  ui_story_5075_50751201_185_dialog_content = "I... No...",
  ui_story_5075_50751201_186_dialog_content = "What's wrong with Yoh? He looks like he's in a lot of pain...",
  ui_story_5075_50751201_187_dialog_content = "That's because this isn't what he truly wants.",
  ui_story_5075_50751201_188_dialog_content = "The Yoh I know cares for both his friends and his own kind. He wouldn't want his hatred to hurt them or any other fiendlings.",
  ui_story_5075_50751201_189_dialog_content = "What's more, not all of us are as wicked as our predecessors.",
  ui_story_5075_50751201_190_dialog_content = "I'm sure you saw what PlayerName tried to do.",
  ui_story_5075_50751201_191_dialog_content = "If he were a part of the Lin Family at the time... I'm certain he would have done exactly the same.",
  ui_story_5075_50751201_192_dialog_content = "...",
  ui_story_5075_50751201_193_dialog_content = "The Lin Family has kept you trapped long enough.",
  ui_story_5075_50751201_194_dialog_content = "I won't allow anyone else to keep you shackled by hatred.",
  ui_story_5075_50751201_195_dialog_content = "I can hear the voices of the serpentfish as well.",
  ui_story_5075_50751201_196_dialog_content = "Which is why I'm going to save you.",
  ui_story_5075_50751201_197_dialog_content = "No!",
  ui_story_5075_50751201_198_dialog_content = "I. Hate!",
  ui_story_5075_50751201_199_dialog_content = "You. Are. Too.",
  ui_story_5075_50751201_200_dialog_content = "<size=45>Betrayer!</size>",
  ui_story_5075_50751202_1_dialog_content = "Great! You're finally awake. Kids who sleep in stunt their own growth, you know.",
  ui_story_5075_50751202_2_dialog_content = "Really? So if I start going to bed and waking up earlier... Can I still get a little taller?",
  ui_story_5075_50751202_3_dialog_content = "You can try praying to me!",
  ui_story_5075_50751202_4_dialog_content = "And Yuebai too.",
  ui_story_5075_50751202_5_dialog_content = "I'm not a child anymore.",
  ui_story_5075_50751202_6_dialog_content = "Oh, you are one compared to me.",
  ui_story_5075_50751202_7_dialog_content = "So don't frown all the time. After all, Yoh just didn't want to fight you and ran away.",
  ui_story_5075_50751202_8_dialog_content = "As long as he's still there, it's easy-peasy to get him out of the sea.",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>Suddenly, Chen'ni raises her hand and casts a beam of golden light into the sea.</color>",
  ui_story_5075_50751202_10_dialog_content = "I probably shouldn't ask about what you did just now, right?",
  ui_story_5075_50751202_11_dialog_content = "Well, it doesn't matter to me anymore, so might as well break the rest of the seals.",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>The previously calm sea surface suddenly churns violently, with towering waves rising.</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>A figure rises from the ocean to mid-air.</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>Countless whirlpools tear asunder the sea surface, from which boundless black mist emerges.</color>",
  ui_story_5075_50751202_16_dialog_content = "Is that the Yoh you've been alluding to? He's quite young.",
  ui_story_5075_50751202_17_dialog_content = "I. Know. You.",
  ui_story_5075_50751202_18_dialog_content = "Chen. Dragon.",
  ui_story_5075_50751202_19_dialog_content = "He knows me from the rage possessing him? That's a long time to keep a grudge.",
  ui_story_5075_50751202_20_dialog_content = "I. Want. Revenge.",
  ui_story_5075_50751202_21_dialog_content = "Don't. You. Interfere.",
  ui_story_5075_50751202_22_dialog_content = "Or. Else.",
  ui_story_5075_50751202_23_dialog_content = "Flood. City.",
  ui_story_5075_50751202_24_dialog_content = "Oh, don't tell me you are...",
  ui_story_5075_50751202_25_dialog_content = "(This is my first time seeing Chen'ni this serious.)",
  ui_story_5075_50751202_26_dialog_content = "(Can she really do nothing for Yoh?)",
  ui_story_5075_50751202_27_dialog_content = "So does he mean if Chen'ni intervenes, he'll flood the entire Haojin?",
  ui_story_5075_50751202_28_dialog_content = "He's taking the entire city hostage.",
  ui_story_5075_50751202_29_dialog_content = "So you're...",
  ui_story_5075_50751202_30_dialog_content = "Threatening me?",
  ui_story_5075_50751202_31_dialog_content = "Huh?",
  ui_story_5075_50751202_32_dialog_content = "This is neat! Nobody has threatened me for a few centuries!",
  ui_story_5075_50751202_33_dialog_content = "But on second thought, I really don't have anything to do with this.",
  ui_story_5075_50751202_34_dialog_content = "The events feel complicated, and I don't quite get it.",
  ui_story_5075_50751202_35_dialog_content = "But you mortals broke the seal, and Yoh's animosity is also an issue between mortals and fiendlings.",
  ui_story_5075_50751202_36_dialog_content = "So it should be handled between mortals and fiendlings.",
  ui_story_5075_50751202_37_dialog_content = "Yes, I make a lot of sense!",
  ui_story_5075_50751202_38_dialog_content = "This is definitely not the time for you to be \"logical\"!",
  ui_story_5075_50751202_39_dialog_content = "However, neat as it may be, I don't like being threatened.",
  ui_story_5075_50751202_40_dialog_content = "So—",
  ui_story_5075_50751202_41_dialog_content = "(Chen'ni just took off and flew up to Yoh!)",
  ui_story_5075_50751202_42_dialog_content = "Thud, thud!",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>Chen'ni lifts her fist, lightly tapping Yoh's head.</color>",
  ui_story_5075_50751202_44_dialog_content = "I'm making a move. What are you doing about it?",
  ui_story_5075_50751202_45_dialog_content = "Chen'ni?",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>As if to express Yoh's anger, the sea surface bursts open.</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>Successive layers of massive waves rise. Instead of subsiding, they keep growing even higher amidst the echoing tumult of the sea.</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>The beach where we stand is quickly inundated.</color>",
  ui_story_5075_50751202_50_dialog_content = "At this rate, we're all gonna drown!",
  ui_story_5075_50751202_51_dialog_content = "Don't worry, I'm fairly agile in the water. I'll save you if you start to drown.",
  ui_story_5075_50751202_52_dialog_content = "I'd rather not start that process in the first place!",
  ui_story_5075_50751202_53_dialog_content = "Oops, almost forgot about you two.",
  ui_story_5075_50751202_54_dialog_content = "(We're flying?)",
  ui_story_5075_50751202_55_dialog_content = "My supernatural power comes in handy, doesn't it?",
  ui_story_5075_50751202_56_dialog_content = "What about Yoh?",
  ui_story_5075_50751202_57_dialog_content = "Didn't he say something about <color=#FFB400>flooding the city</color>? He's on the way to Haojin right now.",
  ui_story_5075_50751202_58_dialog_content = "I-Isn't that an even worse turn of events?",
  ui_story_5075_50751202_59_dialog_content = "Why did you have to provoke him like that?",
  ui_story_5075_50751202_60_dialog_content = "Don't be such a nervous wreck, PlayerName.",
  ui_story_5075_50751202_61_dialog_content = "I've lived a very long time and have been watching the creatures in Longzhou for a long time too.",
  ui_story_5075_50751202_62_dialog_content = "Whether it's Yoh or you.",
  ui_story_5075_50751202_63_dialog_content = "Neither should underestimate them.",
  ui_story_5075_50751301_1_dialog_content = "Heaven's will—",
  ui_story_5075_50751301_2_dialog_content = "Roar!",
  ui_story_5075_50751301_3_dialog_content = "Urgh, knock one down and another gets back up.",
  ui_story_5075_50751301_4_dialog_content = "The black mist in the city is getting even thicker. I'm starting to miss the time when I couldn't see it.",
  ui_story_5075_50751301_5_dialog_content = "Even rope isn't enough to tie down these frenzied fiendlings. If only I had a way of expelling the grudge from their bodies...",
  ui_story_5075_50751301_6_dialog_content = "Make ways! I got the cure!",
  ui_story_5075_50751301_7_dialog_content = "Y-You're giving medicine to the fiendlings?",
  ui_story_5075_50751301_8_dialog_content = "Isn't it obvious?",
  ui_story_5075_50751301_9_dialog_content = "But their loss of control isn't being caused by a disease, but the corruption born of grudge—",
  ui_story_5075_50751301_10_dialog_content = "So to you, doctors can only treat diseases?",
  ui_story_5075_50751301_11_dialog_content = "Since that energy has to get inside a fiendling to take effect, it can be equated to a toxin.",
  ui_story_5075_50751301_12_dialog_content = "And there's a cure to every toxin.",
  ui_story_5075_50751301_13_dialog_content = "The dark mist has pervaded the city. Even Tinytail... my brother's afflicted.",
  ui_story_5075_50751301_14_dialog_content = "But I got a potion to balance inner Lumina from my teacher for him. He got a lot better after taking it.",
  ui_story_5075_50751301_15_dialog_content = "That's why I run outside and try to help.",
  ui_story_5075_50751301_16_dialog_content = "Ha!",
  ui_story_5075_50751301_17_dialog_content = "Your brother... Is that so? Then that must mean you're a <color=#FFB400>fiendling</color> as well.",
  ui_story_5075_50751301_18_dialog_content = "What, you've got something against fiendlings?",
  ui_story_5075_50751301_19_dialog_content = "Not at all! I was just thinking that you're quite an incredible doctor.",
  ui_story_5075_50751301_20_dialog_content = "You really think so? Well, at least you recognize talent when you see it.",
  ui_story_5075_50751301_21_dialog_content = "But I'm actually not that special...",
  ui_story_5075_50751301_22_dialog_content = "I have the cure on me, but the fiendlings are running amok, and it's tough for me to administer it to them.",
  ui_story_5075_50751301_23_dialog_content = "Leave that to me!",
  ui_story_5075_50751301_24_dialog_content = "I'll knock out every fiendling I see and bring them over to you for treatment!",
  ui_story_5075_50751301_25_dialog_content = "Quiet, not so loud!",
  ui_story_5075_50751301_26_dialog_content = "We sneaked out on our own. We'll be in big trouble if we're caught.",
  ui_story_5075_50751301_27_dialog_content = "Oh, got it! I used to do stuff like this when I was a kid too.",
  ui_story_5075_50751301_28_dialog_content = "Don't worry, I'll keep a lookout and make sure no one sees you.",
  ui_story_5075_50751301_29_dialog_content = "My name's Luo Song, and this is my partner, Ah Ding.",
  ui_story_5075_50751301_30_dialog_content = "Roar!",
  ui_story_5075_50751301_31_dialog_content = "I'm Liqing, and this is Tinytail, my big brother.",
  ui_story_5075_50751301_32_dialog_content = "Ha!",
  ui_story_5075_50751301_33_dialog_content = "A pleasure working with you!",
  ui_story_5075_50751301_34_dialog_content = "Ha-howl!",
  ui_story_5075_50751301_35_dialog_content = "Squeak!",
  ui_story_5075_50751301_36_dialog_content = "Just wait here for me, Dr. Liqing. I'll go scout ahead!",
  ui_story_5075_50751301_37_dialog_content = "Hey, wait!",
  ui_story_5075_50751301_38_dialog_content = "Have you no patience?",
  ui_story_5075_50751301_39_dialog_content = "Help... I need help!",
  ui_story_5075_50751301_40_dialog_content = "Stay back! The stick in my hand isn't for show!",
  ui_story_5075_50751301_41_dialog_content = "Squeak!",
  ui_story_5075_50751301_42_dialog_content = "You monsters, don't think we're easy to bully! Ha-ah!",
  ui_story_5075_50751301_43_dialog_content = "Stop, all of you! Urgh—",
  ui_story_5075_50751301_44_dialog_content = "Luo Song!",
  ui_story_5075_50751301_45_dialog_content = "What are you doing? Who told you to charge into the middle of them?",
  ui_story_5075_50751301_46_dialog_content = "Great, now you got a blow to the shoulder and a punch to the belly.",
  ui_story_5075_50751301_47_dialog_content = "Haha, this is an emergency, isn't it?",
  ui_story_5075_50751301_48_dialog_content = "I'm fine, so just give this fiendling its medicine while I hold it down.",
  ui_story_5075_50751301_49_dialog_content = "... I can't decide whether you're careful or careless.",
  ui_story_5075_50751301_50_dialog_content = "I, I mean, sorry... for striking you...",
  ui_story_5075_50751301_51_dialog_content = "Don't worry about it. I was the one who jumped between you all of a sudden.",
  ui_story_5075_50751301_52_dialog_content = "But, but that's a fiendling! Why were you defending it?",
  ui_story_5075_50751301_53_dialog_content = "Actually, he was defending you!",
  ui_story_5075_50751301_54_dialog_content = "Oh...",
  ui_story_5075_50751301_55_dialog_content = "It's normal for someone to fight back if a fiendling attacks them. But just know that it's not fiendlings' intent to attack people.",
  ui_story_5075_50751301_56_dialog_content = "They're all innocent victims, just like you.",
  ui_story_5075_50751301_57_dialog_content = "And since no one's at fault here, no one should be allowed to get hurt.",
  ui_story_5075_50751301_58_dialog_content = "Isn't that how things should be?",
  ui_story_5075_50751301_59_dialog_content = "Alright, this fiendling is much better after the cure.",
  ui_story_5075_50751301_60_dialog_content = "We must have covered most of Haojin and cured most of the fiendlings by now.",
  ui_story_5075_50751301_61_dialog_content = "Grr.",
  ui_story_5075_50751301_62_dialog_content = "See that? They're being manipulated into attacking people, and they're perfectly docile once they return to normal.",
  ui_story_5075_50751301_63_dialog_content = "... If this is from somebody else, I won't be buying it.",
  ui_story_5075_50751301_64_dialog_content = "But since it's coming from you, I think it's true.",
  ui_story_5075_50751301_65_dialog_content = "Thank you for saving my life! I'll spread the word and tell them to seek your help if a fiendling harms someone.",
  ui_story_5075_50751301_66_dialog_content = "Really? That'd be much appreciated, thanks!",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751301_68_dialog_content = "What's happening? Why does the sky get so dark all of a sudden?",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>Pitter-patter.</color>",
  ui_story_5075_50751301_70_dialog_content = "Is it raining?",
  ui_story_5075_50751301_71_dialog_content = "Wait, this is not rain.",
  ui_story_5075_50751301_72_dialog_content = "<size=45>The night isn't falling either. A huge tidal wave is covering the sky.</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>Is Haojin being flooded?</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>The streets are filled with folks fleeing in panic.</color>",
  ui_story_5075_50751302_2_dialog_content = "Wicked spirits! The wicked spirits are bringing a flood to drown us all!",
  ui_story_5075_50751302_3_dialog_content = "RUN—",
  ui_story_5075_50751302_4_dialog_content = "Dragon Maiden, please protect us. Dragon Maiden, please help us...",
  ui_story_5075_50751302_5_dialog_content = "This isn't a problem that we can solve on our own anymore.",
  ui_story_5075_50751302_6_dialog_content = "Set us down, Chen'ni! At least let us help those people get to safety!",
  ui_story_5075_50751302_7_dialog_content = "Lady Chen'ni.",
  ui_story_5075_50751302_8_dialog_content = "I don't think it's necessary.",
  ui_story_5075_50751302_9_dialog_content = "But—",
  ui_story_5075_50751302_10_dialog_content = "Listen carefully, PlayerName.",
  ui_story_5075_50751302_11_dialog_content = "Ouch! Tripped over a brick... Hurts so bad.",
  ui_story_5075_50751302_12_dialog_content = "What place is this... Where is Mom and Dad?",
  ui_story_5075_50751302_13_dialog_content = "*weeps*",
  ui_story_5075_50751302_14_dialog_content = "Graah!",
  ui_story_5075_50751302_15_dialog_content = "Help! Someone save me!",
  ui_story_5075_50751302_16_dialog_content = "Squeak!",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>Right before the Eclipsite's hit lands, the fiendling rushes over and knocks it away.</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>The attack goes slightly off course and misses.</color>",
  ui_story_5075_50751302_19_dialog_content = "Wait, you are...",
  ui_story_5075_50751302_20_dialog_content = "This one's not loud enough. Get another one!",
  ui_story_5075_50751302_21_dialog_content = "Firecrackers burst, chasing fiendlings away, banish misfortune in a joyful way!",
  ui_story_5075_50751302_22_dialog_content = "Squeak...",
  ui_story_5075_50751302_23_dialog_content = "You're from back then...",
  ui_story_5075_50751302_24_dialog_content = "Graah!",
  ui_story_5075_50751302_25_dialog_content = "Watch out!",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>The boy dashes forward, scoops up the tiny fiendling, and rolls onto the mud-covered ground.</color>",
  ui_story_5075_50751302_27_dialog_content = "Ah Ding! Strike now!",
  ui_story_5075_50751302_28_dialog_content = "Grr...",
  ui_story_5075_50751302_29_dialog_content = "Huh? Aren't you that kid from before?",
  ui_story_5075_50751302_30_dialog_content = "Water... It's pouring down!",
  ui_story_5075_50751302_31_dialog_content = "Squeak!",
  ui_story_5075_50751302_32_dialog_content = "Wait, don't leave me behind!",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>It's like the sky's crashing down.</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>With a thunderous noise, massive waves are finally smashing down from above.</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>In the face of overwhelming power, the small city built by Aurorians on the ground is utterly powerless.</color>",
  ui_story_5075_50751302_36_dialog_content = "Ahhhhhhhh!",
  ui_story_5075_50751302_37_dialog_content = "...",
  ui_story_5075_50751302_38_dialog_content = "I, I'm not dead? What happened?",
  ui_story_5075_50751302_39_dialog_content = "... Look up there.",
  ui_story_5075_50751302_40_dialog_content = "Squeak!",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>The little fiendling hovers in mid-air, creating an unseen barrier above.</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>It's holding back the wave right in front.</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>Under the pressure, the fiendling shivers, but it's still lifting its little claws, holding up that protective barrier.</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>Then, another barrier appears not far off.</color>",
  ui_story_5075_50751302_45_dialog_content = "Roar!",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>And then, another one.</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>The barriers created by the fiendlings interweave to cover a vast expanse.</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>The waves, as heavy as a thousand tons, press down upon Haojin City, but they cannot advance an inch.</color>",
  ui_story_5075_50751302_49_dialog_content = "That's...",
  ui_story_5075_50751302_50_dialog_content = "This land has never belonged only to the Aurorians.",
  ui_story_5075_50751302_51_dialog_content = "The fiendlings have to protect their home too.",
  ui_story_5075_50751302_52_dialog_content = "Even if that Lin fogey hadn't looked for it, Yoh would've checked on the seal for his friends.",
  ui_story_5075_50751302_53_dialog_content = "Most of the Aurorians don't want to admit it, but fiendlings also have a right to the land.",
  ui_story_5075_50751302_54_dialog_content = "Are you listening, PlayerName?",
  ui_story_5075_50751302_55_dialog_content = "Yes, I heard that.",
  ui_story_5075_50751302_56_dialog_content = "And I think everyone should hear that too.",
  ui_story_5075_50751302_57_dialog_content = "Well, I can certainly help get the word out.",
  ui_story_5075_50751302_58_dialog_content = "Let's do this!",
  ui_story_5075_50751302_59_option_content = "Psychic Scan!",
  ui_story_5075_50751302_60_dialog_content = "Those two-legged, they're bad, always kicking us when they see us.",
  ui_story_5075_50751302_61_dialog_content = "But those two-legged are also good, because they can catch yummy prey.",
  ui_story_5075_50751302_62_dialog_content = "They sometimes share their food with us.",
  ui_story_5075_50751302_63_dialog_content = "Wait, what's this?",
  ui_story_5075_50751302_64_dialog_content = "Is this the voice... of the fiendlings?",
  ui_story_5075_50751302_65_dialog_content = "Blown up by heated things, scary.",
  ui_story_5075_50751302_66_dialog_content = "Being driven away, scary.",
  ui_story_5075_50751302_67_dialog_content = "This place is our home too.",
  ui_story_5075_50751302_68_dialog_content = "But we're scared too! You always steal things and ruin our food.",
  ui_story_5075_50751302_69_dialog_content = "And you even use magic we can't! W-We don't know how to deal with you!",
  ui_story_5075_50751302_70_dialog_content = "Those two-legged, dumb. They leave stuff in the corner, can't find it, and blame us.",
  ui_story_5075_50751302_71_dialog_content = "Those two-legged, so dumb. They leave food in the yard but don't leave a sign, and it ends up eaten by others.",
  ui_story_5075_50751302_72_dialog_content = "But those with two legs are smart too. Last time when my leg was hurt, they used a board to brace it, and it got better.",
  ui_story_5075_50751302_73_dialog_content = "Are we being too mean to them...",
  ui_story_5075_50751302_74_dialog_content = "Yeah, they're called fiendlings, but actually, they're just wild critters that have recently gotten the hang of things.",
  ui_story_5075_50751302_75_dialog_content = "They're both silly and smart. They're mean, yet kind. They hit us and say sorry. Those two-legged are really weird.",
  ui_story_5075_50751302_76_dialog_content = "But there's nothing we can do.",
  ui_story_5075_50751302_77_dialog_content = "Nothing we can do.",
  ui_story_5075_50751302_78_dialog_content = "We share a home, after all.",
  ui_story_5075_50751302_79_dialog_content = "Water's coming, and they can't escape.",
  ui_story_5075_50751302_80_dialog_content = "Water's coming, and the home can't escape too.",
  ui_story_5075_50751302_81_dialog_content = "Water is bad. Go away—",
  ui_story_5075_50751302_82_dialog_content = "Stay away from—",
  ui_story_5075_50751302_83_dialog_content = "<size=45>Our HOME!</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>On the barrier enveloping the entire city, a sudden golden glow swirls, and the waves that couldn't fall are scattered by the explosive force.</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>They turn into a bitter rain, quietly drizzling onto Haojin.</color>",
  ui_story_5075_50751302_86_dialog_content = "The rain just now... Did you do that, Chen'ni?",
  ui_story_5075_50751302_87_dialog_content = "What?",
  ui_story_5075_50751302_88_dialog_content = "Uh... Never mind.",
  ui_story_5075_50751302_89_dialog_content = "Those little fiendlings are really impressive.",
  ui_story_5075_50751302_90_dialog_content = "Now all that's left is to deal with Yoh.",
  ui_story_5075_50751302_91_dialog_content = "...",
  ui_story_5075_50751302_92_dialog_content = "You heard them too, right? The hearts of all those people and fiendlings?",
  ui_story_5075_50751302_93_dialog_content = "They might make mistakes and squabble from time to time, or even hurt each other for all kinds of reasons.",
  ui_story_5075_50751302_94_dialog_content = "But they also work together and help each other out, so that they can coexist in the world.",
  ui_story_5075_50751302_95_dialog_content = "All of them are living creatures born in Longzhou. They don't have any reason to hate each other, natural or otherwise.",
  ui_story_5075_50751302_96_dialog_content = "Which is why, at the very least, neither of them should have to die for the other to live.",
  ui_story_5075_50751302_97_dialog_content = "Also...",
  ui_story_5075_50751302_98_dialog_content = "Among all of those voices just now, I heard an apology meant just for you.",
  ui_story_5075_50751302_99_dialog_content = "Yoh.",
  ui_story_5075_50751302_100_dialog_content = "Sorry.",
  ui_story_5075_50751401_1_dialog_content = "Apologize.",
  ui_story_5075_50751401_2_dialog_content = "Why.",
  ui_story_5075_50751401_3_dialog_content = "Obviously.",
  ui_story_5075_50751401_4_dialog_content = "No. Remorse.",
  ui_story_5075_50751401_5_dialog_content = "No... Urgh!",
  ui_story_5075_50751401_6_dialog_content = "He's flying back to the bay! After him!",
  ui_story_5075_50751401_7_dialog_content = "Yoh!",
  ui_story_5075_50751401_8_dialog_content = "Shaken by a mere word or two... What a wimp!",
  ui_story_5075_50751401_9_dialog_content = "No... Urgh!",
  ui_story_5075_50751401_10_dialog_content = "If this is the level of hatred you're capable of, you might as well give me your body!",
  ui_story_5075_50751401_11_dialog_content = "Yoh... He's resisting the black mist's control!",
  ui_story_5075_50751401_12_dialog_content = "(That means we might have a shot right now!)",
  ui_story_5075_50751401_13_dialog_content = "Humph. The body is decent, but too weak in will.",
  ui_story_5075_50751401_14_dialog_content = "What a shame it is for a fiendling to be manipulated with ease by Aurorians.",
  ui_story_5075_50751401_15_dialog_content = "It's been a long time, Chen'ni.",
  ui_story_5075_50751401_16_dialog_content = "Not really. It's only been two snoozes.",
  ui_story_5075_50751401_17_dialog_content = "You're still your old self.",
  ui_story_5075_50751401_18_dialog_content = "It's pretty hard for us to change even if we want to.",
  ui_story_5075_50751401_19_dialog_content = "On the other hand, the mortal world did change a lot, which you definitely missed staying in the sea all this time.",
  ui_story_5075_50751401_20_dialog_content = "They've got auto-tracking clockwork birds, vibrant western paintings, and ships that can cross the ocean.",
  ui_story_5075_50751401_21_dialog_content = "Humph. No matter how well they create, they're still no more than inferior creatures.",
  ui_story_5075_50751401_22_dialog_content = "Do you judge that by lifespans?",
  ui_story_5075_50751401_23_dialog_content = "Don't you think that's odd?",
  ui_story_5075_50751401_24_dialog_content = "Aurorians have a short life, but it's them who now dominate the continent.",
  ui_story_5075_50751401_25_dialog_content = "On the contrary, a superior lifeform like us—according to you—is hardly ever seen.",
  ui_story_5075_50751401_26_dialog_content = "Must you degrade yourself like this?",
  ui_story_5075_50751401_27_dialog_content = "We noble fiendlings share the same bloodline as the <color=#FFB400>Primordial</color> ones.. Lowly Aurorians do not deserve to be mentioned in the same sentence as us!",
  ui_story_5075_50751401_28_dialog_content = "But now, even a powerless Aurorian could mock and toy with fiendlings!",
  ui_story_5075_50751401_29_dialog_content = "Are you just going to ignore the severity of this situation?",
  ui_story_5075_50751401_30_dialog_content = "Fiendlings' power and bloodline reign supreme over the Aurorians'.",
  ui_story_5075_50751401_31_dialog_content = "Why should we lower ourselves and share Longzhou with them?",
  ui_story_5075_50751401_32_option_content = "Force Boost!",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_34_dialog_content = "Force Boost!",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_36_dialog_content = "(It's no good, I can barely sense the real Yoh's presence. There's no way to reach him right now.)",
  ui_story_5075_50751401_37_dialog_content = "PlayerName, can you send my thoughts to Yoh's mind?",
  ui_story_5075_50751401_38_dialog_content = "I'll try my best, but I'm not sure he can hear us in his condition.",
  ui_story_5075_50751401_39_dialog_content = "That's fine.",
  ui_story_5075_50751401_40_dialog_content = "As denizens of the vast ocean's depths, the serpentfish would never drown so easily.",
  ui_story_5075_50751401_41_dialog_content = "Alright then, prepare yourself.",
  ui_story_5075_50751401_42_option_content = "Force Boost!",
  ui_story_5075_50751401_43_dialog_content = "Yoh, can you hear me?",
  ui_story_5075_50751401_44_dialog_content = "...",
  ui_story_5075_50751401_45_dialog_content = "Before I left, the guildmaster told me he had never apologized to you in person.",
  ui_story_5075_50751401_46_dialog_content = "He said that by doing so, he would be forcing you to tolerate his despicable behavior out of the kindness of your heart.",
  ui_story_5075_50751401_47_dialog_content = "Since he did that deliberately and accepted the spoils that came with the crime, he has no right to ask for forgiveness.",
  ui_story_5075_50751401_48_dialog_content = "That is also true of the Lins.",
  ui_story_5075_50751401_49_dialog_content = "If you believe that I am also a traitor against my serpentfish ancestry, then naturally that includes me as well.",
  ui_story_5075_50751401_50_dialog_content = "Exact your revenge as you see fit, and we will accept it.",
  ui_story_5075_50751401_51_dialog_content = "But it must be from you and you only, under no one's manipulation, in person.",
  ui_story_5075_50751401_52_dialog_content = "Or is the grudge held by the serpentfish so insignificant that you would entrust it to someone else?",
  ui_story_5075_50751401_53_dialog_content = "No.",
  ui_story_5075_50751401_54_dialog_content = "I'm getting a response!",
  ui_story_5075_50751401_55_dialog_content = "Yoh, I'm going to try and expel the negative thoughts that are controlling your body.",
  ui_story_5075_50751401_56_dialog_content = "Please try to work with me!",
  ui_story_5075_50751401_57_dialog_content = "PlayerName and Yuebai sure are slow.",
  ui_story_5075_50751401_58_dialog_content = "What did you say?",
  ui_story_5075_50751401_59_dialog_content = "I say, I don't feel like talking with you anymore.",
  ui_story_5075_50751401_60_dialog_content = "Why you...",
  ui_story_5075_50751401_61_dialog_content = "Stop the charade. You're not my kin.",
  ui_story_5075_50751401_62_dialog_content = "You're not my kin.",
  ui_story_5075_50751401_63_dialog_content = "!",
  ui_story_5075_50751401_64_dialog_content = "When I first woke up, I tried to contact my fellows.",
  ui_story_5075_50751401_65_dialog_content = "But everyone was still in slumber. From Longzhou to Cloud Island, very few responded.",
  ui_story_5075_50751401_66_dialog_content = "So the only reason I even spoke to you was because you had the black dragon's vibe.",
  ui_story_5075_50751401_67_dialog_content = "But you're not that black dragon at all, just a collection of negative emotions that stole some memories from your vessel.",
  ui_story_5075_50751401_68_dialog_content = "You left only arrogance in Black Dragon and only hatred in Yoh.",
  ui_story_5075_50751401_69_dialog_content = "That's because it's the only two things you've got.",
  ui_story_5075_50751401_70_dialog_content = "You keep emphasizing compatriotism, yet hold no sympathy for fiendlings.",
  ui_story_5075_50751401_71_dialog_content = "You claim to be noble, yet cling to nothing but cowardice.",
  ui_story_5075_50751401_72_dialog_content = "You don't even have a personality to speak of and hide behind a facade.",
  ui_story_5075_50751401_73_dialog_content = "Do you truly believe you can lay claim to being a higher lifeform?",
  ui_story_5075_50751401_74_dialog_content = "What's wrong with not having a personality? I am a true immortal!",
  ui_story_5075_50751401_75_dialog_content = "Even the so-called deities like you cannot measure up to me in longevity! I...",
  ui_story_5075_50751401_76_dialog_content = "Now, before it regains its composure!",
  ui_story_5075_50751401_77_option_content = "Force Boost!",
  ui_story_5075_50751401_78_dialog_content = "It. Is. My. Body.",
  ui_story_5075_50751401_79_dialog_content = "Get. Out!",
  ui_story_5075_50751401_80_dialog_content = "Urgh!",
  ui_story_5075_50751401_81_dialog_content = "What?",
  ui_story_5075_50751401_82_dialog_content = "Thanks to your distraction, Chen'ni, we were able to find it!",
  ui_story_5075_50751401_83_dialog_content = "Now we just have to help Yoh expel it from the inside...",
  ui_story_5075_50751401_84_dialog_content = "Think again!",
  ui_story_5075_50751402_1_dialog_content = "Tsk, tsk... Just a useless husk. What does it matter if I return it to you?",
  ui_story_5075_50751402_2_dialog_content = "This is where my original body is buried.",
  ui_story_5075_50751402_3_dialog_content = "Even in this state, I'm not something you can handle!",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>The sea in the distance roils once again.</color>",
  ui_story_5075_50751402_5_dialog_content = "(But I refuse to see Haojin underwater again.)",
  ui_story_5075_50751402_6_dialog_content = "Chen'ni, you said I could use this to ask you for a wish, right?",
  ui_story_5075_50751402_7_dialog_content = "Oh?",
  ui_story_5075_50751402_8_dialog_content = "What wish do you have in mind?",
  ui_story_5075_50751402_9_dialog_content = "That thing isn't an Aurorian or a fiendling, or even an Eclipsite.",
  ui_story_5075_50751402_10_dialog_content = "It's nothing but a disembodied mass of evil intent.",
  ui_story_5075_50751402_11_dialog_content = "O Almighty Benevolent Dragon Divinity, would you please get rid of this evil and return peace to this place once more?",
  ui_story_5075_50751402_12_dialog_content = "Granted.",
  ui_story_5075_50751402_13_dialog_content = "Tsk, tsk... It's been eight hundred years, and your virtuous Dragon Maiden wouldn't lift a finger when I flooded Haojin.",
  ui_story_5075_50751402_14_dialog_content = "The offerings must be lacking, so she suffers a decline in power—",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>In one fleeting moment, a golden lotus radiates brilliance.</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>A crystal-clear, ethereal figure rises between the sea and sky.</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>Splendid golden light spreads like ripples, and wherever it reaches, wicked spirits vanish into thin air.</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>Inside Haojin City</color>",
  ui_story_5075_50751402_19_dialog_content = "Growl...",
  ui_story_5075_50751402_20_dialog_content = "The wicked spirits in the city... They've all disappeared?",
  ui_story_5075_50751402_21_dialog_content = "Look! Look at the sky!",
  ui_story_5075_50751402_22_dialog_content = "It's the Dragon Maiden! The Dragon Maiden has manifested, helping us ward off evil!",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>The Eclipsite remnant, taking on the form of a black dragon, turns and runs without any hesitation.</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>Only for the ethereal figure to immobilize him with a mere flick of a finger.</color>",
  ui_story_5075_50751402_25_dialog_content = "If you believe I'm weakened, why are you afraid to fight?",
  ui_story_5075_50751402_26_dialog_content = "Tsk, tsk, tsk...",
  ui_story_5075_50751402_27_dialog_content = "Never thought that after so long, you still hold onto this level of strength.",
  ui_story_5075_50751402_28_dialog_content = "But you haven't won yet!",
  ui_story_5075_50751402_29_dialog_content = "As long as the strength of the Eclipsite Archlord remains, I'm practically immortal!",
  ui_story_5075_50751402_30_dialog_content = "If you wreck this bit of me, my power's just gonna reconvene and bring me to life again.",
  ui_story_5075_50751402_31_dialog_content = "You surely can eliminate me once or twice, but can you keep wiping me out a thousand or ten thousand times?",
  ui_story_5075_50751402_32_dialog_content = "I—",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>It doesn't get to finish the sentence.</color>",
  ui_story_5075_50751402_34_dialog_content = "Things without mind and form need not exist in the world.",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>The ethereal figure crushes it.</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>The next instant, black mist once again surges over the sea.</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>Resentment and Darkflow fuse into a turbid core in the center of the black mist, rapidly taking shape.</color>",
  ui_story_5075_50751402_38_dialog_content = "I hate to admit it, but he's right. There's no way we can guard this place forever.",
  ui_story_5075_50751402_39_dialog_content = "Without a permanent solution, we can't guarantee no one will get hurt next time, and the time after that...",
  ui_story_5075_50751402_40_dialog_content = "Whose side are you on, PlayerName?",
  ui_story_5075_50751402_41_dialog_content = "But...",
  ui_story_5075_50751402_42_dialog_content = "For millennia, it is said I protected the ships sailing the sea.",
  ui_story_5075_50751402_43_dialog_content = "But in the last hundred years before I awoke, mortals continued voyaging.",
  ui_story_5075_50751402_44_dialog_content = "They are able to protect themselves without divine intervention.",
  ui_story_5075_50751402_45_dialog_content = "That's what I love to hear!",
  ui_story_5075_50751402_46_dialog_content = "That voice...",
  ui_story_5075_50751402_47_dialog_content = "Xuan Ji!",
  ui_story_5075_50751402_48_dialog_content = "Long time no see, PlayerName.",
  ui_story_5075_50751402_49_dialog_content = "I see I made it in time for the finale.",
  ui_story_5075_50751402_50_dialog_content = "Let me show you the latest cool thing from Ye Kingdom!",
  ui_story_5075_50751402_51_dialog_content = "Operation stable. Target locked. Maximum power.",
  ui_story_5075_50751402_52_dialog_content = "<size=45>Fire!</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>Dazzling golden light cuts through the sea, and artificial thunder runs through the black mist from the center.</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>Before the black mist, trying to condense, can fill the previous breach, it gets shattered once again.</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>Following a heavy bombardment, the sea finally returns to calm.</color>",
  ui_story_5075_50751402_61_dialog_content = "It's not coming back?",
  ui_story_5075_50751402_62_dialog_content = "Right. It was completely gone without a trace before it had a chance to react.",
  ui_story_5075_50751402_63_dialog_content = "Is this one of your little inventions while I was asleep too?",
  ui_story_5075_50751402_64_dialog_content = "D-Don't put your head into the barrel!",
  ui_story_5075_50751402_65_dialog_content = "Relax, I turned it off.",
  ui_story_5075_50751402_66_dialog_content = "Don't you have important business back in the Ye Kingdom, Xuan Ji?",
  ui_story_5075_50751402_67_dialog_content = "Yes, but who knew I'd get a call from Princess Dantang halfway through?",
  ui_story_5075_50751402_68_dialog_content = "I figured Ji was in a bigger bind, so I commandeered the most advanced <color=#FFB400>arcane blaster</color> for reinforcement.",
  ui_story_5075_50751402_69_dialog_content = "Only for Her Highness to be absent...",
  ui_story_5075_50751402_70_dialog_content = "Though seeing you is good enough, PlayerName!",
  ui_story_5075_50751402_71_dialog_content = "Dantang is in the city right now.",
  ui_story_5075_50751402_72_dialog_content = "Since everything's back to normal now, why not come back with us and spend the Spring Festival here in Haojin?",
  ui_story_5075_50751402_73_dialog_content = "Oh, I remember how awesome the New Year ceremony to repel monsters is in Haojin.",
  ui_story_5075_50751402_74_dialog_content = "Too bad I have to hurry back to Ye for unfinished business.",
  ui_story_5075_50751402_75_dialog_content = "You should get back too and not miss the celebration. We'll get together later.",
  ui_story_5075_50751402_76_dialog_content = "Don't forget to give my regards to Princess Dantang.",
  ui_story_5075_50751402_77_dialog_content = "Alright then, best of luck with your official business.",
  ui_story_5075_50751402_78_dialog_content = "I'll send a clockwork bird if something's up!",
  ui_story_5075_50751402_79_dialog_content = "Hmm, this feels like a letdown.",
  ui_story_5075_50751402_80_dialog_content = "I came all the way from Ye with the arcane blaster just for a brief cameo.",
  ui_story_5075_50751402_81_dialog_content = "But even though no one hailed me as a hero then, I'm getting quite an entourage now.",
  ui_story_5075_50751402_82_dialog_content = "Lady Xuan Ji.",
  ui_story_5075_50751402_83_dialog_content = "You've taken highly classified weapons without permission.",
  ui_story_5075_50751402_84_dialog_content = "And you've even smuggled these weapons to another kingdom. You are now suspected of treason.",
  ui_story_5075_50751402_X84_dialog_content = "Well, it's debatable whether you people represent the Ye Kingdom...",
  ui_story_5075_50751402_85_dialog_content = "Did the king send you?",
  ui_story_5075_50751402_86_dialog_content = "Indeed, we, under the secret command of the <color=#FFB400>King of Ye</color>, are going to arrest you. Will you defy this order?",
  ui_story_5075_50751402_87_dialog_content = "... Not at all.",
  ui_story_5075_50751402_88_dialog_content = "I am a citizen of Ye, not to mention a former state adviser and luminary.",
  ui_story_5075_50751402_89_dialog_content = "I refuse to follow anyone who harms the interests of Ye but will never disobey the king's order.",
  ui_story_5075_50751402_90_dialog_content = "I plead guilty.",
  ui_story_5075_50751402_91_dialog_content = "...",
  ui_story_5075_50751402_92_dialog_content = "Come on, don't look so disappointed.",
  ui_story_5075_50751402_93_dialog_content = "This is my first time spending New Year's in jail, so I'd appreciate it if you let me know when I fail to follow the protocol.",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5075_50751501_2_dialog_content = "Wow, a fireworks show!",
  ui_story_5075_50751501_3_dialog_content = "After just one night, the entire city is bustling with festivity.",
  ui_story_5075_50751501_4_dialog_content = "The wicked spirits have been purged, and the misunderstanding between people and fiendlings has been resolved.",
  ui_story_5075_50751501_5_dialog_content = "Everyone should be able to enjoy a carefree Spring Festival tomorrow.",
  ui_story_5075_50751501_6_dialog_content = "Is Yoh returning to the sea too?",
  ui_story_5075_50751501_7_dialog_content = "Yes. He says he needs to be alone for some time in order to decide what to do next.",
  ui_story_5075_50751501_8_dialog_content = "Do you think he's going to get his revenge on the Lin Family?",
  ui_story_5075_50751501_9_dialog_content = "I'm not sure.",
  ui_story_5075_50751501_10_dialog_content = "But at the very least, we managed to settle our past differences. As for the future...",
  ui_story_5075_50751501_11_dialog_content = "That's a question for tomorrow, don't you think?",
  ui_story_5075_50751501_12_dialog_content = "\"Merry New Year,\" right?",
  ui_story_5075_50751501_13_dialog_content = "Li Tianxian wasn't lying after all. This ancient incantation really works!",
  ui_story_5075_50751501_14_dialog_content = "?",
  ui_story_5075_50751501_15_dialog_content = "... Heheh.",
  ui_story_5075_50751501_16_dialog_content = "Wh-Why are you laughing, Yuebai? This isn't some kind of joke, is it?",
  ui_story_5075_50751501_17_dialog_content = "No.",
  ui_story_5075_50751501_18_dialog_content = "It truly is a powerful incantation.",
  ui_story_5075_50751501_19_dialog_content = "I still have matters to attend to with the Lin Family. Until next time.",
  ui_story_5075_50751501_20_dialog_content = "Sure, see you later.",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>Crackle and pop!</color>",
  ui_story_5075_50751501_22_dialog_content = "What's going on?",
  ui_story_5075_50751501_23_dialog_content = "The monster-repelling ceremony is coming this way!",
  ui_story_5075_50751501_24_dialog_content = "Chen'ni? Where have you been all this time?",
  ui_story_5075_50751501_25_dialog_content = "And when did you get all of those snacks?",
  ui_story_5075_50751501_26_dialog_content = "I kind of made the round with my dragon horns showing, and the vendors just stuffed me with these!",
  ui_story_5075_50751501_27_dialog_content = "Oh, that's right, PlayerName has no horns or tail.",
  ui_story_5075_50751501_28_dialog_content = "Don't feel sad. I'll split the loot with you.",
  ui_story_5075_50751501_29_dialog_content = "Thanks, but that doesn't bother me much.",
  ui_story_5075_50751501_30_dialog_content = "Look, Luo Song is one of the performers.",
  ui_story_5075_50751501_31_dialog_content = "No kidding! And look, there's a bunch of fiendlings with him too!",
  ui_story_5075_50751501_32_dialog_content = "Firecrackers burst, chasing monsters away, banish misfortune in a joyful way.",
  ui_story_5075_50751501_33_dialog_content = "Blessings unfold with auspicious omens. Welcoming spring, happiness lights every face!",
  ui_story_5075_50751501_34_dialog_content = "Wait, I thought they were supposed to be driving away monsters? Why are the fiendlings chasers too?",
  ui_story_5075_50751501_35_dialog_content = "They changed it up this year—not chasing away fiendlings, but wicked spirits instead.",
  ui_story_5075_50751501_36_dialog_content = "Did you not see the Dragon Maiden's manifestation last night? She eradicated all wicked spirits, leaving the fiendlings untouched.",
  ui_story_5075_50751501_37_dialog_content = "That means that even the Dragon Maiden deems fiendlings harmless, right?",
  ui_story_5075_50751501_38_dialog_content = "Listen up! You need to learn to work together if you want to defeat a powerful opponent!",
  ui_story_5075_50751501_39_dialog_content = "By combining your unique strengths, your power will increase dramatically!",
  ui_story_5075_50751501_40_dialog_content = "Alright Ah Ding, have your new friend help you show everyone what I mean!",
  ui_story_5075_50751501_41_dialog_content = "Ha!",
  ui_story_5075_50751501_42_dialog_content = "Roar!",
  ui_story_5075_50751501_43_dialog_content = "Am I seeing things?",
  ui_story_5075_50751501_44_dialog_content = "Why does that cat look so familiar?",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>Crackle and pop!</color>",
  ui_story_5075_50751501_46_dialog_content = "Firecrackers burst, chasing monsters away... Ouch!",
  ui_story_5075_50751501_47_dialog_content = "Sorry, I wasn't watching where I was going and bumped into you… Oh.",
  ui_story_5075_50751501_48_dialog_content = "Yes?",
  ui_story_5075_50751501_49_dialog_content = "Oh, it's the kid who was picking on that little fiendling earlier.",
  ui_story_5075_50751501_50_dialog_content = "So, eh... Miss, you're a fiendling too, aren't you?",
  ui_story_5075_50751501_51_dialog_content = "Here's a candy for you!",
  ui_story_5075_50751501_52_dialog_content = "And... if you know any fiendling we've been mean to, please tell them I'm sorry!",
  ui_story_5075_50751501_53_dialog_content = "He ran off...",
  ui_story_5075_50751501_54_dialog_content = "I guess people's opinions toward fiendlings are really starting to change.",
  ui_story_5075_50751501_55_dialog_content = "Hmm... Wow!",
  ui_story_5075_50751501_56_dialog_content = "It's very sweet.",
  ui_story_5075_50751501_57_dialog_content = "I thought seeing this would make you feel happy, Chen'ni.",
  ui_story_5075_50751501_58_dialog_content = "I am happy.",
  ui_story_5075_50751501_59_dialog_content = "Then why does it feel like...",
  ui_story_5075_50751501_60_dialog_content = "Your happiness is no different than the happiness you felt yesterday or even the day before.",
  ui_story_5075_50751501_61_dialog_content = "Well, that's how it is in the world.",
  ui_story_5075_50751501_62_dialog_content = "People turn against fiendlings one day because they are afraid, then treat them nicely out of guilt the next.",
  ui_story_5075_50751501_63_dialog_content = "Who knows how they will see the fiendlings tomorrow.",
  ui_story_5075_50751501_64_dialog_content = "You might get a yummy snack yesterday, an awful one today, and then a delicious one again tomorrow.",
  ui_story_5075_50751501_65_dialog_content = "There will always be good and bad, but the good won't stay good, and the bad won't stay bad.",
  ui_story_5075_50751501_66_dialog_content = "I think I like it that way.",
  ui_story_5075_50751501_67_dialog_content = "I... can't say I really understand what you're feeling, Chen'ni.",
  ui_story_5075_50751501_68_dialog_content = "But after everything we went through, I think it makes a little more sense now.",
  ui_story_5075_50751501_69_dialog_content = "In your eyes, every living being is exactly the same. It makes no difference to you if they're people, fiendlings, or anything else.",
  ui_story_5075_50751501_70_dialog_content = "All beings have meaning behind their existence.",
  ui_story_5075_50751501_71_dialog_content = "And because you respect that meaning, you try not to interfere in our world.",
  ui_story_5075_50751501_72_dialog_content = "It's not that you don't care about us, but that you care about everyone equally.",
  ui_story_5075_50751501_73_dialog_content = "If that's the case, I'm sure our troubles these last few days must have seemed awfully petty to you.",
  ui_story_5075_50751501_74_dialog_content = "Hopefully, we didn't disappoint you too much.",
  ui_story_5075_50751501_75_dialog_content = "So what are you gonna do now, Chen'ni?",
  ui_story_5075_50751501_76_dialog_content = "I came out because I was rudely awakened.",
  ui_story_5075_50751501_77_dialog_content = "So I'll be going back to sleep in a while.",
  ui_story_5075_50751501_78_dialog_content = "So soon?",
  ui_story_5075_50751501_79_dialog_content = "Emissary! The king is asking for your presence in the palace.",
  ui_story_5075_50751501_80_dialog_content = "Uh, sure.",
  ui_story_5075_50751501_81_dialog_content = "Chen'ni, want to come along? Chen'ni?",
  ui_story_5075_50751501_82_dialog_content = "Gone already, huh?",
  ui_story_5075_50751501_83_dialog_content = "Thank you for everything, PlayerName.",
  ui_story_5075_50751501_84_dialog_content = "This time—",
  ui_story_5075_50751501_85_dialog_content = "PlayerName! PlayerName!",
  ui_story_5075_50751501_86_dialog_content = "I've heard everything from Dantang. She said you took charge in a crisis, displaying unparalleled wisdom and courage.",
  ui_story_5075_50751501_87_dialog_content = "Not only did you expose the villains in the Ji Kingdom's court, but the timely receding of yesterday's flood is also credited to you!",
  ui_story_5075_50751501_88_dialog_content = "I believe I did not exaggerate the account thusly, Crown Prince.",
  ui_story_5075_50751501_89_dialog_content = "Anyway, I know now that PlayerName is a big hero!",
  ui_story_5075_50751501_90_dialog_content = "You're awesome, hero! <size=45>I want to marry PlayerName!</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>... What?</size>",
  ui_story_5075_50751501_92_dialog_content = "As the saying goes, husband and wife are like one. With an awesome fiancée like you, I'll surely be a hero too!",
  ui_story_5075_50751501_93_dialog_content = "<size=45>Ahem!</size>",
  ui_story_5075_50751501_94_dialog_content = "Somebody escort the prince back immediately!",
  ui_story_5075_50751501_95_dialog_content = "Tell the tutor to teach him the meaning of marriage and make him stop all this nonsense that I almost fell for...",
  ui_story_5075_50751501_96_dialog_content = "However, his other remarks are not wrong.",
  ui_story_5075_50751501_97_dialog_content = "The crisis in Haojin was a miscalculation on my part, and it's thanks to you that the disaster was avoided.",
  ui_story_5075_50751501_98_dialog_content = "Hence, feel free to tell me whatever you want, and I shall surely grant it.",
  ui_story_5075_50751501_99_dialog_content = "In that case, Dantang and I would like to share our plan with you for improving relations between our two lands!",
  ui_story_5075_50751501_100_dialog_content = "Is that all? Do you not desire gold, treasure, or positions of power?",
  ui_story_5075_50751501_101_dialog_content = "To be honest, that's not entirely untrue. But I came to Longzhou as Astra's official envoy.",
  ui_story_5075_50751501_102_dialog_content = "Completing my mission is my top priority.",
  ui_story_5075_50751501_103_dialog_content = "Hahaha, for a young talent like you, I somewhat don't want to let you go back.",
  ui_story_5075_50751501_104_dialog_content = "But since you are unwilling to stay in Longzhou, how about this?",
  ui_story_5075_50751501_105_dialog_content = "I hereby declare you an Honorary Citizen of Ji Kingdom.",
  ui_story_5075_50751501_106_dialog_content = "No matter where you go or what you do henceforth, the Ji Kingdom will always welcome you.",
  ui_story_5075_50751501_107_dialog_content = "Thank you, Lord!",
  ui_story_5075_50751501_108_dialog_content = "Phew... We spent so much time in the palace, and it's getting late.",
  ui_story_5075_50751501_109_dialog_content = "After the steward was arrested, they also got rid of all those guards and maids.",
  ui_story_5075_50751501_110_dialog_content = "I think this is my first time being all alone here.",
  ui_story_5075_50751501_111_dialog_content = "... It's so quiet.",
  ui_story_5075_50751501_112_dialog_content = "Now that things have finally settled down, I'm not sure what to do with myself.",
  ui_story_5075_50751501_113_dialog_content = "Oh yeah, the Spring Festival is tomorrow.",
  ui_story_5075_50751501_114_dialog_content = "From what I've heard, every family in Longzhou is staying up all night tonight while they eat and hang out together.",
  ui_story_5075_50751501_115_dialog_content = "It's their way of saying goodbye to the last year and welcoming the new year.",
  ui_story_5075_50751501_116_dialog_content = "Maybe I should do something like that too... Nah, there's no point staying up all night by myself.",
  ui_story_5075_50751501_117_dialog_content = "I wonder what everyone's up to...",
  ui_story_5075_50751501_118_dialog_content = "Waiting for PlayerName to notice me.",
  ui_story_5075_50751501_119_dialog_content = "Huh? Wh-When did you get in here?",
  ui_story_5075_50751501_120_dialog_content = "I was here before you came back.",
  ui_story_5075_50751501_121_dialog_content = "Only to see you wander around not paying attention to anything, so I had to show myself.",
  ui_story_5075_50751501_122_dialog_content = "So you saw that, huh...",
  ui_story_5075_50751501_123_dialog_content = "I thought you were already gone.",
  ui_story_5075_50751501_124_dialog_content = "You said you were going back to the sea in a while, after all.",
  ui_story_5075_50751501_125_dialog_content = "That's right. I don't plan to stay long.",
  ui_story_5075_50751501_126_dialog_content = "I'm going back in a few decades.",
  ui_story_5075_50751501_127_dialog_content = "Wait, what? A few decades is just \"a while\" to you?",
  ui_story_5075_50751501_128_dialog_content = "Is that too quick?",
  ui_story_5075_50751501_129_dialog_content = "I like hanging out with you.",
  ui_story_5075_50751501_130_dialog_content = "So if you don't mind, it's possible for me to stick around for a hundred years or two.",
  ui_story_5075_50751501_131_dialog_content = "... Sorry, I forgot that major fiendlings have a completely different sense of time than we do.",
  ui_story_5075_50751501_132_dialog_content = "But how come you don't have anything here, PlayerName?",
  ui_story_5075_50751501_133_dialog_content = "It should be time for a New Year's Eve meal.",
  ui_story_5075_50751501_134_dialog_content = "Haha, guess I forgot.",
  ui_story_5075_50751501_135_dialog_content = "Well, these are bean curd sheets I just got as an offering. Take it.",
  ui_story_5075_50751501_136_dialog_content = "Thanks... Uh, bean curd sheets?",
  ui_story_5075_50751501_137_dialog_content = "PlayerName! Chen'ni!",
  ui_story_5075_50751501_138_dialog_content = "Where are you two?",
  ui_story_5075_50751501_139_dialog_content = "Is that Luo Song?",
  ui_story_5075_50751501_140_dialog_content = "Luo Song! Over here!",
  ui_story_5075_50751501_141_dialog_content = "Ah, there you are! Glad I finally found you two.",
  ui_story_5075_50751501_142_dialog_content = "I should have asked where you were staying before I left.",
  ui_story_5075_50751501_143_dialog_content = "Wait, have you been walking through the streets shouting our names this whole time?",
  ui_story_5075_50751501_144_dialog_content = "Haha, I know it wasn't the smartest way of looking for you, but it worked out, didn't it?",
  ui_story_5075_50751501_145_dialog_content = "After everything we've been through, you don't mind letting me celebrate the new year with you, right?",
  ui_story_5075_50751501_146_dialog_content = "Of course not!",
  ui_story_5075_50751501_147_dialog_content = "Glad to hear it.",
  ui_story_5075_50751501_148_dialog_content = "Anyway, I helped an old lady move some stuff earlier, and she gave me this bag of celery for my troubles.",
  ui_story_5075_50751501_149_dialog_content = "At the very least, we can use it to cook something up for tonight.",
  ui_story_5075_50751501_150_dialog_content = "Oh my, this place is even more deserted than my fortune-telling stand.",
  ui_story_5075_50751501_151_dialog_content = "Li Tianxian, you're here too?",
  ui_story_5075_50751501_152_dialog_content = "To mooch... I mean, to check up on you, since you're in a foreign land and all.",
  ui_story_5075_50751501_153_dialog_content = "I can't believe you don't even have a meal prepared. I guess you're lucky I'm here.",
  ui_story_5075_50751501_154_dialog_content = "Here, a New Year's gift from me.",
  ui_story_5075_50751501_155_dialog_content = "I appreciate the gesture and all, but why give me a bunch of wild vegetables?",
  ui_story_5075_50751501_156_dialog_content = "This is no ordinary veggie. It's shepherd's purse and challenging to find in winter.",
  ui_story_5075_50751501_157_dialog_content = "I had to get the batch from a greenhouse, and it cost me all the profit I made off the sugar figurines.",
  ui_story_5075_50751501_158_dialog_content = "It represents fortune and wealth, so your coffers will be full throughout the year!",
  ui_story_5075_50751501_159_dialog_content = "And you've got bean curd sheets too. That's auspicious and brings prosperity for generations to come.",
  ui_story_5075_50751501_160_dialog_content = "Celery isn't bad either. It means money through hard work.",
  ui_story_5075_50751501_161_dialog_content = "Come give me a hand, PlayerName—",
  ui_story_5075_50751501_162_dialog_content = "A guild member sent us an entire cartload of fresh lotus roots. I figured you didn't prepare any ingredients tonight, so I brought some for you.",
  ui_story_5075_50751501_163_dialog_content = "An entire cartload?",
  ui_story_5075_50751501_164_dialog_content = "Just take it. All quality stuff, you know.",
  ui_story_5075_50751501_165_dialog_content = "I see signs pointing to a good fortune for you everywhere.",
  ui_story_5075_50751501_166_dialog_content = "You think everything's auspicious, don't you?",
  ui_story_5075_50751501_167_dialog_content = "It's the New Year, of course everything is auspicious.",
  ui_story_5075_50751501_168_dialog_content = "I could hear Li swindling from a mile away.",
  ui_story_5075_50751501_169_dialog_content = "Though it is nice to speak felicitously on New Year's Eve.",
  ui_story_5075_50751501_170_dialog_content = "It's been a while, PlayerName.",
  ui_story_5075_50751501_171_dialog_content = "Dantang? Jiu? Shouldn't you be celebrating the new year back at the palace?",
  ui_story_5075_50751501_172_dialog_content = "We are supposed to.",
  ui_story_5075_50751501_173_dialog_content = "But because of your merit over the past few days, PlayerName, the king assigned me to a special task.",
  ui_story_5075_50751501_174_dialog_content = "I shall make sure you have an enjoyable New Year's.",
  ui_story_5075_50751501_175_dialog_content = "There are carts of food outside from the palace. I will cook myself and make the appropriate fares for the holiday.",
  ui_story_5075_50751501_176_dialog_content = "Oh, I would like to offer my blessing as well.",
  ui_story_5075_50751501_177_dialog_content = "With this plate of golden yellow daylilies, PlayerName...",
  ui_story_5075_50751501_178_dialog_content = "I wish you a bright future.",
  ui_story_5075_50751501_179_dialog_content = "I guess I'll offer you pea pods. They mean a full harvest in Longzhou.",
  ui_story_5075_50751501_180_dialog_content = "Wow, I see so many people!",
  ui_story_5075_50751501_181_dialog_content = "And I was worried PlayerName was going to spend New Year's Eve alone.",
  ui_story_5075_50751501_182_dialog_content = "It is good for our young friend to be this popular.",
  ui_story_5075_50751501_183_dialog_content = "Zhong Xu! Liqing! You guys are here too!",
  ui_story_5075_50751501_184_dialog_content = "Where did all this food on the table come from? Oh, I know!",
  ui_story_5075_50751501_185_dialog_content = "You're making the Ten Scenic, aren't you?",
  ui_story_5075_50751501_186_dialog_content = "What is that?",
  ui_story_5075_50751501_187_dialog_content = "It's a famous traditional Ji dish with dozens of thinly sliced, stir-fried vegetables.",
  ui_story_5075_50751501_188_dialog_content = "That combines all the auspices on one plate.",
  ui_story_5075_50751501_189_dialog_content = "It's a Spring Festival necessity in Ji.",
  ui_story_5075_50751501_190_dialog_content = "But I see something is still missing here.",
  ui_story_5075_50751501_191_dialog_content = "Allow me to contribute potherb mustard to the cause and wish everyone a great career.",
  ui_story_5075_50751501_192_dialog_content = "I'll throw in some little hogweed for good measure.",
  ui_story_5075_50751501_193_dialog_content = "It's not just a vegetable but also an anti-toxin herb.",
  ui_story_5075_50751501_194_dialog_content = "You are truly testing my culinary skills with such exotic ingredients.",
  ui_story_5075_50751501_195_dialog_content = "Oh, it won't be a challenge for you at all, Your Highness.",
  ui_story_5075_50751501_196_dialog_content = "Are you sure, Jiu? Why don't you come give me a hand in the kitchen then?",
  ui_story_5075_50751501_197_dialog_content = "I'll help too.",
  ui_story_5075_50751501_198_dialog_content = "Leave the tasting to me.",
  ui_story_5075_50751501_199_dialog_content = "I can do the tasting!",
  ui_story_5075_50751501_200_dialog_content = "Fine, I can't fight you for it, so please, have at it.",
  ui_story_5075_50751501_201_dialog_content = "I'll go out and sort the ingredients. Just tell me what you need and I'll bring it in.",
  ui_story_5075_50751501_202_dialog_content = "I also brought some decorations to place throughout the room.",
  ui_story_5075_50751501_203_dialog_content = "That's wonderful. I was just thinking this place could use more festivity!",
  ui_story_5075_50751501_204_dialog_content = "Here comes the Ten Scenic everybody's had a hand in.",
  ui_story_5075_50751501_205_dialog_content = "Before the bell of the Dragon Maiden Temple rings in a few minutes to officially usher in the New Year...",
  ui_story_5075_50751501_206_dialog_content = "My gratitude for all you have done for me in the past year, PlayerName.",
  ui_story_5075_50751501_207_dialog_content = "I'm not good with words, so I'll just say \"Thanks!\"",
  ui_story_5075_50751501_208_dialog_content = "I appreciate your business last year and look forward to your patronage next year.",
  ui_story_5075_50751501_209_dialog_content = "I am grateful for your assistance in our previous journeys, my young friend. I wish you a lovely new year.",
  ui_story_5075_50751501_210_dialog_content = "I thank you for everything. Stay healthy so you don't have to come see me for treatment!",
  ui_story_5075_50751501_211_dialog_content = "We may have just met, but I already consider you a good friend.",
  ui_story_5075_50751501_212_dialog_content = "Cheers to the new year! I wish you the strength you need to defeat any wicked spirit that comes your way!",
  ui_story_5075_50751501_213_dialog_content = "Cheers, and Happy New Year!",
  ui_story_5075_50751501_214_dialog_content = "*gulps*",
  ui_story_5075_50751501_215_dialog_content = "Hey, I didn't even get a sip! Don't you run off with it...",
  ui_story_5075_50751501_216_dialog_content = "PlayerName, PlayerName.",
  ui_story_5075_50751501_217_dialog_content = "What's the matter, Chen'ni?",
  ui_story_5075_50751501_218_dialog_content = "Lower your head.",
  ui_story_5075_50751501_219_dialog_content = "Okay, but what are you doing?",
  ui_story_5075_50751501_220_dialog_content = "Let me pat you.",
  ui_story_5075_50751501_221_dialog_content = "Be happy and content every day.",
  ui_story_5075_50751501_222_dialog_content = "This is straight from a deity, so you can bank on that!",
  ui_story_5075_50751501_223_dialog_content = "<color=#e8d9bb>Dong—dong—</color>",
  ui_story_5075_50751501_224_dialog_content = "<color=#e8d9bb>The bell of the Dragon Maiden Temple rings from the South Mountains, echoing throughout the entire city.</color>",
  ui_story_5075_50751501_225_dialog_content = "<color=#e8d9bb>A hundred and eight times it rings, cleansing worries and bringing good luck and health.</color>",
  ui_story_5075_50751501_226_dialog_content = "That ringing... It must signal the start of the Spring Festival and a new year.",
  ui_story_5075_50751501_227_dialog_content = "PlayerName.",
  ui_story_5075_50751501_228_dialog_content = "PlayerName.",
  ui_story_5075_50751501_229_dialog_content = "PlayerName.",
  ui_story_5075_50751501_230_dialog_content = "PlayerName.",
  ui_story_5075_50751501_231_dialog_content = "Young friend.",
  ui_story_5075_50751501_232_dialog_content = "PlayerName.",
  ui_story_5075_50751501_233_dialog_content = "PlayerName.",
  ui_story_5075_50751501_234_dialog_content = "PlayerName.",
  ui_story_5075_50751501_235_dialog_content = "<size=45>Happy New Year!</size>"
}
return config
